import { useContext, useEffect, useMemo, useState } from "react";
import { UNSAFE_NavigationContext as NavigationContext } from "react-router-dom";
import { EnrollmentFormConfig, createDefaultSection, getDefaultEnrollmentConfig } from "@/lib/types/formBuilder";
import { SectionCard } from "./SectionCard";
import { JointEnrollmentSettings } from "./JointEnrollmentSettings";
import { FormPreview } from "./FormPreview";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Plus, Eye, Pencil, CalendarDays, RotateCcw, Tags, LayoutGrid } from "lucide-react";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import type { FormBuilderField, FormBuilderSection, FieldType } from "@/lib/types/formBuilder";
import { Textarea } from "@/components/ui/textarea";
import { getEnrollmentFormConfig, saveEnrollmentFormConfig } from "@/lib/api/enrollmentFormConfig";
import { Badge } from "@/components/ui/badge";
import { getStudentFields, type SchoolStudentField } from "@/lib/api/studentFields";

type Mode = "edit" | "preview";
const FORM_BUILDER_UNSAVED_KEY = "nexa:form-builder:unsaved";
const FORM_BUILDER_SAVE_REQUEST_EVENT = "nexa:form-builder:request-save";
const FORM_BUILDER_SAVE_RESULT_EVENT = "nexa:form-builder:save-result";

export function FormBuilder() {
  const [config, setConfig] = useState<EnrollmentFormConfig>(getDefaultEnrollmentConfig);
  const [mode, setMode] = useState<Mode>("edit");
  const [saving, setSaving] = useState(false);
  const [lastSavedSnapshot, setLastSavedSnapshot] = useState(() => JSON.stringify(getDefaultEnrollmentConfig()));
  const [schoolStudentFields, setSchoolStudentFields] = useState<SchoolStudentField[]>([]);

  const hasUnsavedChanges = useMemo(
    () => JSON.stringify(config) !== lastSavedSnapshot,
    [config, lastSavedSnapshot]
  );
  const navigationContext = useContext(NavigationContext);

  useEffect(() => {
    const loadConfig = async () => {
      const response = await getEnrollmentFormConfig();

      if (!response.success || !response.data?.config) {
        toast.error(response.error?.message || "No se pudo cargar el formulario guardado");
        return;
      }

      setConfig(response.data.config);
      setLastSavedSnapshot(JSON.stringify(response.data.config));
    };

    void loadConfig();
  }, []);

  useEffect(() => {
    const loadSchoolFields = async () => {
      try {
        const fields = await getStudentFields();
        setSchoolStudentFields(fields);
      } catch {
        setSchoolStudentFields([]);
      }
    };

    void loadSchoolFields();
  }, []);

  useEffect(() => {
    if (hasUnsavedChanges) {
      window.localStorage.setItem(FORM_BUILDER_UNSAVED_KEY, "1");
    } else {
      window.localStorage.removeItem(FORM_BUILDER_UNSAVED_KEY);
    }
  }, [hasUnsavedChanges]);

  useEffect(() => {
    const handleBeforeUnload = (event: BeforeUnloadEvent) => {
      if (!hasUnsavedChanges) {
        return;
      }

      event.preventDefault();
      event.returnValue = "";
    };

    window.addEventListener("beforeunload", handleBeforeUnload);
    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
      window.localStorage.removeItem(FORM_BUILDER_UNSAVED_KEY);
    };
  }, [hasUnsavedChanges]);

  useEffect(() => {
    if (!hasUnsavedChanges) {
      return;
    }

    const navigator = navigationContext.navigator as {
      block?: (blocker: (tx: { retry: () => void }) => void) => () => void;
    };

    if (typeof navigator.block !== "function") {
      return;
    }

    const unblock = navigator.block((tx) => {
      const confirmLeave = window.confirm(
        "Tienes cambios sin guardar en el Form Builder. Si sales ahora, se perderan. ¿Quieres continuar?"
      );

      if (!confirmLeave) {
        return;
      }

      window.localStorage.removeItem(FORM_BUILDER_UNSAVED_KEY);
      unblock();
      tx.retry();
    });

    return unblock;
  }, [hasUnsavedChanges, navigationContext]);

  useEffect(() => {
    if (!hasUnsavedChanges) {
      return;
    }

    const handleAnchorNavigation = (event: MouseEvent) => {
      const target = event.target as HTMLElement | null;
      if (!target) {
        return;
      }

      const anchor = target.closest("a[href]") as HTMLAnchorElement | null;
      if (!anchor) {
        return;
      }

      const href = anchor.getAttribute("href") || "";
      if (!href || href.startsWith("#") || anchor.target === "_blank") {
        return;
      }

      const isInternal = href.startsWith("/");
      if (!isInternal) {
        return;
      }

      const confirmLeave = window.confirm(
        "Tienes cambios sin guardar en el Form Builder. Si sales ahora, se perderan. ¿Quieres continuar?"
      );

      if (!confirmLeave) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }

      window.localStorage.removeItem(FORM_BUILDER_UNSAVED_KEY);
    };

    document.addEventListener("click", handleAnchorNavigation, true);
    return () => {
      document.removeEventListener("click", handleAnchorNavigation, true);
    };
  }, [hasUnsavedChanges]);

  const updateSection = (index: number, section: FormBuilderSection) => {
    const sections = [...config.sections];
    sections[index] = section;
    setConfig({ ...config, sections });
  };

  const deleteSection = (index: number) => {
    setConfig({ ...config, sections: config.sections.filter((_, i) => i !== index) });
  };

  const moveSection = (index: number, direction: "up" | "down") => {
    const sections = [...config.sections];
    const target = direction === "up" ? index - 1 : index + 1;
    if (target < 0 || target >= sections.length) return;
    [sections[index], sections[target]] = [sections[target], sections[index]];
    setConfig({ ...config, sections });
  };

  const addSection = () => {
    setConfig({ ...config, sections: [...config.sections, createDefaultSection()] });
  };

  const handleSave = async (): Promise<boolean> => {
    setSaving(true);

    const response = await saveEnrollmentFormConfig(config);
    setSaving(false);

    if (!response.success) {
      toast.error(response.error?.message || "No se pudo guardar el formulario");
      return false;
    }

    setLastSavedSnapshot(JSON.stringify(config));
    toast.success("Formulario guardado correctamente");
    return true;
  };

  useEffect(() => {
    const onRequestSave = () => {
      void (async () => {
        const success = await handleSave();
        window.dispatchEvent(new CustomEvent(FORM_BUILDER_SAVE_RESULT_EVENT, { detail: { success } }));
      })();
    };

    window.addEventListener(FORM_BUILDER_SAVE_REQUEST_EVENT, onRequestSave);
    return () => {
      window.removeEventListener(FORM_BUILDER_SAVE_REQUEST_EVENT, onRequestSave);
    };
  }, [handleSave]);

  const handleReset = () => {
    setConfig(getDefaultEnrollmentConfig());
    toast.info("Formulario restaurado a valores por defecto");
  };

  const sectionIndexForStudentData = useMemo(() => {
    const byId = config.sections.findIndex((section) => section.id.toLowerCase().includes("student"));
    if (byId >= 0) return byId;

    const byTitle = config.sections.findIndex((section) => section.title.toLowerCase().includes("alumno"));
    if (byTitle >= 0) return byTitle;

    return 0;
  }, [config.sections]);

  const existingFieldIds = useMemo(() => {
    return new Set(config.sections.flatMap((section) => section.fields.map((field) => field.id)));
  }, [config.sections]);

  const toFormFieldType = (type: SchoolStudentField["type"]): FieldType => {
    if (type === "number") return "number";
    if (type === "date") return "date";
    return "text";
  };

  const makeSchoolFieldFormId = (field: SchoolStudentField) => field.key;

  const makeSchoolFieldFormField = (field: SchoolStudentField): FormBuilderField => ({
    id: makeSchoolFieldFormId(field),
    type: toFormFieldType(field.type),
    label: field.label,
    placeholder: `Ingresa ${field.label.toLowerCase()}`,
    required: field.required,
  });

  const requiredSchoolFieldsNotIncluded = useMemo(() => {
    return schoolStudentFields.filter((field) => field.required && !existingFieldIds.has(makeSchoolFieldFormId(field)));
  }, [schoolStudentFields, existingFieldIds]);

  const addSchoolFieldToForm = (field: SchoolStudentField) => {
    const fieldId = makeSchoolFieldFormId(field);
    if (existingFieldIds.has(fieldId)) {
      toast.info(`El campo ${field.label} ya esta incluido en el formulario`);
      return;
    }

    if (config.sections.length === 0) {
      toast.error("No hay secciones disponibles para agregar el campo");
      return;
    }

    setConfig((prev) => {
      const sections = [...prev.sections];
      const target = sections[sectionIndexForStudentData] ?? sections[0];
      const targetIndex = sections.indexOf(target);
      const nextFields = [...target.fields, makeSchoolFieldFormField(field)];
      sections[targetIndex] = { ...target, fields: nextFields };
      return { ...prev, sections };
    });

    toast.success(`Campo ${field.label} agregado al formulario`);
  };

  const addAllRequiredSchoolFieldsToForm = () => {
    if (requiredSchoolFieldsNotIncluded.length === 0) {
      toast.info("No hay campos requeridos pendientes de agregar");
      return;
    }

    if (config.sections.length === 0) {
      toast.error("No hay secciones disponibles para agregar campos");
      return;
    }

    setConfig((prev) => {
      const sections = [...prev.sections];
      const target = sections[sectionIndexForStudentData] ?? sections[0];
      const targetIndex = sections.indexOf(target);
      const knownIds = new Set(target.fields.map((field) => field.id));
      const fieldsToAdd = requiredSchoolFieldsNotIncluded
        .filter((field) => !knownIds.has(makeSchoolFieldFormId(field)))
        .map((field) => makeSchoolFieldFormField(field));

      if (fieldsToAdd.length === 0) {
        return prev;
      }

      sections[targetIndex] = {
        ...target,
        fields: [...target.fields, ...fieldsToAdd],
      };

      return { ...prev, sections };
    });

    toast.success(`Se agregaron ${requiredSchoolFieldsNotIncluded.length} campo(s) requeridos al formulario`);
  };

  return (
    <div className="space-y-6">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="flex items-center rounded-lg border border-border bg-card p-0.5">
          <button
            onClick={() => setMode("edit")}
            className={cn(
              "flex items-center gap-1.5 rounded-md px-3 py-2 text-xs font-medium transition-colors",
              mode === "edit" ? "bg-accent text-accent-foreground" : "text-muted-foreground hover:text-foreground"
            )}
          >
            <Pencil className="h-3.5 w-3.5" />
            Editor
          </button>
          <button
            onClick={() => setMode("preview")}
            className={cn(
              "flex items-center gap-1.5 rounded-md px-3 py-2 text-xs font-medium transition-colors",
              mode === "preview" ? "bg-accent text-accent-foreground" : "text-muted-foreground hover:text-foreground"
            )}
          >
            <Eye className="h-3.5 w-3.5" />
            Vista Previa
          </button>
        </div>

        <div className="flex items-center gap-2 ml-auto">
          {hasUnsavedChanges ? (
            <span className="text-xs font-medium text-warning">Cambios sin guardar</span>
          ) : null}
          <Button variant="outline" size="sm" onClick={handleReset}>
            <RotateCcw className="h-3.5 w-3.5 mr-1" />
            Restaurar
          </Button>
          <Button size="sm" onClick={handleSave} disabled={saving}>
            Guardar Formulario
          </Button>
        </div>
      </div>

      {mode === "edit" ? (
        <div className="space-y-6">
          {/* Schedule toggle */}
          <div className="rounded-xl border border-border bg-card shadow-soft p-5">
            <div className="flex items-center gap-3">
              <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent">
                <CalendarDays className="h-4.5 w-4.5 text-accent-foreground" />
              </div>
              <div className="flex-1">
                <h3 className="text-sm font-semibold text-foreground">Selección de Clases por Horario</h3>
                <p className="text-xs text-muted-foreground">
                  Incluir el horario semanal para que los alumnos seleccionen sus clases
                </p>
              </div>
              <Switch
                checked={config.includeSchedule}
                onCheckedChange={(checked) => setConfig({ ...config, includeSchedule: checked })}
              />
            </div>
          </div>

          {/* Pricing toggle */}
          <div className="rounded-xl border border-border bg-card shadow-soft p-5">
            <div className="flex items-center gap-3">
              <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent">
                <Tags className="h-4.5 w-4.5 text-accent-foreground" />
              </div>
              <div className="flex-1">
                <h3 className="text-sm font-semibold text-foreground">Mostrar Tarifas y Bonos</h3>
                <p className="text-xs text-muted-foreground">
                  Mostrar resumen dinámico de precio, ahorro y cercanía a bonos en la matrícula pública
                </p>
              </div>
              <Switch
                checked={config.includePricing ?? true}
                onCheckedChange={(checked) => setConfig({ ...config, includePricing: checked })}
              />
            </div>
          </div>

          {/* Schedule display settings */}
          {(() => {
            const scheduleSettings = config.scheduleSettings ?? {
              preferredView: "calendar" as const,
              recurringSelectionMode: "linked" as const,
              recurringClassOverrides: [] as string[],
              calendarFields: {
                showDiscipline: true,
                showCategory: false,
                showRoom: true,
                showCapacity: true,
                showPrice: true,
                showSelectedStudents: true,
              },
            };
            const updateSchedule = (next: typeof scheduleSettings) =>
              setConfig({ ...config, scheduleSettings: next });
            return (
              <div className="rounded-xl border border-border bg-card shadow-soft p-5 space-y-4">
                <div className="flex items-center gap-3">
                  <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent">
                    <LayoutGrid className="h-4.5 w-4.5 text-accent-foreground" />
                  </div>
                  <div className="flex-1">
                    <h3 className="text-sm font-semibold text-foreground">Configuración del Horario</h3>
                    <p className="text-xs text-muted-foreground">
                      Vista por defecto, selección de clases recurrentes y campos visibles en tarjetas del calendario
                    </p>
                  </div>
                </div>

                <div className="grid gap-3 sm:grid-cols-2 pl-12">
                  <div className="space-y-1">
                    <Label className="text-xs text-muted-foreground">Vista preferida</Label>
                    <div className="flex rounded-md border overflow-hidden">
                      <button
                        type="button"
                        className={`flex-1 text-xs px-3 py-2 ${scheduleSettings.preferredView === "calendar" ? "bg-primary text-primary-foreground" : "bg-background"}`}
                        onClick={() => updateSchedule({ ...scheduleSettings, preferredView: "calendar" })}
                      >
                        Calendario
                      </button>
                      <button
                        type="button"
                        className={`flex-1 text-xs px-3 py-2 ${scheduleSettings.preferredView === "list" ? "bg-primary text-primary-foreground" : "bg-background"}`}
                        onClick={() => updateSchedule({ ...scheduleSettings, preferredView: "list" })}
                      >
                        Lista
                      </button>
                    </div>
                  </div>

                  <div className="space-y-1">
                    <Label className="text-xs text-muted-foreground">Clases recurrentes</Label>
                    <div className="flex rounded-md border overflow-hidden">
                      <button
                        type="button"
                        className={`flex-1 text-xs px-3 py-2 ${scheduleSettings.recurringSelectionMode === "linked" ? "bg-primary text-primary-foreground" : "bg-background"}`}
                        onClick={() => updateSchedule({ ...scheduleSettings, recurringSelectionMode: "linked" })}
                      >
                        Días enlazados
                      </button>
                      <button
                        type="button"
                        className={`flex-1 text-xs px-3 py-2 ${scheduleSettings.recurringSelectionMode === "single_day" ? "bg-primary text-primary-foreground" : "bg-background"}`}
                        onClick={() => updateSchedule({ ...scheduleSettings, recurringSelectionMode: "single_day" })}
                      >
                        Día individual
                      </button>
                    </div>
                  </div>
                </div>

                <div className="space-y-2 pl-12">
                  <Label className="text-xs text-muted-foreground">
                    IDs de clase para anular el modo por defecto (separados por coma)
                  </Label>
                  <Textarea
                    rows={2}
                    className="text-xs"
                    placeholder="uuid-1, uuid-2"
                    value={scheduleSettings.recurringClassOverrides.join(", ")}
                    onChange={(e) => {
                      const ids = e.target.value
                        .split(",")
                        .map((v) => v.trim())
                        .filter(Boolean);
                      updateSchedule({ ...scheduleSettings, recurringClassOverrides: ids });
                    }}
                  />
                  <p className="text-[11px] text-muted-foreground">
                    Si el modo es "Días enlazados", estas clases permitirán selección por día individual. Si el modo es
                    "Día individual", estas clases quedarán enlazadas.
                  </p>
                </div>

                <div className="space-y-2 pl-12">
                  <Label className="text-xs text-muted-foreground">Campos visibles en tarjetas del calendario</Label>
                  <div className="grid gap-2 sm:grid-cols-2">
                    {([
                      ["showDiscipline", "Disciplina"],
                      ["showCategory", "Categoría"],
                      ["showRoom", "Aula"],
                      ["showCapacity", "Capacidad"],
                      ["showPrice", "Precio"],
                      ["showSelectedStudents", "Alumnos seleccionados"],
                    ] as const).map(([key, label]) => (
                      <div key={key} className="flex items-center justify-between rounded-md border px-3 py-2">
                        <span className="text-xs">{label}</span>
                        <Switch
                          checked={Boolean(scheduleSettings.calendarFields[key])}
                          onCheckedChange={(checked) =>
                            updateSchedule({
                              ...scheduleSettings,
                              calendarFields: {
                                ...scheduleSettings.calendarFields,
                                [key]: Boolean(checked),
                              },
                            })
                          }
                        />
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            );
          })()}

          {/* Joint enrollment */}
          <JointEnrollmentSettings
            config={config.jointEnrollment}
            onChange={(jointEnrollment) => setConfig({ ...config, jointEnrollment })}
          />

          <div className="rounded-xl border border-border bg-card shadow-soft p-5 space-y-3">
            <div className="flex flex-wrap items-start justify-between gap-2">
              <div>
                <h3 className="text-sm font-semibold text-foreground">Campos personalizados de alumnos (escuela)</h3>
                <p className="text-xs text-muted-foreground">
                  Estos campos vienen de la configuracion de tu escuela. Puedes agregarlos al formulario
                  publico para pedirlos durante la inscripcion.
                </p>
              </div>
              <Button
                size="sm"
                variant="outline"
                onClick={addAllRequiredSchoolFieldsToForm}
                disabled={requiredSchoolFieldsNotIncluded.length === 0}
              >
                Agregar todos los requeridos
              </Button>
            </div>

            {schoolStudentFields.length === 0 ? (
              <p className="text-xs text-muted-foreground">No hay campos personalizados configurados para esta escuela.</p>
            ) : (
              <div className="space-y-2">
                {schoolStudentFields.map((field) => {
                  const included = existingFieldIds.has(makeSchoolFieldFormId(field));
                  return (
                    <div key={field.id} className="flex flex-wrap items-center justify-between gap-2 rounded-md border px-3 py-2">
                      <div className="space-y-1">
                        <p className="text-sm font-medium">
                          {field.label}
                          <span className="ml-1 text-xs text-muted-foreground">({field.key})</span>
                        </p>
                        <div className="flex flex-wrap items-center gap-1.5">
                          <Badge variant="outline" className="text-[10px]">{field.type}</Badge>
                          {field.required ? <Badge variant="outline" className="text-[10px]">Requerido</Badge> : null}
                          {field.visibleInTable ? <Badge variant="outline" className="text-[10px]">Visible en tabla</Badge> : null}
                          {included ? <Badge className="text-[10px]">Incluido en formulario</Badge> : null}
                        </div>
                      </div>
                      <Button
                        size="sm"
                        variant={included ? "outline" : "default"}
                        disabled={included}
                        onClick={() => addSchoolFieldToForm(field)}
                      >
                        {included ? "Ya agregado" : "Agregar al formulario"}
                      </Button>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Sections */}
          <div className="space-y-4">
            {config.sections.map((section, i) => (
              <SectionCard
                key={section.id}
                section={section}
                index={i}
                totalSections={config.sections.length}
                allSections={config.sections}
                onUpdate={(s) => updateSection(i, s)}
                onDelete={() => deleteSection(i)}
                onMove={(dir) => moveSection(i, dir)}
              />
            ))}
          </div>

          <Button variant="outline" className="w-full border-dashed" onClick={addSection}>
            <Plus className="h-4 w-4 mr-2" />
            Añadir Sección
          </Button>
        </div>
      ) : (
        <div className="max-w-2xl mx-auto">
          <div className="mb-4 rounded-lg bg-accent/50 border border-accent px-4 py-2.5">
            <p className="text-xs text-accent-foreground">
              <Eye className="inline h-3 w-3 mr-1 -mt-0.5" />
              Vista previa del formulario tal como lo verán los alumnos. Las condiciones lógicas se evalúan en tiempo real.
            </p>
          </div>
          <FormPreview config={config} />
        </div>
      )}
    </div>
  );
}

import { EnrollmentFormConfig } from "@/lib/types/formBuilder";
import { useState } from "react";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Asterisk, ArrowLeft, ArrowRight, Send, Users, Plus, Trash2, CalendarDays } from "lucide-react";
import { WeeklySchedule } from "@/components/schedule/WeeklySchedule";
import { MOCK_CLASSES } from "@/lib/data/mockClasses";
import { ClassCardData } from "@/components/cards/ClassCard";

interface FormPreviewProps {
  config: EnrollmentFormConfig;
}

interface StudentEnrollment {
  id: string;
  label: string;
  values: Record<string, any>;
  selectedClassIds: string[];
}

export function FormPreview({ config }: FormPreviewProps) {
  const [students, setStudents] = useState<StudentEnrollment[]>([
    { id: "s1", label: "Alumno 1", values: {}, selectedClassIds: [] },
  ]);
  const [activeStudentIndex, setActiveStudentIndex] = useState(0);
  const [step, setStep] = useState(0);
  const [showSummary, setShowSummary] = useState(false);

  const activeStudent = students[activeStudentIndex];

  const resolveDateReference = (rawValue: string) => {
    if (rawValue === "today") {
      const now = new Date();
      now.setHours(0, 0, 0, 0);
      return now;
    }

    const minusYearsMatch = rawValue.match(/^today_minus_(\d+)y$/);
    if (minusYearsMatch) {
      const years = Number(minusYearsMatch[1]);
      if (Number.isFinite(years)) {
        const now = new Date();
        now.setHours(0, 0, 0, 0);
        now.setFullYear(now.getFullYear() - years);
        return now;
      }
    }

    const parsed = new Date(rawValue);
    if (isNaN(parsed.getTime())) return null;
    parsed.setHours(0, 0, 0, 0);
    return parsed;
  };

  // Steps: sections + optional schedule
  const visibleSections = config.sections.filter((section) => {
    if (!section.conditions?.length) return true;
    // Evaluate conditions (simplified: check current student values)
    return section.conditions.every((cond) => {
      const val = activeStudent.values[cond.sourceFieldId];
      if (cond.operator === "is_not_empty") return val !== undefined && val !== "";
      if (cond.operator === "is_empty") return val === undefined || val === "";
      if (cond.operator === "equals") return String(val) === cond.value;
      if (cond.operator === "not_equals") return String(val) !== cond.value;
      if (cond.operator === "date_before" || cond.operator === "date_after") {
        const sourceDate = resolveDateReference(String(val));
        const targetDate = resolveDateReference(cond.value);
        if (!sourceDate || !targetDate) return false;
        return cond.operator === "date_before"
          ? sourceDate.getTime() < targetDate.getTime()
          : sourceDate.getTime() > targetDate.getTime();
      }
      if (cond.operator === "less_than") {
        // Handle date fields (age calculation)
        if (cond.sourceFieldId.includes("birthdate") || cond.sourceFieldId.includes("date")) {
          const birthDate = new Date(val);
          if (isNaN(birthDate.getTime())) return false;
          const age = Math.floor((Date.now() - birthDate.getTime()) / (365.25 * 24 * 60 * 60 * 1000));
          return age < parseFloat(cond.value);
        }
        return parseFloat(val) < parseFloat(cond.value);
      }
      if (cond.operator === "greater_than") return parseFloat(val) > parseFloat(cond.value);
      if (cond.operator === "contains") return String(val).includes(cond.value);
      return true;
    });
  });

  const allSteps = [
    ...visibleSections.map((s) => ({ id: s.id, title: s.title, type: "form" as const })),
    ...(config.includeSchedule ? [{ id: "_schedule", title: "Selección de Clases", type: "schedule" as const }] : []),
  ];

  const currentStep = allSteps[step];
  const isLastStep = step === allSteps.length - 1;

  const setValue = (fieldId: string, value: any) => {
    setStudents((prev) =>
      prev.map((s, i) =>
        i === activeStudentIndex ? { ...s, values: { ...s.values, [fieldId]: value } } : s
      )
    );
  };

  const toggleClass = (classId: string) => {
    setStudents((prev) =>
      prev.map((s, i) =>
        i === activeStudentIndex
          ? {
              ...s,
              selectedClassIds: s.selectedClassIds.includes(classId)
                ? s.selectedClassIds.filter((id) => id !== classId)
                : [...s.selectedClassIds, classId],
            }
          : s
      )
    );
  };

  const addStudent = () => {
    if (!config.jointEnrollment.enabled) return;
    if (students.length >= config.jointEnrollment.maxStudents) return;
    const idx = students.length + 1;
    setStudents((prev) => [...prev, { id: `s${idx}`, label: `Alumno ${idx}`, values: {}, selectedClassIds: [] }]);
    setActiveStudentIndex(students.length);
    setStep(0);
  };

  const removeStudent = (index: number) => {
    if (students.length <= 1) return;
    setStudents((prev) => prev.filter((_, i) => i !== index));
    setActiveStudentIndex((prev) => Math.min(prev, students.length - 2));
  };

  const selectedClassesForStudent = (student: StudentEnrollment): ClassCardData[] =>
    MOCK_CLASSES.filter((c) => student.selectedClassIds.includes(c.id));

  const totalPrice = students.reduce(
    (sum, s) => sum + selectedClassesForStudent(s).reduce((cs, c) => cs + c.price, 0),
    0
  );

  if (showSummary) {
    return (
      <div className="space-y-6 animate-fade-in">
        <h3 className="text-base font-semibold text-foreground">Resumen de Matrícula</h3>
        {students.map((student, si) => {
          const classes = selectedClassesForStudent(student);
          const subtotal = classes.reduce((s, c) => s + c.price, 0);
          return (
            <div key={student.id} className="rounded-lg border border-border bg-card p-4 space-y-3">
              <div className="flex items-center gap-2">
                <div className="flex h-7 w-7 items-center justify-center rounded-full bg-primary text-primary-foreground text-xs font-bold">
                  {si + 1}
                </div>
                <span className="text-sm font-medium text-foreground">
                  {student.values.student_name || student.label}
                </span>
                <span className="text-xs text-muted-foreground ml-auto">{classes.length} clases · ${subtotal}</span>
              </div>
              <div className="grid gap-2 sm:grid-cols-2">
                {classes.map((cls) => (
                  <div key={cls.id} className="flex items-center gap-2 rounded-md bg-muted/50 px-3 py-2 text-xs">
                    <CalendarDays className="h-3 w-3 text-muted-foreground shrink-0" />
                    <span className="font-medium text-foreground truncate">{cls.name}</span>
                    <span className="text-muted-foreground ml-auto whitespace-nowrap">{cls.day} · {cls.time}</span>
                    <span className="font-medium text-foreground">€{cls.price}</span>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
        <div className="flex justify-between items-center rounded-lg border border-border bg-accent/50 p-4">
          <span className="text-sm font-semibold text-foreground">Total</span>
          <span className="text-lg font-bold text-foreground">€{totalPrice}</span>
        </div>
        <div className="flex gap-3">
          <Button variant="outline" onClick={() => setShowSummary(false)}>
            <ArrowLeft className="h-4 w-4 mr-1" /> Volver
          </Button>
          <Button className="flex-1">
            <Send className="h-4 w-4 mr-1" /> Confirmar Matrícula
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Student tabs for joint enrollment */}
      {config.jointEnrollment.enabled && (
        <div className="flex items-center gap-2 flex-wrap">
          {students.map((s, i) => (
            <button
              key={s.id}
              onClick={() => { setActiveStudentIndex(i); setStep(0); }}
              className={cn(
                "flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-medium transition-colors",
                i === activeStudentIndex
                  ? "bg-primary text-primary-foreground"
                  : "bg-muted text-muted-foreground hover:bg-accent"
              )}
            >
              {s.values.student_name || s.label}
              {students.length > 1 && (
                <button
                  type="button"
                  onClick={(e) => { e.stopPropagation(); removeStudent(i); }}
                  className="ml-1 hover:text-destructive"
                >
                  <Trash2 className="h-3 w-3" />
                </button>
              )}
            </button>
          ))}
          {students.length < config.jointEnrollment.maxStudents && (
            <button
              onClick={addStudent}
              className="flex items-center gap-1 rounded-full border border-dashed border-border px-3 py-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
            >
              <Plus className="h-3 w-3" /> Añadir alumno
            </button>
          )}
        </div>
      )}

      {/* Step indicator */}
      <div className="flex items-center gap-1 overflow-x-auto pb-1">
        {allSteps.map((s, i) => (
          <button
            key={s.id}
            onClick={() => i < step && setStep(i)}
            className={cn(
              "flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-medium transition-colors whitespace-nowrap",
              i === step ? "bg-primary text-primary-foreground" : i < step ? "bg-accent text-accent-foreground cursor-pointer" : "bg-muted text-muted-foreground"
            )}
          >
            <span className="flex h-5 w-5 items-center justify-center rounded-full bg-background/20 text-[10px] font-bold">{i + 1}</span>
            <span className="hidden sm:inline">{s.title}</span>
          </button>
        ))}
      </div>

      {/* Step Content */}
      <div className="animate-fade-in" key={`${activeStudent.id}-${currentStep?.id}`}>
        {currentStep?.type === "schedule" ? (
          <WeeklySchedule
            classes={MOCK_CLASSES}
            selectedClassIds={activeStudent.selectedClassIds}
            onToggleClass={toggleClass}
          />
        ) : currentStep ? (
          <div className="rounded-lg border border-border bg-card p-5 space-y-4">
            <div>
              <h3 className="text-sm font-semibold text-foreground">{currentStep.title}</h3>
              {visibleSections.find((s) => s.id === currentStep.id)?.description && (
                <p className="text-xs text-muted-foreground mt-1">
                  {visibleSections.find((s) => s.id === currentStep.id)?.description}
                </p>
              )}
            </div>
            <div className="space-y-4">
              {visibleSections
                .find((s) => s.id === currentStep.id)
                ?.fields.filter((field) => {
                  if (!field.conditions?.length) return true;
                  return field.conditions.every((cond) => {
                    const val = activeStudent.values[cond.sourceFieldId];
                    if (cond.operator === "equals") return String(val) === cond.value;
                    if (cond.operator === "not_equals") return String(val) !== cond.value;
                    if (cond.operator === "is_not_empty") return val !== undefined && val !== "";
                    if (cond.operator === "is_empty") return !val;
                    if (cond.operator === "less_than") {
                      if (cond.sourceFieldId.includes("birthdate")) {
                        const bd = new Date(val);
                        if (isNaN(bd.getTime())) return false;
                        return Math.floor((Date.now() - bd.getTime()) / (365.25 * 24 * 60 * 60 * 1000)) < parseFloat(cond.value);
                      }
                      return parseFloat(val) < parseFloat(cond.value);
                    }
                    if (cond.operator === "greater_than") return parseFloat(val) > parseFloat(cond.value);
                    if (cond.operator === "contains") return String(val).includes(cond.value);
                    if (cond.operator === "date_before" || cond.operator === "date_after") {
                      const sourceDate = resolveDateReference(String(val));
                      const targetDate = resolveDateReference(cond.value);
                      if (!sourceDate || !targetDate) return false;
                      return cond.operator === "date_before"
                        ? sourceDate.getTime() < targetDate.getTime()
                        : sourceDate.getTime() > targetDate.getTime();
                    }
                    return true;
                  });
                })
                .map((field) => (
                  <div key={field.id} className="space-y-1.5">
                    {field.type !== "checkbox" && field.type !== "info" ? (
                      <Label className="text-xs font-medium text-foreground">
                        {field.label}
                        {field.required && <Asterisk className="inline h-2.5 w-2.5 text-destructive ml-0.5" />}
                      </Label>
                    ) : field.type === "checkbox" && field.placeholder ? (
                      <Label className="text-xs font-medium text-foreground">
                        {field.label}
                        {field.required && <Asterisk className="inline h-2.5 w-2.5 text-destructive ml-0.5" />}
                      </Label>
                    ) : null}
                    {field.type === "checkbox" ? (
                      <div className="flex items-center gap-2">
                        <Checkbox
                          checked={!!activeStudent.values[field.id]}
                          onCheckedChange={(v) => setValue(field.id, v)}
                        />
                        <span className="text-xs text-muted-foreground">{field.placeholder || field.label}</span>
                      </div>
                    ) : field.type === "info" ? (
                      <div className="rounded-md border border-border bg-muted/30 px-3 py-2 text-xs text-muted-foreground">
                        {field.placeholder || field.label}
                      </div>
                    ) : field.type === "textarea" ? (
                      <Textarea
                        value={activeStudent.values[field.id] || ""}
                        onChange={(e) => setValue(field.id, e.target.value)}
                        placeholder={field.placeholder}
                        className="text-xs resize-none"
                        rows={3}
                      />
                    ) : field.type === "select" ? (
                      <Select value={activeStudent.values[field.id] || ""} onValueChange={(v) => setValue(field.id, v)}>
                        <SelectTrigger className="text-xs h-9"><SelectValue placeholder="Seleccionar..." /></SelectTrigger>
                        <SelectContent>
                          {field.options?.map((o) => (
                            <SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    ) : field.type === "file" ? (
                      <div className="rounded-lg border border-dashed border-border py-4 text-center text-xs text-muted-foreground">
                        Arrastra o haz clic para subir ({field.accept})
                      </div>
                    ) : (
                      <Input
                        type={field.type}
                        value={activeStudent.values[field.id] || ""}
                        onChange={(e) => setValue(field.id, e.target.value)}
                        placeholder={field.placeholder}
                        className="text-xs h-9"
                      />
                    )}
                  </div>
                ))}
            </div>
          </div>
        ) : null}
      </div>

      {/* Navigation */}
      <div className="flex items-center justify-between pt-1">
        <Button variant="outline" onClick={() => setStep((s) => Math.max(s - 1, 0))} disabled={step === 0} className={cn(step === 0 && "invisible")}>
          <ArrowLeft className="h-4 w-4 mr-1" /> Anterior
        </Button>
        {isLastStep ? (
          <Button onClick={() => setShowSummary(true)}>
            Ver Resumen <ArrowRight className="h-4 w-4 ml-1" />
          </Button>
        ) : (
          <Button onClick={() => setStep((s) => Math.min(s + 1, allSteps.length - 1))}>
            Siguiente <ArrowRight className="h-4 w-4 ml-1" />
          </Button>
        )}
      </div>
    </div>
  );
}

import { FormFieldConfig } from "@/lib/types/formSchema";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { FileUploader } from "@/components/forms/FileUploader";
import { cn } from "@/lib/utils";

interface DynamicFieldProps {
  field: FormFieldConfig;
  value: any;
  onChange: (value: any) => void;
  error?: string;
}

export function DynamicField({ field, value, onChange, error }: DynamicFieldProps) {
  const id = field.id;

  if (field.type === "checkbox") {
    return (
      <div className="flex items-start gap-3">
        <Checkbox
          id={id}
          checked={!!value}
          onCheckedChange={(checked) => onChange(checked)}
          className="mt-0.5"
        />
        <div className="space-y-1">
          <Label htmlFor={id} className="text-sm font-normal text-foreground cursor-pointer leading-snug">
            {field.label}
            {field.required && <span className="text-destructive ml-0.5">*</span>}
          </Label>
          {error && <p className="text-xs text-destructive">{error}</p>}
        </div>
      </div>
    );
  }

  if (field.type === "file") {
    return (
      <div className="space-y-2">
        <Label className="text-sm font-medium text-foreground">
          {field.label}
          {field.required && <span className="text-destructive ml-0.5">*</span>}
        </Label>
        <FileUploader
          accept={field.accept}
          value={value}
          onChange={onChange}
        />
        {error && <p className="text-xs text-destructive">{error}</p>}
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <Label htmlFor={id} className="text-sm font-medium text-foreground">
        {field.label}
        {field.required && <span className="text-destructive ml-0.5">*</span>}
      </Label>

      {field.type === "textarea" ? (
        <Textarea
          id={id}
          placeholder={field.placeholder}
          value={value || ""}
          onChange={(e) => onChange(e.target.value)}
          maxLength={field.maxLength}
          className={cn("resize-none", error && "border-destructive")}
          rows={3}
        />
      ) : field.type === "select" ? (
        <Select value={value || ""} onValueChange={onChange}>
          <SelectTrigger id={id} className={cn(error && "border-destructive")}>
            <SelectValue placeholder="Seleccionar..." />
          </SelectTrigger>
          <SelectContent>
            {field.options?.map((opt) => (
              <SelectItem key={opt.value} value={opt.value}>
                {opt.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      ) : (
        <Input
          id={id}
          type={field.type}
          placeholder={field.placeholder}
          value={value || ""}
          onChange={(e) => onChange(e.target.value)}
          maxLength={field.maxLength}
          className={cn(error && "border-destructive")}
        />
      )}

      {error && <p className="text-xs text-destructive">{error}</p>}
    </div>
  );
}

import { useState, useCallback } from "react";
import { FormSectionConfig, FormFieldConfig } from "@/lib/types/formSchema";
import { FormSection } from "@/components/forms/FormSection";
import { DynamicField } from "@/components/forms/DynamicField";
import { EnrollmentSummary } from "@/components/forms/EnrollmentSummary";
import { ClassCardData } from "@/components/cards/ClassCard";
import { Button } from "@/components/ui/button";
import { CheckCircle, ArrowLeft, ArrowRight, Send } from "lucide-react";
import { cn } from "@/lib/utils";
import { toast } from "sonner";

interface EnrollmentFormProps {
  schema: FormSectionConfig[];
  selectedClasses: ClassCardData[];
  onRemoveClass: (id: string) => void;
}

export function EnrollmentForm({ schema, selectedClasses, onRemoveClass }: EnrollmentFormProps) {
  const [values, setValues] = useState<Record<string, any>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [step, setStep] = useState(0);
  const [submitted, setSubmitted] = useState(false);

  // Steps: each form section + class summary as first step
  const allSteps = [
    { id: "_classes", title: "Clases Seleccionadas" },
    ...schema,
  ];

  const currentStep = allSteps[step];
  const isLastStep = step === allSteps.length - 1;
  const isFirstStep = step === 0;

  const setValue = useCallback((fieldId: string, value: any) => {
    setValues((prev) => ({ ...prev, [fieldId]: value }));
    setErrors((prev) => {
      const next = { ...prev };
      delete next[fieldId];
      return next;
    });
  }, []);

  const validateCurrentStep = useCallback(() => {
    if (currentStep.id === "_classes") {
      if (selectedClasses.length === 0) {
        toast.error("Selecciona al menos una clase para continuar.");
        return false;
      }
      return true;
    }

    const section = schema.find((s) => s.id === currentStep.id);
    if (!section) return true;

    const newErrors: Record<string, string> = {};
    for (const field of section.fields) {
      const val = values[field.id];
      if (field.required) {
        if (field.type === "checkbox" && !val) {
          newErrors[field.id] = "Este campo es obligatorio";
        } else if (field.type !== "checkbox" && (!val || (typeof val === "string" && val.trim() === ""))) {
          newErrors[field.id] = "Este campo es obligatorio";
        }
      }
      if (field.type === "email" && val && typeof val === "string" && val.trim()) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(val.trim())) {
          newErrors[field.id] = "Ingresá un correo electrónico válido";
        }
      }
      if (field.maxLength && typeof val === "string" && val.length > field.maxLength) {
        newErrors[field.id] = `Máximo ${field.maxLength} caracteres`;
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }, [currentStep, schema, values, selectedClasses]);

  const handleNext = useCallback(() => {
    if (validateCurrentStep()) {
      setStep((s) => Math.min(s + 1, allSteps.length - 1));
    }
  }, [validateCurrentStep, allSteps.length]);

  const handleBack = useCallback(() => {
    setStep((s) => Math.max(s - 1, 0));
  }, []);

  const handleSubmit = useCallback(() => {
    if (!validateCurrentStep()) return;

    // TODO: call createEnrollment() API
    console.log("Enrollment submitted:", { values, classIds: selectedClasses.map((c) => c.id) });
    setSubmitted(true);
    toast.success("¡Inscripción enviada exitosamente!");
  }, [validateCurrentStep, values, selectedClasses]);

  if (submitted) {
    return (
      <div className="rounded-lg border border-border bg-card p-10 shadow-soft text-center animate-fade-in">
        <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-accent">
          <CheckCircle className="h-7 w-7 text-primary" />
        </div>
        <h2 className="text-xl font-semibold text-foreground">¡Inscripción Enviada!</h2>
        <p className="mt-2 text-sm text-muted-foreground max-w-sm mx-auto">
          Tu solicitud de inscripción fue recibida. Te contactaremos pronto para confirmar los detalles y el pago.
        </p>
        <p className="mt-4 text-xs text-muted-foreground">
          Clases seleccionadas: {selectedClasses.length} · Total: €{selectedClasses.reduce((s, c) => s + c.price, 0)}
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Step indicator */}
      <div className="flex items-center gap-1 overflow-x-auto pb-1">
        {allSteps.map((s, i) => (
          <button
            key={s.id}
            onClick={() => i < step && setStep(i)}
            className={cn(
              "flex items-center gap-2 rounded-full px-3 py-1.5 text-xs font-medium transition-colors whitespace-nowrap",
              i === step
                ? "bg-primary text-primary-foreground"
                : i < step
                ? "bg-accent text-accent-foreground cursor-pointer hover:bg-accent/80"
                : "bg-muted text-muted-foreground"
            )}
          >
            <span className="flex h-5 w-5 items-center justify-center rounded-full bg-background/20 text-[10px] font-bold">
              {i + 1}
            </span>
            <span className="hidden sm:inline">{s.title}</span>
          </button>
        ))}
      </div>

      {/* Step content */}
      <div className="animate-fade-in" key={currentStep.id}>
        {currentStep.id === "_classes" ? (
          <EnrollmentSummary
            selectedClasses={selectedClasses}
            onRemoveClass={onRemoveClass}
          />
        ) : (
          <FormSection
            title={currentStep.title}
            description={(currentStep as FormSectionConfig).description}
          >
            {(currentStep as FormSectionConfig).fields.map((field) => (
              <DynamicField
                key={field.id}
                field={field}
                value={values[field.id]}
                onChange={(val) => setValue(field.id, val)}
                error={errors[field.id]}
              />
            ))}
          </FormSection>
        )}
      </div>

      {/* Navigation */}
      <div className="flex items-center justify-between pt-2">
        <Button
          variant="outline"
          onClick={handleBack}
          disabled={isFirstStep}
          className={cn(isFirstStep && "invisible")}
        >
          <ArrowLeft className="h-4 w-4 mr-1" />
          Anterior
        </Button>

        {isLastStep ? (
          <Button onClick={handleSubmit}>
            <Send className="h-4 w-4 mr-1" />
            Enviar Inscripción
          </Button>
        ) : (
          <Button onClick={handleNext}>
            Siguiente
            <ArrowRight className="h-4 w-4 ml-1" />
          </Button>
        )}
      </div>
    </div>
  );
}

