import { useEffect, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { X, Loader2, Tag, Sparkles } from 'lucide-react'
import type { PricingCalculation } from '@/lib/api/pricing'
import type { PricingSelectionInput } from '@/lib/api/pricing'
import { calculatePricing } from '@/lib/api/pricing'

export interface SelectedClass {
  id: string
  pricingClassId?: string
  pricingScheduleId?: string
  name: string
  price: number
  day?: string
  time?: string
}

interface Props {
  tenantId: string
  selectedClasses: SelectedClass[]
  onRemoveClass: (id: string) => void
  showRemoveButtons?: boolean
}

export function DynamicPricingSummary({
  tenantId,
  selectedClasses,
  onRemoveClass,
  showRemoveButtons = true,
}: Props) {
  const [pricing, setPricing] = useState<PricingCalculation | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (selectedClasses.length === 0) {
      setPricing(null)
      return
    }

    loadPricing()
  }, [selectedClasses, tenantId])

  async function loadPricing() {
    try {
      setLoading(true)
      setError(null)

      const classIds = selectedClasses.map((c) => c.pricingClassId || c.id)
      const selections: PricingSelectionInput[] = selectedClasses.map((c) => ({
        class_id: c.pricingClassId || c.id,
        schedule_id: c.pricingScheduleId,
      }))
      const result = await calculatePricing(tenantId, classIds, selections)

      setPricing(result)
    } catch (err: unknown) {
      console.error('Error calculating pricing:', err)
      setError(err instanceof Error ? err.message : 'Error al calcular el precio')
      // Fallback to simple sum
      const fallbackTotal = selectedClasses.reduce((sum, c) => sum + c.price, 0)
      setPricing({
        total: fallbackTotal,
        subtotal: fallbackTotal,
        discount: 0,
        breakdown: selectedClasses.map((c) => ({
          type: 'class',
          description: c.name,
          total: c.price,
          class_ids: [c.id],
        })),
        applied_rules: [],
        savings: 0,
      })
    } finally {
      setLoading(false)
    }
  }

  if (selectedClasses.length === 0) {
    return (
      <Card>
        <CardContent className="p-6">
          <p className="text-sm text-muted-foreground text-center">
            No hay clases seleccionadas
          </p>
        </CardContent>
      </Card>
    )
  }

  const hasBonuses = Boolean(pricing && pricing.applied_rules.length > 0)
  const hasDiscount = Boolean(pricing && pricing.discount > 0)

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg">Resumen de Matrícula</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Selected Classes List */}
        <div className="space-y-2">
          {selectedClasses.map((cls) => (
            <div
              key={cls.id}
              className="flex items-center justify-between p-3 rounded-lg border bg-muted/30"
            >
              <div className="flex-1">
                <p className="font-medium text-sm">{cls.name}</p>
                {(cls.day || cls.time) && (
                  <p className="text-xs text-muted-foreground">
                    {cls.day} {cls.time}
                  </p>
                )}
              </div>
              <div className="flex items-center gap-2">
                <span className="text-sm font-medium">€{cls.price.toFixed(2)}</span>
                {showRemoveButtons && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => onRemoveClass(cls.id)}
                    className="h-6 w-6 p-0 text-muted-foreground hover:text-destructive"
                  >
                    <X className="h-3 w-3" />
                  </Button>
                )}
              </div>
            </div>
          ))}
        </div>

        {/* Loading State */}
        {loading && (
          <div className="flex items-center justify-center py-4">
            <Loader2 className="h-4 w-4 animate-spin mr-2" />
            <span className="text-sm text-muted-foreground">Calculando precio...</span>
          </div>
        )}

        {/* Applied Bonuses/Rules */}
        {!loading && hasBonuses && (
          <div className="space-y-2 p-3 rounded-lg border bg-success/5 border-success/20">
            <div className="flex items-center gap-2 text-success font-medium text-sm">
              <Tag className="h-3 w-3" />
              <span>Bonos aplicados</span>
            </div>
            {pricing.applied_rules.map((rule, index) => (
              <div key={index} className="text-xs text-muted-foreground pl-5">
                <span className="font-medium">{rule.rule_name}</span>
                {rule.description && <span> - {rule.description}</span>}
              </div>
            ))}
            {pricing.savings > 0 && (
              <div className="text-xs text-success font-medium pl-5">
                Ahorro aplicado: €{pricing.savings.toFixed(2)}
              </div>
            )}
          </div>
        )}

        {!loading && pricing?.hint && !hasBonuses && (
          <div className="space-y-1 p-3 rounded-lg border bg-amber-50 border-amber-200 text-amber-800">
            <div className="flex items-center gap-2 text-sm font-medium">
              <Sparkles className="h-3.5 w-3.5" />
              <span>Estás cerca de un bono</span>
            </div>
            <p className="text-xs">
              Te faltan {pricing.hint.missingHours.toFixed(1)}h en {pricing.hint.categoryName} para aplicar
              " {pricing.hint.bonusName} " ({pricing.hint.bonusPrice.toFixed(2)}€).
            </p>
            {pricing.hint.potentialSavings > 0 && (
              <p className="text-xs font-medium">
                Ahorro potencial estimado: €{pricing.hint.potentialSavings.toFixed(2)}
              </p>
            )}
          </div>
        )}

        {/* Error State */}
        {error && !loading && (
          <div className="text-xs text-warning p-2 rounded bg-warning/10 border border-warning/20">
            {error} - Mostrando precios base
          </div>
        )}

        {/* Pricing Breakdown */}
        {!loading && pricing && (
          <div className="space-y-2 pt-2 border-t">
            {/* Breakdown Items (only show packs, not individual classes already shown above) */}
            {pricing.breakdown
              .filter((item) => item.type === 'pack')
              .map((item, index) => (
                <div key={index} className="flex justify-between text-sm">
                  <span className="text-success font-medium">{item.description}</span>
                  <span className="text-success font-medium">€{item.total.toFixed(2)}</span>
                </div>
              ))}

            {/* Subtotal */}
            <div className="flex justify-between text-sm text-muted-foreground">
              <span>Subtotal</span>
              <span>€{pricing.subtotal.toFixed(2)}</span>
            </div>

            {/* Discount */}
            {hasDiscount && (
              <div className="flex justify-between text-sm text-success">
                <span>Descuento</span>
                <span>-€{pricing.discount.toFixed(2)}</span>
              </div>
            )}

            {/* Total */}
            <div className="flex justify-between text-lg font-bold pt-2 border-t">
              <span>Total</span>
              <span>€{pricing.total.toFixed(2)}</span>
            </div>

            {!hasBonuses && pricing.savings > 0 && (
              <div className="flex justify-between text-sm text-success">
                <span>Ahorro potencial</span>
                <span>€{pricing.savings.toFixed(2)}</span>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

import { EnrollmentRecord, EnrollmentStatus } from "@/lib/data/mockEnrollments";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Mail, Phone, Calendar, CreditCard, Clock, FileText, StickyNote, CheckCircle, XCircle, Ban, UserRound, Users } from "lucide-react";
import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { es } from "date-fns/locale";

const STATUS_CONFIG: Record<EnrollmentStatus, { label: string; className: string }> = {
  pending: { label: "Pendiente", className: "bg-warning/15 text-warning border-warning/20" },
  confirmed: { label: "Aceptada", className: "bg-success/15 text-success border-success/20" },
  declined: { label: "Rechazada", className: "bg-destructive/15 text-destructive border-destructive/20" },
  cancelled: { label: "Cancelada", className: "bg-muted text-muted-foreground border-border" },
};

interface EnrollmentDetailDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  enrollment: EnrollmentRecord | null;
  onChangeStatus: (id: string, status: EnrollmentStatus) => void;
}

export function EnrollmentDetailDrawer({ open, onOpenChange, enrollment, onChangeStatus }: EnrollmentDetailDrawerProps) {
  if (!enrollment) return null;

  const statusCfg = STATUS_CONFIG[enrollment.status];
  const isPending = enrollment.status === "pending";

  const paymentMethodFormatted = enrollment.paymentMethod === "transfer" ? "Transferencia bancaria" :
    enrollment.paymentMethod === "cash" ? "Efectivo" :
    enrollment.paymentMethod;

  const isTransferPayment = (() => {
    const normalized = (enrollment.paymentMethod || "").toLowerCase();
    return normalized === "transfer" || normalized === "bank_transfer" || normalized.includes("transfer");
  })();

  const guardians = enrollment.guardians || [];

  const formatMaybeDate = (value?: string) => {
    if (!value) return "No disponible";
    const parsed = new Date(value);
    if (Number.isNaN(parsed.getTime())) {
      return value;
    }
    return format(parsed, "d MMM yyyy", { locale: es });
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-md overflow-y-auto">
        <SheetHeader className="pb-4">
          <div className="flex items-center justify-between">
            <SheetTitle className="text-lg">Inscripción #{enrollment.id.replace("e", "")}</SheetTitle>
            <Badge variant="outline" className={cn("text-[10px] font-medium", statusCfg.className)}>
              {statusCfg.label}
            </Badge>
          </div>
        </SheetHeader>

        <div className="space-y-5">
          {/* Student info */}
          <section className="space-y-3">
            <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Datos del Alumno</h4>
            <div className="space-y-2.5">
              <InfoRow icon={UserRound} label="Nombre" value={enrollment.studentName} />
              <InfoRow icon={Mail} label="Email" value={enrollment.studentEmail} />
              <InfoRow icon={Phone} label="Teléfono" value={enrollment.studentPhone} />
              <InfoRow icon={Calendar} label="Fecha de nacimiento" value={formatMaybeDate(enrollment.studentBirthDate)} />
              <InfoRow icon={Calendar} label="Fecha de solicitud" value={format(new Date(enrollment.date), "d MMM yyyy", { locale: es })} />
              <InfoRow icon={CreditCard} label="Método de pago" value={paymentMethodFormatted} />
              {isTransferPayment && (
                <InfoRow icon={CreditCard} label="IBAN/CBU" value={enrollment.studentIban || "No disponible"} />
              )}
            </div>

            {guardians.length > 0 && (
              <div className="rounded-md border border-border bg-muted/20 p-3 space-y-2.5">
                <div className="flex items-center gap-1.5">
                  <Users className="h-3.5 w-3.5 text-muted-foreground" />
                  <p className="text-[10px] text-muted-foreground uppercase tracking-wider font-medium">Tutores</p>
                </div>

                <div className="space-y-2">
                  {guardians.map((guardian, index) => (
                    <div key={`${guardian.name}-${index}`} className="rounded-md border border-border bg-background px-3 py-2.5 space-y-1.5">
                      <p className="text-sm font-medium text-foreground">{guardian.name || `Tutor ${index + 1}`}</p>
                      {guardian.phone && <p className="text-xs text-muted-foreground">Tel: {guardian.phone}</p>}
                      {guardian.email && <p className="text-xs text-muted-foreground truncate">Email: {guardian.email}</p>}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </section>

          <Separator />

          {/* Classes */}
          <section className="space-y-3">
            <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
              Clases ({enrollment.classes.length})
            </h4>
            <div className="space-y-2">
              {enrollment.classes.map((cls) => (
                <div key={cls.id} className="flex items-center justify-between rounded-md border border-border bg-muted/30 px-3 py-2.5">
                  <div>
                    <p className="text-sm font-medium text-foreground">{cls.name}</p>
                    <div className="flex items-center gap-1.5 text-[10px] text-muted-foreground mt-0.5">
                      <Clock className="h-2.5 w-2.5" />
                      <span>{cls.day} · {cls.time}</span>
                    </div>
                  </div>
                  <span className="text-sm font-medium text-foreground">€{cls.price}</span>
                </div>
              ))}
              <div className="flex items-center justify-between pt-2 border-t border-border">
                <span className="text-sm font-semibold text-foreground">Total</span>
                <span className="text-base font-bold text-primary">€{enrollment.totalPrice}</span>
              </div>
            </div>
          </section>

          {/* Attachments */}
          {enrollment.attachments && enrollment.attachments.length > 0 && (
            <>
              <Separator />
              <section className="space-y-3">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Documentos Adjuntos</h4>
                <div className="space-y-1.5">
                  {enrollment.attachments.map((file) => (
                    <div key={file} className="flex items-center gap-2 rounded-md border border-border bg-muted/30 px-3 py-2">
                      <FileText className="h-3.5 w-3.5 text-muted-foreground" />
                      <span className="text-sm text-foreground">{file}</span>
                    </div>
                  ))}
                </div>
              </section>
            </>
          )}

          {/* Notes */}
          {enrollment.notes && (
            <>
              <Separator />
              <section className="space-y-2">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
                  <StickyNote className="h-3 w-3" /> Notas
                </h4>
                <p className="text-sm text-muted-foreground bg-muted/30 rounded-md p-3 border border-border">
                  {enrollment.notes}
                </p>
              </section>
            </>
          )}

          {/* Actions */}
          {isPending && (
            <>
              <Separator />
              <section className="space-y-3">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Acciones</h4>
                <div className="flex flex-wrap gap-2">
                  <Button
                    size="sm"
                    className="bg-success hover:bg-success/90 text-success-foreground"
                    onClick={() => onChangeStatus(enrollment.id, "confirmed")}
                  >
                    <CheckCircle className="h-3.5 w-3.5 mr-1" />
                    Aceptar
                  </Button>
                  <Button
                    size="sm"
                    variant="destructive"
                    onClick={() => onChangeStatus(enrollment.id, "declined")}
                  >
                    <XCircle className="h-3.5 w-3.5 mr-1" />
                    Rechazar
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => onChangeStatus(enrollment.id, "cancelled")}
                  >
                    <Ban className="h-3.5 w-3.5 mr-1" />
                    Cancelar
                  </Button>
                </div>
              </section>
            </>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

function InfoRow({ icon: Icon, label, value }: { icon: any; label: string; value?: string }) {
  return (
    <div className="flex items-center gap-2.5">
      <Icon className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
      <div className="flex-1 min-w-0">
        <p className="text-[10px] text-muted-foreground">{label}</p>
        <p className="text-sm text-foreground truncate">{value || "No disponible"}</p>
      </div>
    </div>
  );
}

import { PaymentRecord, PaymentStatus } from "@/lib/data/mockPayments";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Mail, User, Calendar, CreditCard, FileText, StickyNote, CheckCircle, RotateCcw, Receipt, FileCheck } from "lucide-react";
import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { es } from "date-fns/locale";

const STATUS_CONFIG: Record<PaymentStatus, { label: string; className: string }> = {
  paid: { label: "Pagado", className: "bg-success/15 text-success border-success/20" },
  pending: { label: "Pendiente", className: "bg-warning/15 text-warning border-warning/20" },
  overdue: { label: "Vencido", className: "bg-destructive/15 text-destructive border-destructive/20" },
  refunded: { label: "Reembolsado", className: "bg-info/15 text-info border-info/20" },
};

interface PaymentDetailDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  payment: PaymentRecord | null;
  onMarkPaid: (id: string) => void;
  onMarkRefunded: (id: string) => void;
  onGenerateReceipt: (payment: PaymentRecord) => void;
}

export function PaymentDetailDrawer({ open, onOpenChange, payment, onMarkPaid, onMarkRefunded, onGenerateReceipt }: PaymentDetailDrawerProps) {
  if (!payment) return null;

  const statusCfg = STATUS_CONFIG[payment.status];
  const canMarkPaid = payment.status === "pending" || payment.status === "overdue";
  const canRefund = payment.status === "paid";
  const payerDiffers = payment.payerName !== payment.studentName;

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-md overflow-y-auto">
        <SheetHeader className="pb-4">
          <div className="flex items-center justify-between">
            <SheetTitle className="text-lg">Pago #{payment.id.replace("p", "")}</SheetTitle>
            <Badge variant="outline" className={cn("text-[10px] font-medium", statusCfg.className)}>
              {statusCfg.label}
            </Badge>
          </div>
        </SheetHeader>

        <div className="space-y-5">
          {/* Student & Payer */}
          <section className="space-y-3">
            <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Datos del Alumno</h4>
            <div className="space-y-2.5">
              <InfoRow icon={User} label="Alumno" value={payment.studentName} />
              <InfoRow icon={Mail} label="Email" value={payment.studentEmail} />
              <InfoRow icon={User} label="Pagador" value={payment.payerName} highlight={payerDiffers} />
            </div>
          </section>

          <Separator />

          {/* Payment details */}
          <section className="space-y-3">
            <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Detalle del Pago</h4>
            <div className="space-y-2.5">
              <InfoRow icon={FileText} label="Concepto" value={payment.concept} />
              <InfoRow icon={Calendar} label="Período" value={format(new Date(payment.month + "-01"), "MMMM yyyy", { locale: es })} />
              <InfoRow icon={Calendar} label="Fecha de registro" value={format(new Date(payment.date), "d MMM yyyy", { locale: es })} />
              <InfoRow icon={CreditCard} label="Método de pago" value={payment.method} />
              {payment.accountNumber && (
                <InfoRow icon={CreditCard} label="Número de cuenta" value={payment.accountNumber} />
              )}
            </div>
            <div className="flex items-center justify-between pt-3 border-t border-border">
              <div className="flex items-center gap-2">
                <span className="text-sm font-semibold text-foreground">Monto</span>
                {payment.amountChanged && (
                  <Badge variant="outline" className="text-[10px] bg-warning/10 text-warning border-warning/30">
                    Modificado
                  </Badge>
                )}
              </div>
              <span className="text-lg font-bold text-primary">€{payment.amount.toLocaleString()}</span>
            </div>
          </section>

          {/* Receipt status */}
          {payment.status === "paid" && (
            <>
              <Separator />
              <section className="space-y-3">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Recibo</h4>
                {payment.receiptGenerated ? (
                  <div className="flex items-center gap-2 rounded-md border border-success/20 bg-success/10 px-3 py-2.5">
                    <FileCheck className="h-4 w-4 text-success" />
                    <span className="text-sm text-foreground">Recibo generado</span>
                  </div>
                ) : (
                  <Button size="sm" variant="outline" onClick={() => onGenerateReceipt(payment)}>
                    <Receipt className="h-3.5 w-3.5 mr-1" />
                    Generar Recibo
                  </Button>
                )}
              </section>
            </>
          )}

          {/* Notes */}
          {payment.notes && (
            <>
              <Separator />
              <section className="space-y-2">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
                  <StickyNote className="h-3 w-3" /> Notas
                </h4>
                <p className="text-sm text-muted-foreground bg-muted/30 rounded-md p-3 border border-border">
                  {payment.notes}
                </p>
              </section>
            </>
          )}

          {/* Actions */}
          {(canMarkPaid || canRefund) && (
            <>
              <Separator />
              <section className="space-y-3">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Acciones</h4>
                <div className="flex flex-wrap gap-2">
                  {canMarkPaid && (
                    <Button
                      size="sm"
                      className="bg-success hover:bg-success/90 text-success-foreground"
                      onClick={() => onMarkPaid(payment.id)}
                    >
                      <CheckCircle className="h-3.5 w-3.5 mr-1" />
                      Marcar como Pagado
                    </Button>
                  )}
                  {canRefund && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => onMarkRefunded(payment.id)}
                    >
                      <RotateCcw className="h-3.5 w-3.5 mr-1" />
                      Reembolsar
                    </Button>
                  )}
                </div>
              </section>
            </>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

function InfoRow({ icon: Icon, label, value, highlight }: { icon: any; label: string; value: string; highlight?: boolean }) {
  return (
    <div className="flex items-center gap-2.5">
      <Icon className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
      <div className="flex-1 min-w-0">
        <p className="text-[10px] text-muted-foreground">{label}</p>
        <p className={cn("text-sm truncate", highlight ? "text-primary font-medium" : "text-foreground")}>{value}</p>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { PaymentMethod, PAYMENT_METHODS } from "@/lib/data/mockPayments";
import { getStudents } from "@/lib/api/students";
import { getSchoolSettings } from "@/lib/api/settings";
import { Loader2 } from "lucide-react";

interface StudentOption {
  id: string;
  name: string;
  email: string;
  status: string;
  guardian?: {
    name: string;
  };
  enrolledClasses: Array<{
    id: string;
    name: string;
    monthlyPrice: number;
  }>;
}

interface RecordPaymentModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave: (payment: {
    studentId: string;
    amount: number;
    metadata: Record<string, unknown>;
  }) => void;
  onStartStripeCheckout?: (payment: {
    studentId: string;
    amount: number;
    metadata: Record<string, unknown>;
  }) => Promise<void>;
  preferredByStudent?: Record<
    string,
    { method?: PaymentMethod; payerName?: string; accountNumber?: string }
  >;
}

export function RecordPaymentModal({
  open,
  onOpenChange,
  onSave,
  onStartStripeCheckout,
  preferredByStudent,
}: RecordPaymentModalProps) {
  const [studentId, setStudentId] = useState("");
  const [payerName, setPayerName] = useState("");
  const [concept, setConcept] = useState("");
  const [month, setMonth] = useState(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
  });
  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState<PaymentMethod>("Efectivo");
  const [accountNumber, setAccountNumber] = useState("");
  const [notes, setNotes] = useState("");
  const [students, setStudents] = useState<StudentOption[]>([]);
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [availableMethods, setAvailableMethods] = useState<PaymentMethod[]>(PAYMENT_METHODS);
  const [currency, setCurrency] = useState("ARS");

  const activeStudents = students.filter((s) => s.status === "active");
  const selectedStudent = activeStudents.find((s) => s.id === studentId);

  useEffect(() => {
    void (async () => {
      setLoadingStudents(true);
      try {
        const data = await getStudents();
        setStudents(data as unknown as StudentOption[]);
      } finally {
        setLoadingStudents(false);
      }
    })();
  }, []);

  useEffect(() => {
    void (async () => {
      try {
        const settings = await getSchoolSettings();
        const payment = (settings?.payment || {}) as Record<string, unknown>;
        const nextMethods: PaymentMethod[] = [];

        if (payment.enableTransfer !== false) {
          nextMethods.push("Transferencia bancaria");
        }
        if (payment.enableCash !== false) {
          nextMethods.push("Efectivo");
        }

        if (nextMethods.length > 0) {
          setAvailableMethods(nextMethods);
          if (!nextMethods.includes(method)) {
            setMethod(nextMethods[0]);
          }
        }

        if (typeof payment.currency === "string" && payment.currency.trim().length > 0) {
          setCurrency(payment.currency.toUpperCase());
        }
      } catch {
        // Keep defaults when payment settings are not available
      }
    })();
  }, []);

  const handleStudentChange = (id: string) => {
    setStudentId(id);
    const student = activeStudents.find((s) => s.id === id);
    const preferred = id ? preferredByStudent?.[id] : undefined;

    if (student) {
      // Auto-fill payer: use guardian if exists, otherwise student
      setPayerName(preferred?.payerName || (student.guardian ? student.guardian.name : student.name));
      if (preferred?.method) {
        setMethod(preferred.method);
      }
      setAccountNumber(preferred?.accountNumber || "");
      if (student.enrolledClasses.length > 0) {
        const total = student.enrolledClasses.reduce((s, c) => s + c.monthlyPrice, 0);
        setAmount(String(total));
        setConcept("Mensualidad — " + student.enrolledClasses.map((c) => c.name).join(" + "));
      }
    }
  };

  const buildPayload = () => {
    if (!selectedStudent || !concept.trim() || !amount || !payerName.trim() || !month) {
      return null;
    }

    const paymentMethodKey =
      method === "Transferencia bancaria"
        ? "transfer"
        : method === "Tarjeta"
          ? "card"
          : method === "MercadoPago"
            ? "mercadopago"
            : "cash";

    return {
      studentId: selectedStudent.id,
      amount: parseFloat(amount),
      metadata: {
        payer_name: payerName.trim(),
        concept: concept.trim(),
        month,
        student_name: selectedStudent.name,
        student_email: selectedStudent.email,
        payment_method: paymentMethodKey,
        account_number:
          method === "Transferencia bancaria"
            ? accountNumber.trim() || (preferredByStudent?.[selectedStudent.id]?.accountNumber ?? undefined)
            : undefined,
        notes: notes.trim() || undefined,
      },
    };
  };

  const handleSave = () => {
    const payload = buildPayload();
    if (!payload) return;

    onSave(payload);
    // Reset
    setStudentId("");
    setPayerName("");
    setConcept("");
    setAmount("");
    setAccountNumber("");
    setNotes("");
  };

  const handleStripeCheckout = async () => {
    if (!onStartStripeCheckout) return;
    const payload = buildPayload();
    if (!payload) return;
    await onStartStripeCheckout(payload);
  };

  const isValid = studentId && concept.trim() && payerName.trim() && amount && parseFloat(amount) > 0 && month;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Registrar Pago</DialogTitle>
          <DialogDescription>
            Registra el pago, metodo y referencia para actualizar el estado de la cuota.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Student */}
          <div className="space-y-1.5">
            <Label className="text-xs">Alumno *</Label>
            <Select value={studentId} onValueChange={handleStudentChange}>
              <SelectTrigger className="h-9 text-sm">
                <SelectValue placeholder="Seleccionar alumno..." />
              </SelectTrigger>
              <SelectContent>
                {loadingStudents ? (
                  <div className="px-3 py-2 text-xs text-muted-foreground flex items-center gap-2">
                    <Loader2 className="h-3 w-3 animate-spin" /> Cargando alumnos...
                  </div>
                ) : activeStudents.map((s) => (
                  <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Payer name */}
          <div className="space-y-1.5">
            <Label className="text-xs">Nombre del Pagador *</Label>
            <Input
              value={payerName}
              onChange={(e) => setPayerName(e.target.value)}
              placeholder="Nombre de quien realiza el pago"
              className="h-9 text-sm"
            />
          </div>

          {/* Concept */}
          <div className="space-y-1.5">
            <Label className="text-xs">Concepto *</Label>
            <Input
              value={concept}
              onChange={(e) => setConcept(e.target.value)}
              placeholder="Ej: Mensualidad — Ballet Principiantes"
              className="h-9 text-sm"
            />
          </div>

          {/* Month & Amount row */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-xs">Período *</Label>
              <Input
                type="month"
                value={month}
                onChange={(e) => setMonth(e.target.value)}
                className="h-9 text-sm"
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">Monto ({currency}) *</Label>
              <Input
                type="number"
                min="0"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0"
                className="h-9 text-sm"
              />
            </div>
          </div>

          {/* Method */}
          <div className="space-y-1.5">
            <Label className="text-xs">Método de Pago</Label>
            <Select value={method} onValueChange={(v) => setMethod(v as PaymentMethod)}>
              <SelectTrigger className="h-9 text-sm">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {availableMethods.map((m) => (
                  <SelectItem key={m} value={m}>{m}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {method === "Transferencia bancaria" && (
            <div className="space-y-1.5">
              <Label className="text-xs">Número de cuenta</Label>
              <Input
                value={accountNumber}
                onChange={(e) => setAccountNumber(e.target.value)}
                placeholder="Ej: ES91 **** **** **** 1234"
                className="h-9 text-sm"
              />
            </div>
          )}

          {/* Notes */}
          <div className="space-y-1.5">
            <Label className="text-xs">Notas (opcional)</Label>
            <Textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Notas adicionales..."
              className="text-sm min-h-[60px]"
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" size="sm" onClick={() => onOpenChange(false)}>Cancelar</Button>
          {onStartStripeCheckout ? (
            <Button variant="secondary" size="sm" disabled={!isValid} onClick={handleStripeCheckout}>
              Cobrar con Stripe
            </Button>
          ) : null}
          <Button size="sm" disabled={!isValid} onClick={handleSave}>Registrar Pago</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { StudentRecord } from "@/lib/data/mockStudents";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2 } from "lucide-react";
import type { SchoolStudentField } from "@/lib/api/studentFields";

interface StudentFormModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  student?: StudentRecord | null;
  customFields?: SchoolStudentField[];
  onSave: (data: Omit<StudentRecord, "id">) => Promise<boolean>;
}

const EMPTY: Omit<StudentRecord, "id"> = {
  name: "", email: "", phone: "", birthdate: "",
  address: "", locality: "", identityDocumentType: undefined, identityDocumentNumber: "",
  enrolledClasses: [], status: "active", joinDate: new Date().toISOString().slice(0, 10),
  paymentType: "monthly", notes: "",
  payerType: "student",
  payerName: "",
  payerEmail: "",
  payerPhone: "",
  preferredPaymentMethod: "cash",
  accountNumber: "",
  extraData: {},
};

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function hasMinDigits(value: string, min: number): boolean {
  const digits = value.replace(/\D/g, "");
  return digits.length >= min;
}

function isValidDate(value: string): boolean {
  const date = new Date(value);
  return !Number.isNaN(date.getTime());
}

export function StudentFormModal({ open, onOpenChange, student, customFields = [], onSave }: StudentFormModalProps) {
  const isEdit = !!student;
  const [form, setForm] = useState<Omit<StudentRecord, "id">>(EMPTY);
  const [hasGuardian, setHasGuardian] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isLoading, setIsLoading] = useState(false);

  const isMinor = (() => {
    if (!form.birthdate) return false;
    const birth = new Date(form.birthdate);
    if (Number.isNaN(birth.getTime())) return false;
    const today = new Date();
    const age = today.getFullYear() - birth.getFullYear() - (
      today.getMonth() < birth.getMonth() ||
      (today.getMonth() === birth.getMonth() && today.getDate() < birth.getDate())
        ? 1
        : 0
    );
    return age < 18;
  })();

  useEffect(() => {
    if (student) {
      const { id, ...rest } = student;
      setForm({ ...rest, extraData: rest.extraData || {} });
      setHasGuardian(!!student.guardian);
    } else {
      setForm(EMPTY);
      setHasGuardian(false);
    }
    setErrors({});
  }, [student, open]);

  useEffect(() => {
    if (form.payerType === "guardian" && !hasGuardian) {
      setHasGuardian(true);
    }
  }, [form.payerType, hasGuardian]);

  const set = (key: string, value: any) => {
    setForm((prev) => ({ ...prev, [key]: value }));
    setErrors((prev) => { const n = { ...prev }; delete n[key]; return n; });
  };

  const setGuardian = (key: string, value: string) => {
    setForm((prev) => ({
      ...prev,
      guardian: { ...(prev.guardian || { name: "", phone: "", email: "" }), [key]: value },
    }));
  };

  const validate = () => {
    const e: Record<string, string> = {};
    if (!form.name.trim()) e.name = "Obligatorio";
    else if (form.name.trim().length > 120) e.name = "Máximo 120 caracteres";

    if (!form.email.trim()) e.email = "Obligatorio";
    else if (!EMAIL_REGEX.test(form.email.trim())) e.email = "Email inválido";

    if (!form.phone.trim()) e.phone = "Obligatorio";
    else if (!hasMinDigits(form.phone, 6)) e.phone = "Teléfono inválido";

    if (form.identityDocumentNumber?.trim() && !form.identityDocumentType) {
      e.identityDocumentType = "Obligatorio";
    }
    if (form.identityDocumentType && !form.identityDocumentNumber?.trim()) {
      e.identityDocumentNumber = "Obligatorio";
    } else if (form.identityDocumentType && form.identityDocumentNumber?.trim()) {
      const normalizedDoc = form.identityDocumentNumber.trim();
      if (form.identityDocumentType === "dni" && !/^\d{7,8}[A-Za-z]?$/.test(normalizedDoc)) {
        e.identityDocumentNumber = "DNI inválido";
      }
      if (form.identityDocumentType === "passport" && !/^[A-Za-z0-9]{5,20}$/.test(normalizedDoc)) {
        e.identityDocumentNumber = "Pasaporte inválido";
      }
    }

    if (!form.birthdate) e.birthdate = "Obligatorio";
    else if (!isValidDate(form.birthdate)) e.birthdate = "Fecha inválida";
    else if (new Date(form.birthdate) > new Date()) e.birthdate = "No puede ser futura";

    if (form.joinDate && !isValidDate(form.joinDate)) {
      e.joinDate = "Fecha inválida";
    }

    if (form.address && form.address.trim().length > 180) {
      e.address = "Máximo 180 caracteres";
    }

    if (form.locality && form.locality.trim().length > 120) {
      e.locality = "Máximo 120 caracteres";
    }

    if (form.notes && form.notes.length > 2000) {
      e.notes = "Máximo 2000 caracteres";
    }

    const requiresGuardianData = hasGuardian || isMinor || form.payerType === "guardian";
    if (requiresGuardianData) {
      if (!form.guardian?.name?.trim()) e.guardian_name = "Obligatorio";
      if (!form.guardian?.phone?.trim()) e.guardian_phone = "Obligatorio";
      else if (!hasMinDigits(form.guardian.phone, 6)) e.guardian_phone = "Teléfono inválido";
      if (form.guardian?.email?.trim() && !EMAIL_REGEX.test(form.guardian.email.trim())) {
        e.guardian_email = "Email inválido";
      }
    }

    if (!form.payerType) {
      e.payerType = "Obligatorio";
    }

    if (!form.preferredPaymentMethod) {
      e.preferredPaymentMethod = "Obligatorio";
    }

    if (form.payerType === "other") {
      if (!form.payerName?.trim()) e.payerName = "Obligatorio";
      if (!form.payerPhone?.trim()) e.payerPhone = "Obligatorio";
      else if (!hasMinDigits(form.payerPhone, 6)) e.payerPhone = "Teléfono inválido";
      if (!form.payerEmail?.trim()) {
        e.payerEmail = "Obligatorio";
      } else if (!EMAIL_REGEX.test(form.payerEmail.trim())) {
        e.payerEmail = "Email inválido";
      }
    }

    if (form.preferredPaymentMethod === "transfer" && form.accountNumber?.trim() === "") {
      e.accountNumber = "Obligatorio";
    } else if (form.preferredPaymentMethod === "transfer" && form.accountNumber && form.accountNumber.trim().length < 8) {
      e.accountNumber = "Cuenta inválida";
    }

    for (const field of customFields.filter((item) => item.visible && item.required)) {
      const rawValue = form.extraData?.[field.key];
      if (rawValue == null || String(rawValue).trim() === "") {
        e[`custom_${field.key}`] = "Obligatorio";
      }
    }

    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSave = async () => {
    if (!validate()) return;
    const data = { ...form };
    if (!hasGuardian && !isMinor) {
      delete data.guardian;
    } else if (data.guardian) {
      data.guardian = {
        ...data.guardian,
        email: data.guardian.email?.trim() ? data.guardian.email.trim() : undefined,
      };
    }

    if (data.payerType !== "other") {
      data.payerName = undefined;
      data.payerEmail = undefined;
      data.payerPhone = undefined;
    }

    if (data.preferredPaymentMethod !== "transfer") {
      data.accountNumber = undefined;
    }

    data.extraData = { ...(data.extraData || {}) };

    setIsLoading(true);
    try {
      const ok = await onSave(data);
      if (ok) {
        onOpenChange(false);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{isEdit ? "Editar Alumno" : "Nuevo Alumno"}</DialogTitle>
          <DialogDescription>
            {isEdit ? "Modifica los datos del alumno y guarda cambios." : "Completa la ficha para registrar un nuevo alumno."}
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-4 py-2">
          <div className="space-y-1.5">
            <Label className="text-sm">Nombre completo *</Label>
            <Input value={form.name} onChange={(e) => set("name", e.target.value)} placeholder="Nombre completo" disabled={isLoading} className={errors.name ? "border-destructive" : ""} />
            {errors.name && <p className="text-xs text-destructive">{errors.name}</p>}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-sm">Email *</Label>
              <Input type="email" value={form.email} onChange={(e) => set("email", e.target.value)} placeholder="email@ejemplo.com" disabled={isLoading} className={errors.email ? "border-destructive" : ""} />
              {errors.email && <p className="text-xs text-destructive">{errors.email}</p>}
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm">Teléfono *</Label>
              <Input value={form.phone} onChange={(e) => set("phone", e.target.value)} placeholder="+34 612 34 56 78" disabled={isLoading} className={errors.phone ? "border-destructive" : ""} />
              {errors.phone && <p className="text-xs text-destructive">{errors.phone}</p>}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-sm">Domicilio</Label>
              <Input
                value={form.address || ""}
                onChange={(e) => set("address", e.target.value)}
                placeholder="Calle, número, piso..."
                disabled={isLoading}
                className={errors.address ? "border-destructive" : ""}
              />
              {errors.address && <p className="text-xs text-destructive">{errors.address}</p>}
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm">Localidad</Label>
              <Input
                value={form.locality || ""}
                onChange={(e) => set("locality", e.target.value)}
                placeholder="Ej: Madrid"
                disabled={isLoading}
                className={errors.locality ? "border-destructive" : ""}
              />
              {errors.locality && <p className="text-xs text-destructive">{errors.locality}</p>}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-sm">Tipo de documento</Label>
              <Select
                value={form.identityDocumentType || "none"}
                onValueChange={(v) => set("identityDocumentType", v === "none" ? undefined : v)}
                disabled={isLoading}
              >
                <SelectTrigger className={errors.identityDocumentType ? "border-destructive" : ""}>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sin documento</SelectItem>
                  <SelectItem value="dni">DNI</SelectItem>
                  <SelectItem value="passport">Pasaporte</SelectItem>
                </SelectContent>
              </Select>
              {errors.identityDocumentType && <p className="text-xs text-destructive">{errors.identityDocumentType}</p>}
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm">Nº DNI/Pasaporte</Label>
              <Input
                value={form.identityDocumentNumber || ""}
                onChange={(e) => set("identityDocumentNumber", e.target.value)}
                placeholder="Documento identificativo"
                disabled={isLoading}
                className={errors.identityDocumentNumber ? "border-destructive" : ""}
              />
              {errors.identityDocumentNumber && <p className="text-xs text-destructive">{errors.identityDocumentNumber}</p>}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-sm">Fecha de nacimiento *</Label>
              <Input type="date" value={form.birthdate} onChange={(e) => set("birthdate", e.target.value)} disabled={isLoading} className={errors.birthdate ? "border-destructive" : ""} />
              {errors.birthdate && <p className="text-xs text-destructive">{errors.birthdate}</p>}
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm">Tipo de pago</Label>
              <Select value={form.paymentType} onValueChange={(v) => set("paymentType", v)} disabled={isLoading}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="monthly">Mensual</SelectItem>
                  <SelectItem value="per_class">Por clase</SelectItem>
                  <SelectItem value="none">Sin pago</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-sm">Estado</Label>
              <Select value={form.status} onValueChange={(v: any) => set("status", v)} disabled={isLoading}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="active">Activo</SelectItem>
                  <SelectItem value="inactive">Inactivo</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm">Fecha de ingreso</Label>
              <Input type="date" value={form.joinDate} onChange={(e) => set("joinDate", e.target.value)} disabled={isLoading} className={errors.joinDate ? "border-destructive" : ""} />
              {errors.joinDate && <p className="text-xs text-destructive">{errors.joinDate}</p>}
            </div>
          </div>

          <div className="rounded-md border border-border bg-muted/30 p-4 space-y-3">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
              Datos de pago
            </p>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label className="text-sm">Quién realiza el pago *</Label>
                <Select
                  value={form.payerType || "student"}
                  onValueChange={(v) => set("payerType", v)}
                  disabled={isLoading}
                >
                  <SelectTrigger className={errors.payerType ? "border-destructive" : ""}>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="student">El propio alumno</SelectItem>
                    <SelectItem value="guardian">Tutor o responsable</SelectItem>
                    <SelectItem value="other">Otra persona</SelectItem>
                  </SelectContent>
                </Select>
                {errors.payerType && <p className="text-xs text-destructive">{errors.payerType}</p>}
              </div>

              <div className="space-y-1.5">
                <Label className="text-sm">Método de pago *</Label>
                <Select
                  value={form.preferredPaymentMethod || "cash"}
                  onValueChange={(v) => set("preferredPaymentMethod", v)}
                  disabled={isLoading}
                >
                  <SelectTrigger className={errors.preferredPaymentMethod ? "border-destructive" : ""}>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="transfer">Transferencia bancaria</SelectItem>
                    <SelectItem value="cash">Efectivo</SelectItem>
                    <SelectItem value="card">Tarjeta</SelectItem>
                    <SelectItem value="mercadopago">Mercado Pago</SelectItem>
                  </SelectContent>
                </Select>
                {errors.preferredPaymentMethod && <p className="text-xs text-destructive">{errors.preferredPaymentMethod}</p>}
              </div>
            </div>

            {form.payerType === "other" && (
              <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                <div className="space-y-1.5 sm:col-span-2">
                  <Label className="text-sm">Nombre del pagador *</Label>
                  <Input
                    value={form.payerName || ""}
                    onChange={(e) => set("payerName", e.target.value)}
                    placeholder="Nombre completo"
                    disabled={isLoading}
                    className={errors.payerName ? "border-destructive" : ""}
                  />
                  {errors.payerName && <p className="text-xs text-destructive">{errors.payerName}</p>}
                </div>

                <div className="space-y-1.5">
                  <Label className="text-sm">Email del pagador *</Label>
                  <Input
                    type="email"
                    value={form.payerEmail || ""}
                    onChange={(e) => set("payerEmail", e.target.value)}
                    placeholder="pagador@ejemplo.com"
                    disabled={isLoading}
                    className={errors.payerEmail ? "border-destructive" : ""}
                  />
                  {errors.payerEmail && <p className="text-xs text-destructive">{errors.payerEmail}</p>}
                </div>

                <div className="space-y-1.5">
                  <Label className="text-sm">Teléfono del pagador *</Label>
                  <Input
                    value={form.payerPhone || ""}
                    onChange={(e) => set("payerPhone", e.target.value)}
                    placeholder="+34 612 34 56 78"
                    disabled={isLoading}
                    className={errors.payerPhone ? "border-destructive" : ""}
                  />
                  {errors.payerPhone && <p className="text-xs text-destructive">{errors.payerPhone}</p>}
                </div>
              </div>
            )}

            {form.preferredPaymentMethod === "transfer" && (
              <div className="space-y-1.5">
                <Label className="text-sm">Número de cuenta (IBAN/CBU) *</Label>
                <Input
                  value={form.accountNumber || ""}
                  onChange={(e) => set("accountNumber", e.target.value)}
                  placeholder="ES00 0000 0000 0000 0000 0000"
                  disabled={isLoading}
                  className={errors.accountNumber ? "border-destructive" : ""}
                />
                {errors.accountNumber && <p className="text-xs text-destructive">{errors.accountNumber}</p>}
              </div>
            )}
          </div>

          {/* Guardian toggle */}
          <div className="flex items-center gap-2 pt-1">
            <input
              type="checkbox"
              id="has-guardian"
              checked={hasGuardian || isMinor || form.payerType === "guardian"}
              onChange={(e) => setHasGuardian(e.target.checked)}
              disabled={isLoading || isMinor || form.payerType === "guardian"}
              className="rounded border-border"
            />
            <Label htmlFor="has-guardian" className="text-sm font-normal cursor-pointer">
              Tiene tutor / responsable {isMinor ? "(obligatorio por menor de edad)" : form.payerType === "guardian" ? "(obligatorio si paga el tutor)" : ""}
            </Label>
          </div>

          {(hasGuardian || isMinor || form.payerType === "guardian") && (
            <div className="rounded-md border border-border bg-muted/30 p-4 space-y-3">
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Datos del Tutor</p>
              <div className="space-y-1.5">
                <Label className="text-sm">Nombre *</Label>
                <Input value={form.guardian?.name || ""} onChange={(e) => setGuardian("name", e.target.value)} disabled={isLoading} className={errors.guardian_name ? "border-destructive" : ""} />
                {errors.guardian_name && <p className="text-xs text-destructive">{errors.guardian_name}</p>}
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label className="text-sm">Teléfono *</Label>
                  <Input value={form.guardian?.phone || ""} onChange={(e) => setGuardian("phone", e.target.value)} disabled={isLoading} className={errors.guardian_phone ? "border-destructive" : ""} />
                  {errors.guardian_phone && <p className="text-xs text-destructive">{errors.guardian_phone}</p>}
                </div>
                <div className="space-y-1.5">
                  <Label className="text-sm">Email</Label>
                  <Input type="email" value={form.guardian?.email || ""} onChange={(e) => setGuardian("email", e.target.value)} disabled={isLoading} className={errors.guardian_email ? "border-destructive" : ""} />
                  {errors.guardian_email && <p className="text-xs text-destructive">{errors.guardian_email}</p>}
                </div>
              </div>
            </div>
          )}

          {customFields.filter((field) => field.visible).length > 0 && (
            <div className="rounded-md border border-border bg-muted/30 p-4 space-y-3">
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Campos personalizados</p>
              <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
                {customFields.filter((field) => field.visible).map((field) => {
                  const value = form.extraData?.[field.key];
                  const errorKey = `custom_${field.key}`;

                  if (field.type === "date") {
                    return (
                      <div className="space-y-1.5" key={field.id}>
                        <Label className="text-sm">{field.label}{field.required ? " *" : ""}</Label>
                        <Input
                          type="date"
                          value={typeof value === "string" ? value : ""}
                          onChange={(event) => set("extraData", { ...(form.extraData || {}), [field.key]: event.target.value })}
                          disabled={isLoading}
                          className={errors[errorKey] ? "border-destructive" : ""}
                        />
                        {errors[errorKey] && <p className="text-xs text-destructive">{errors[errorKey]}</p>}
                      </div>
                    );
                  }

                  if (field.type === "number") {
                    return (
                      <div className="space-y-1.5" key={field.id}>
                        <Label className="text-sm">{field.label}{field.required ? " *" : ""}</Label>
                        <Input
                          type="number"
                          value={value == null ? "" : String(value)}
                          onChange={(event) => set("extraData", { ...(form.extraData || {}), [field.key]: event.target.value })}
                          disabled={isLoading}
                          className={errors[errorKey] ? "border-destructive" : ""}
                        />
                        {errors[errorKey] && <p className="text-xs text-destructive">{errors[errorKey]}</p>}
                      </div>
                    );
                  }

                  if (field.type === "select") {
                    return (
                      <div className="space-y-1.5" key={field.id}>
                        <Label className="text-sm">{field.label}{field.required ? " *" : ""}</Label>
                        <Input
                          value={value == null ? "" : String(value)}
                          onChange={(event) => set("extraData", { ...(form.extraData || {}), [field.key]: event.target.value })}
                          placeholder="Valor"
                          disabled={isLoading}
                          className={errors[errorKey] ? "border-destructive" : ""}
                        />
                        {errors[errorKey] && <p className="text-xs text-destructive">{errors[errorKey]}</p>}
                      </div>
                    );
                  }

                  return (
                    <div className="space-y-1.5" key={field.id}>
                      <Label className="text-sm">{field.label}{field.required ? " *" : ""}</Label>
                      <Input
                        value={value == null ? "" : String(value)}
                        onChange={(event) => set("extraData", { ...(form.extraData || {}), [field.key]: event.target.value })}
                        placeholder={field.label}
                        disabled={isLoading}
                        className={errors[errorKey] ? "border-destructive" : ""}
                      />
                      {errors[errorKey] && <p className="text-xs text-destructive">{errors[errorKey]}</p>}
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <div className="space-y-1.5">
            <Label className="text-sm">Notas</Label>
            <Textarea value={form.notes || ""} onChange={(e) => set("notes", e.target.value)} placeholder="Observaciones sobre el alumno..." rows={2} disabled={isLoading} className={errors.notes ? "resize-none border-destructive" : "resize-none"} />
            {errors.notes && <p className="text-xs text-destructive">{errors.notes}</p>}
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isLoading}>Cancelar</Button>
          <Button onClick={handleSave} disabled={isLoading}>
            {isLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
            {isEdit ? "Guardar Cambios" : "Crear Alumno"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { StudentRecord } from "@/lib/data/mockStudents";
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Mail, Phone, Calendar, GraduationCap, Clock, User, Shield, StickyNote, DollarSign } from "lucide-react";
import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { es } from "date-fns/locale";
import type { SchoolStudentField } from "@/lib/api/studentFields";

const PAYMENT_LABELS: Record<string, string> = {
  monthly: "Mensual",
  per_class: "Por clase",
  none: "Sin pago",
};

interface StudentProfileDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  student: StudentRecord | null;
  customFields?: SchoolStudentField[];
}

function formatCustomFieldValue(value: unknown): string {
  if (value == null) return "-";
  if (typeof value === "string") return value.trim() || "-";
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  return JSON.stringify(value);
}

export function StudentProfileDrawer({ open, onOpenChange, student, customFields = [] }: StudentProfileDrawerProps) {
  if (!student) return null;

  const age = new Date().getFullYear() - new Date(student.birthdate).getFullYear();
  const isMinor = age < 18;
  const statusLabel = student.status === "active" ? "Activo" : "Inactivo";
  const statusClass = student.status === "active"
    ? "bg-success/15 text-success border-success/20"
    : "bg-muted text-muted-foreground border-border";

  const monthlyTotal = student.paymentType === "monthly"
    ? (typeof student.monthlyTotalOverride === "number"
      ? student.monthlyTotalOverride
      : student.enrolledClasses.reduce((sum, c) => sum + c.monthlyPrice, 0))
    : null;

  const visibleCustomFields = customFields.filter((field) => field.visible);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-md overflow-y-auto">
        <SheetHeader className="pb-4">
          <div className="flex items-center gap-3">
            <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-accent text-accent-foreground text-lg font-semibold">
              {student.name.split(" ").map((n) => n[0]).join("").slice(0, 2)}
            </div>
            <div className="flex-1 min-w-0">
              <SheetTitle className="text-lg">{student.name}</SheetTitle>
              <div className="flex items-center gap-2 mt-0.5">
                <Badge variant="outline" className={cn("text-[10px]", statusClass)}>{statusLabel}</Badge>
                {isMinor && (
                  <Badge variant="outline" className="text-[10px] bg-info/15 text-info border-info/20">Menor</Badge>
                )}
              </div>
            </div>
          </div>
        </SheetHeader>

        <div className="space-y-5">
          <section className="space-y-3">
            <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Datos de Contacto</h4>
            <div className="space-y-2.5">
              <InfoRow icon={Mail} label="Email" value={student.email} />
              <InfoRow icon={Phone} label="Teléfono" value={student.phone} />
                    <InfoRow icon={Calendar} label="Localidad" value={student.locality || "-"} />
                    <InfoRow icon={Calendar} label="Domicilio" value={student.address || "-"} />
                    <InfoRow icon={Calendar} label="Documento" value={student.identityDocumentType && student.identityDocumentNumber ? `${student.identityDocumentType === "dni" ? "DNI" : "Pasaporte"}: ${student.identityDocumentNumber}` : "-"} />
              <InfoRow icon={Calendar} label="Nacimiento" value={student.birthdate ? `${format(new Date(student.birthdate), "d MMM yyyy", { locale: es })} (${age} años)` : "N/A"} />
              <InfoRow icon={Calendar} label="Inscripción" value={student.joinDate ? format(new Date(student.joinDate), "d MMM yyyy", { locale: es }) : "N/A"} />
              <InfoRow icon={DollarSign} label="Tipo de pago" value={PAYMENT_LABELS[student.paymentType]} />
              {visibleCustomFields.map((field) => (
                <InfoRow
                  key={field.id}
                  icon={User}
                  label={field.label}
                  value={formatCustomFieldValue(student.extraData?.[field.key])}
                />
              ))}
            </div>
          </section>

          <Separator />

          {student.guardian && (
            <>
              <section className="space-y-3">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
                  <Shield className="h-3 w-3" /> Tutor / Responsable
                </h4>
                <div className="space-y-2.5">
                  <InfoRow icon={User} label="Nombre" value={student.guardian.name} />
                  <InfoRow icon={Phone} label="Teléfono" value={student.guardian.phone} />
                  <InfoRow icon={Mail} label="Email" value={student.guardian.email} />
                </div>
              </section>
              <Separator />
            </>
          )}

          <section className="space-y-3">
            <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
              <GraduationCap className="h-3 w-3" /> Clases Inscriptas ({student.enrolledClasses.length})
            </h4>
            {student.enrolledClasses.length === 0 ? (
              <p className="text-sm text-muted-foreground">Sin clases inscriptas actualmente.</p>
            ) : (
              <div className="space-y-2">
                {student.enrolledClasses.map((cls) => (
                  <div key={cls.id} className="flex items-center justify-between rounded-md border border-border bg-muted/30 px-3 py-2.5">
                    <div>
                      <p className="text-sm font-medium text-foreground">{cls.name}</p>
                      <div className="flex items-center gap-1.5 text-[10px] text-muted-foreground mt-0.5">
                        <Clock className="h-2.5 w-2.5" />
                        <span>{cls.day} · {cls.time}</span>
                      </div>
                    </div>
                    <span className="text-sm font-medium text-foreground">€{cls.monthlyPrice}</span>
                  </div>
                ))}
                {monthlyTotal !== null && (
                  <div className="flex items-center justify-between pt-2 border-t border-border">
                    <span className="text-sm font-semibold text-foreground">Total mensual</span>
                    <span className="text-base font-bold text-primary">€{monthlyTotal}</span>
                  </div>
                )}
              </div>
            )}
          </section>

          {student.notes && (
            <>
              <Separator />
              <section className="space-y-2">
                <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
                  <StickyNote className="h-3 w-3" /> Notas
                </h4>
                <p className="text-sm text-muted-foreground bg-muted/30 rounded-md p-3 border border-border">
                  {student.notes}
                </p>
              </section>
            </>
          )}

          <Separator />

          <section className="space-y-3">
            <h4 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1.5">
              <GraduationCap className="h-3 w-3" /> Certificaciones
            </h4>
            <p className="text-sm text-muted-foreground">
              Las certificaciones de exámenes aprobados aparecerán aquí.
            </p>
          </section>
        </div>
      </SheetContent>
    </Sheet>
  );
}

function InfoRow({ icon: Icon, label, value }: { icon: any; label: string; value: string }) {
  return (
    <div className="flex items-center gap-2.5">
      <Icon className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
      <div className="flex-1 min-w-0">
        <p className="text-[10px] text-muted-foreground">{label}</p>
        <p className="text-sm text-foreground truncate">{value}</p>
      </div>
    </div>
  );
}

