import { useEffect, useMemo, useState } from "react";
import { PageContainer } from "@/components/layout/PageContainer";
import { StatCard } from "@/components/cards/StatCard";
import { Users, CreditCard, TrendingUp, AlertTriangle, Loader2, Wallet, Trophy, Target, Activity, CircleDollarSign } from "lucide-react";
import { getAnalyticsData, getDashboardMetrics, type AnalyticsData, type DashboardMetrics } from "@/lib/api/payments";
import { getStudents } from "@/lib/api/students";
import { format } from "date-fns";
import { es } from "date-fns/locale";
import { Progress } from "@/components/ui/progress";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, LineChart, Line, Legend,
} from "recharts";

const CHART_COLORS = [
  "hsl(263, 70%, 58%)",
  "hsl(142, 71%, 45%)",
  "hsl(38, 92%, 50%)",
  "hsl(0, 84%, 60%)",
  "hsl(210, 92%, 55%)",
  "hsl(263, 70%, 78%)",
];

export default function AnalyticsPage() {
  const [analytics, setAnalytics] = useState<AnalyticsData | null>(null);
  const [metrics, setMetrics] = useState<DashboardMetrics | null>(null);
  const [students, setStudents] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadData() {
      try {
        setLoading(true);
        const [analyticsData, metricsData, studentsData] = await Promise.all([
          getAnalyticsData(),
          getDashboardMetrics(),
          getStudents(),
        ]);

        setAnalytics(analyticsData);
        setMetrics(metricsData);
        setStudents(studentsData || []);
      } catch (error) {
        console.error("Failed to load analytics:", error);
      } finally {
        setLoading(false);
      }
    }

    loadData();
  }, []);

  const totalStudents = students.length;
  const inactiveStudents = students.filter((s) => s.status === "inactive").length;
  const activeStudents = totalStudents - inactiveStudents;

  const revenueLineData = useMemo(() => {
    if (!analytics?.revenueByMonth) return [];
    const monthNames = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"];
    const allMonths = Array.from(
      new Set([
        ...Object.keys(analytics.revenueByMonth || {}),
        ...Object.keys(analytics.pendingByMonth || {}),
      ])
    ).sort((a, b) => a.localeCompare(b));

    return allMonths.map((month) => {
        const [y, m] = month.split("-");
        const paidCents = analytics.revenueByMonth?.[month] || 0;
        const pendingCents = analytics.pendingByMonth?.[month] || 0;
        return {
          name: `${monthNames[parseInt(m) - 1]} ${y}`,
          Cobrado: Math.round(paidCents / 100),
          Pendiente: Math.round(pendingCents / 100),
          CobroPct: analytics.collectionRateByMonth?.[month] || 0,
        };
      });
  }, [analytics]);

  const enrollmentsByStatus = useMemo(() => {
    if (!analytics?.enrollmentsByStatus) return [];
    const labels: Record<string, string> = {
      pending: "Pendiente",
      confirmed: "Confirmada",
      declined: "Rechazada",
      cancelled: "Cancelada",
    };
    return Object.entries(analytics.enrollmentsByStatus).map(([key, value]) => ({
      name: labels[key] || key,
      value,
    }));
  }, [analytics]);

  const methodDistribution = useMemo(() => {
    if (!analytics?.methodDistribution) return [];
    return Object.entries(analytics.methodDistribution).map(([name, value]) => ({
      name,
      value,
    }));
  }, [analytics]);

  const studentsPerClass = useMemo(() => {
    if (!analytics?.studentsByClass) return [];
    return Object.entries(analytics.studentsByClass)
      .map(([name, alumnos]) => ({
        name: name.length > 18 ? name.slice(0, 18) + "…" : name,
        alumnos,
      }))
      .sort((a, b) => b.alumnos - a.alumnos)
      .slice(0, 8);
  }, [analytics]);

  const formatCurrency = (value: number) => `${value.toLocaleString("es-ES")} €`;
  const formatShortDate = (value: string | null) => {
    if (!value) return "Sin fecha";
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? "Sin fecha" : format(parsed, "d MMM", { locale: es });
  };

  if (loading) {
    return (
      <PageContainer title="Analíticas" description="Control financiero y comercial en tiempo real">
        <div className="flex items-center justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      </PageContainer>
    );
  }

  const activeStudentsBase = analytics?.activeStudentsCount || activeStudents;
  const payingStudents = analytics?.payingStudentsCount || 0;
  const payingStudentsPct = analytics?.payingStudentsPct || 0;
  const potentialRevenue = analytics?.potentialRevenue || 0;
  const potentialCollectionPct = analytics?.potentialCollectionPct || 0;
  const totalRevenue = analytics?.totalRevenue || 0;
  const pendingRevenue = analytics?.pendingRevenue || 0;
  const overdueRevenue = analytics?.overdueRevenue || 0;
  const collectionRatePct = analytics?.collectionRatePct || 0;
  const totalEnrollments = Object.values(analytics?.enrollmentsByStatus || {}).reduce((a: number, b: number) => a + b, 0);
  const revenueGap = Math.max(0, potentialRevenue - totalRevenue);

  return (
    <PageContainer
      title="Analíticas"
      description="Control financiero y comercial en tiempo real"
    >
      <div className="mb-3">
        <h3 className="text-sm font-semibold text-foreground">1. Pulso de caja</h3>
      </div>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard
          title="Ingresos totales"
          value={formatCurrency(totalRevenue)}
          change={`${totalEnrollments} inscripciones analizadas`}
          changeType="positive"
          icon={CreditCard}
        />
        <StatCard
          title="Pendiente de cobro"
          value={formatCurrency(pendingRevenue)}
          change={overdueRevenue > 0 ? `${formatCurrency(overdueRevenue)} en riesgo de impago` : "Sin importe vencido"}
          changeType={overdueRevenue > 0 ? "negative" : "neutral"}
          icon={AlertTriangle}
        />
        <StatCard
          title="Tasa de cobro"
          value={`${collectionRatePct}%`}
          change={`${formatCurrency(totalRevenue)} cobrados · ${formatCurrency(pendingRevenue)} pendientes`}
          changeType="positive"
          icon={TrendingUp}
        />
        <StatCard
          title="Pagos vencidos"
          value={analytics?.overduePaymentsCount || 0}
          change={
            (analytics?.overduePaymentsCount || 0) > 0
              ? `${analytics?.overdueStudentsCount || 0} alumno(s) afectados`
              : "Todo al día"
          }
          changeType={(analytics?.overduePaymentsCount || 0) > 0 ? "negative" : "positive"}
          icon={Activity}
        />
      </div>

      <div className="mt-4 rounded-lg border border-border bg-card p-5 shadow-soft">
        <div className="mb-2 flex items-center justify-between">
          <p className="text-sm font-medium text-foreground">Cobrado vs pendiente</p>
          <p className="text-xs text-muted-foreground">{collectionRatePct}% cobrado</p>
        </div>
        <Progress value={collectionRatePct} className="h-2" />
      </div>

      <div className="mt-6 mb-3">
        <h3 className="text-sm font-semibold text-foreground">2. Eficiencia operativa</h3>
      </div>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard
          title="Ingreso medio por alumno (mes)"
          value={formatCurrency(analytics?.avgRevenuePerActiveStudent || 0)}
          change="Depende de cuántos alumnos han pagado este mes"
          changeType="neutral"
          icon={Users}
          tooltip="Ingresos totales dividido entre alumnos activos"
        />
        <StatCard
          title="Precio medio por cuota"
          value={formatCurrency(analytics?.avgPaymentAmount || 0)}
          change="Media de los pagos realizados"
          changeType="positive"
          icon={Wallet}
          tooltip="Importe medio de cada cobro realizado"
        />
        <StatCard
          title="Alumnos que pagan"
          value={`${payingStudents} / ${activeStudentsBase}`}
          change={`${payingStudentsPct}% de alumnos activos`}
          changeType={payingStudentsPct >= 70 ? "positive" : payingStudentsPct >= 40 ? "neutral" : "negative"}
          icon={CircleDollarSign}
        />
        <StatCard
          title="Tasa de inscripción"
          value={`${metrics?.enrollmentRate || 0}%`}
          change={`${totalEnrollments} inscripciones totales`}
          changeType="positive"
          icon={TrendingUp}
        />
        <StatCard
          title="Ocupación vs ingresos"
          value={`${analytics?.occupancyPct || 0}% ocupación`}
          change={`${formatCurrency(analytics?.revenuePerConfirmedEnrollment || 0)} por plaza ocupada`}
          changeType={(analytics?.occupancyPct || 0) >= 70 ? "positive" : "neutral"}
          icon={Target}
        />
      </div>

      <div className="mt-6 mb-3">
        <h3 className="text-sm font-semibold text-foreground">3. Potencial capturable</h3>
      </div>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        <StatCard
          title="Ingreso potencial vs real"
          value={`${formatCurrency(totalRevenue)} / ${formatCurrency(potentialRevenue)}`}
          change={`${potentialCollectionPct}% del potencial mensual`}
          changeType={potentialCollectionPct >= 80 ? "positive" : potentialCollectionPct >= 50 ? "neutral" : "negative"}
          icon={Target}
        />
        <StatCard
          title="Gap de ingresos"
          value={formatCurrency(revenueGap)}
          change={revenueGap > 0 ? "Importe recuperable si sube el porcentaje de cobro" : "Sin gap relevante"}
          changeType={revenueGap > 0 ? "neutral" : "positive"}
          icon={AlertTriangle}
        />
        <StatCard
          title="Alumnos activos"
          value={activeStudentsBase}
          change={`${inactiveStudents} inactivos de ${totalStudents}`}
          changeType="neutral"
          icon={Users}
        />
      </div>

      {/* Charts row 1 */}
      <div className="grid gap-4 lg:grid-cols-2 mt-6">
        {/* Revenue line chart */}
        <div className="rounded-lg border border-border bg-card p-5 shadow-soft">
          <h3 className="text-sm font-semibold text-foreground mb-4">Tendencia de cobro mensual</h3>
          <ResponsiveContainer width="100%" height={260}>
            <LineChart data={revenueLineData}>
              <CartesianGrid strokeDasharray="3 3" stroke="hsl(215, 20%, 91%)" />
              <XAxis dataKey="name" tick={{ fontSize: 11 }} stroke="hsl(215, 14%, 46%)" />
              <YAxis yAxisId="left" tick={{ fontSize: 11 }} stroke="hsl(215, 14%, 46%)" tickFormatter={(v) => `${v}€`} />
              <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 11 }} stroke="hsl(215, 14%, 46%)" domain={[0, 100]} tickFormatter={(v) => `${v}%`} />
              <Tooltip formatter={(v: number, key: string) => key === "CobroPct" ? `${v}%` : `${v.toLocaleString("es-ES")} €`} />
              <Legend wrapperStyle={{ fontSize: 12 }} />
              <Line yAxisId="left" type="monotone" dataKey="Cobrado" stroke="hsl(142, 71%, 45%)" strokeWidth={2} dot={{ r: 4 }} />
              <Line yAxisId="left" type="monotone" dataKey="Pendiente" stroke="hsl(38, 92%, 50%)" strokeWidth={2} dot={{ r: 4 }} />
              <Line yAxisId="right" type="monotone" dataKey="CobroPct" stroke="hsl(210, 92%, 55%)" strokeWidth={2} dot={{ r: 3 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>

        {/* Students per class */}
        <div className="rounded-lg border border-border bg-card p-5 shadow-soft">
          <h3 className="text-sm font-semibold text-foreground mb-4">Alumnos por Clase</h3>
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={studentsPerClass} layout="vertical" margin={{ left: 10 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="hsl(215, 20%, 91%)" />
              <XAxis type="number" tick={{ fontSize: 11 }} stroke="hsl(215, 14%, 46%)" />
              <YAxis type="category" dataKey="name" width={120} tick={{ fontSize: 10 }} stroke="hsl(215, 14%, 46%)" />
              <Tooltip />
              <Bar dataKey="alumnos" fill="hsl(263, 70%, 58%)" radius={[0, 4, 4, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Charts row 2 */}
      <div className="grid gap-4 lg:grid-cols-2 mt-4">
        {/* Enrollment status pie */}
        <div className="rounded-lg border border-border bg-card p-5 shadow-soft">
          <h3 className="text-sm font-semibold text-foreground mb-4">Inscripciones por Estado</h3>
          <ResponsiveContainer width="100%" height={240}>
            <PieChart>
              <Pie
                data={enrollmentsByStatus}
                cx="50%"
                cy="50%"
                innerRadius={55}
                outerRadius={90}
                paddingAngle={3}
                dataKey="value"
                label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                labelLine={false}
              >
                {enrollmentsByStatus.map((_, i) => (
                  <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        {/* Payment method pie */}
        <div className="rounded-lg border border-border bg-card p-5 shadow-soft">
          <h3 className="text-sm font-semibold text-foreground mb-4">Distribución por Método de Pago</h3>
          <ResponsiveContainer width="100%" height={240}>
            <PieChart>
              <Pie
                data={methodDistribution}
                cx="50%"
                cy="50%"
                innerRadius={55}
                outerRadius={90}
                paddingAngle={3}
                dataKey="value"
                label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                labelLine={false}
              >
                {methodDistribution.map((_, i) => (
                  <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid gap-4 lg:grid-cols-2 mt-4">
        <div className="rounded-lg border border-border bg-card p-5 shadow-soft">
          <div className="flex items-center gap-2 mb-4">
            <Trophy className="h-4 w-4 text-primary" />
            <h3 className="text-sm font-semibold text-foreground">Alumnos que más pagan</h3>
          </div>
          <div className="space-y-3">
            {(analytics?.topPayingStudents || []).length === 0 ? (
              <p className="text-sm text-muted-foreground">Todavía no hay pagos suficientes para calcular el ranking.</p>
            ) : (
              analytics?.topPayingStudents.map((student, index) => (
                <div key={student.studentId} className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
                  <div>
                    <p className="text-sm font-medium text-foreground">{index + 1}. {student.studentName}</p>
                    <p className="text-xs text-muted-foreground">
                      {student.paymentsCount} cobro(s) · ticket medio {formatCurrency(student.avgPayment)} · último pago {formatShortDate(student.lastPaymentAt)}
                    </p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-semibold text-foreground">{formatCurrency(student.totalPaid)}</p>
                    <p className="text-xs text-muted-foreground">acumulado</p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="rounded-lg border border-border bg-card p-5 shadow-soft">
          <div className="flex items-center gap-2 mb-4">
            <AlertTriangle className="h-4 w-4 text-warning" />
            <h3 className="text-sm font-semibold text-foreground">Mayor saldo pendiente</h3>
          </div>
          <div className="space-y-3">
            {(analytics?.highestPendingBalances || []).length === 0 ? (
              <p className="text-sm text-muted-foreground">No hay deuda pendiente acumulada en este momento.</p>
            ) : (
              analytics?.highestPendingBalances.map((student) => (
                <div key={student.studentId} className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
                  <div>
                    <p className="text-sm font-medium text-foreground">{student.studentName}</p>
                    <p className="text-xs text-muted-foreground">
                      {student.itemsCount} recibo(s) pendiente(s) · último vencimiento {formatShortDate(student.latestDueAt)}
                    </p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-semibold text-warning">{formatCurrency(student.pendingAmount)}</p>
                    <p className="text-xs text-muted-foreground">por recuperar</p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </PageContainer>
  );
}

import { useEffect, useMemo, useState } from "react";
import { PageContainer } from "@/components/layout/PageContainer";
import { StatCard } from "@/components/cards/StatCard";
import {
  Users,
  AlertTriangle,
  ClipboardList,
  ArrowRight,
  CheckCircle,
  UserPlus,
  Loader2,
  CircleDollarSign,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { useNavigate } from "react-router-dom";
import { format, isValid } from "date-fns";
import { es } from "date-fns/locale";
import { getDashboardMetrics, getAnalyticsData } from "@/lib/api/payments";
import { getScheduleInsights, type ScheduleInsightsResult } from "@/lib/api/schedules";
import { getEnrollments } from "@/lib/api/enrollments";
import { getPayments } from "@/lib/api/payments";
import { getTeachers } from "@/lib/api/teachers";
import { buildEconomySnapshot } from "@/lib/economy";
import { ScheduleInsightsPanel } from "@/components/schedule/ScheduleInsightsPanel";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";

export default function DashboardPage() {
  const navigate = useNavigate();
  const [metrics, setMetrics] = useState<Awaited<ReturnType<typeof getDashboardMetrics>> | null>(null);
  const [analytics, setAnalytics] = useState<Awaited<ReturnType<typeof getAnalyticsData>> | null>(null);
  const [scheduleInsights, setScheduleInsights] = useState<ScheduleInsightsResult | null>(null);
  const [enrollments, setEnrollments] = useState<any[]>([]);
  const [payments, setPayments] = useState<any[]>([]);
  const [teachers, setTeachers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadData() {
      try {
        setLoading(true);
        const [metricsData, analyticsData, enrollmentsData, paymentsData, insightsData, teachersData] = await Promise.all([
          getDashboardMetrics(),
          getAnalyticsData(),
          getEnrollments(),
          getPayments(),
          getScheduleInsights(),
          getTeachers(),
        ]);
        setMetrics(metricsData);
        setAnalytics(analyticsData);
        setEnrollments(enrollmentsData || []);
        setPayments(paymentsData || []);
        setScheduleInsights(insightsData);
        setTeachers(teachersData || []);
      } catch (error) {
        console.error("Failed to load dashboard data:", error);
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, []);

  const overduePayments = useMemo(
    () => payments.filter((p) => p.status === "overdue" || p.status === "pending"),
    [payments]
  );

  const recentEnrollments = useMemo(
    () => enrollments.slice(0, 5),
    [enrollments]
  );

  const economy = useMemo(
    () => buildEconomySnapshot({ payments: payments || [], teachers: teachers || [], months: 6 }),
    [payments, teachers]
  );

  const revenueByMonth = useMemo(() => {
    if (!analytics?.revenueByMonth) return [];
    const monthNames = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"];
    return Object.entries(analytics.revenueByMonth)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([month, total]) => {
        const [, m] = month.split("-");
        return { name: monthNames[parseInt(m) - 1], total: Math.round(total / 100) };
      })
      .slice(-6);
  }, [analytics]);

  const STATUS_STYLES: Record<string, string> = {
    pending: "bg-warning/10 text-warning border-warning/20",
    confirmed: "bg-success/10 text-success border-success/20",
    declined: "bg-destructive/10 text-destructive border-destructive/20",
    cancelled: "bg-muted text-muted-foreground border-border",
  };
  const STATUS_LABELS: Record<string, string> = {
    pending: "Pendiente", confirmed: "Confirmada", declined: "Rechazada", cancelled: "Cancelada",
  };

  const formatSafeDate = (value: unknown) => {
    if (!value) return "Sin fecha";
    const parsed = new Date(value as string | number | Date);
    return isValid(parsed) ? format(parsed, "d MMM", { locale: es }) : "Sin fecha";
  };

  if (loading) {
    return (
      <PageContainer title="Dashboard" description="Vista general de tu academia">
        <div className="flex items-center justify-center py-16">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer title="Dashboard" description="Vista general de tu academia">
      {/* KPIs */}
      <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
        <StatCard 
          title="Alumnos activos" 
          value={metrics?.activeStudents ?? 0} 
          change={`${metrics?.totalStudents ?? 0} en total`} 
          changeType="neutral" 
          icon={Users} 
        />
        <StatCard 
          title={`Ingresos ${new Date().toLocaleString("es-ES", { month: "short" })}`} 
          value={`${(metrics?.monthRevenue ?? 0).toLocaleString()}€`} 
          change={
            (metrics?.overduePayments ?? 0) > 0 
              ? `${metrics?.overduePayments} pendientes` 
              : "Todo al día"
          } 
          changeType={(metrics?.overduePayments ?? 0) > 0 ? "negative" : "positive"} 
          icon={CircleDollarSign} 
        />
        <StatCard 
          title="Inscripciones" 
          value={metrics?.pendingEnrollments ?? 0} 
          change="pendientes" 
          changeType={(metrics?.pendingEnrollments ?? 0) > 0 ? "neutral" : "positive"} 
          icon={ClipboardList} 
        />
      </div>

      {/* Alerts */}
      {((metrics?.overduePayments ?? 0) > 0 || (metrics?.pendingEnrollments ?? 0) > 0) && (
        <div className="flex flex-wrap gap-3">
          {(metrics?.overduePayments ?? 0) > 0 && (
            <button
              onClick={() => navigate("/admin/payments")}
              className="flex items-center gap-2 rounded-lg border border-destructive/15 bg-destructive/5 px-4 py-2.5 text-sm text-destructive hover:bg-destructive/10 transition-colors"
            >
              <AlertTriangle className="h-4 w-4" />
              <span className="font-medium">{metrics?.overduePayments} pagos pendientes</span>
              <ArrowRight className="h-3.5 w-3.5" />
            </button>
          )}
          {(metrics?.pendingEnrollments ?? 0) > 0 && (
            <button
              onClick={() => navigate("/admin/enrollments")}
              className="flex items-center gap-2 rounded-lg border border-warning/15 bg-warning/5 px-4 py-2.5 text-sm text-warning hover:bg-warning/10 transition-colors"
            >
              <ClipboardList className="h-4 w-4" />
              <span className="font-medium">{metrics?.pendingEnrollments} inscripciones pendientes</span>
              <ArrowRight className="h-3.5 w-3.5" />
            </button>
          )}
        </div>
      )}

      {/* Revenue chart + Financial status */}
      <div className="grid gap-5 lg:grid-cols-3">
        <div className="lg:col-span-2 rounded-xl border border-border bg-card p-6">
          <div className="flex items-center justify-between mb-5">
            <h3 className="text-sm font-medium text-foreground">Ingresos</h3>
            <Button variant="ghost" size="sm" className="text-xs h-7" onClick={() => navigate("/admin/analytics")}>
              Ver más <ArrowRight className="h-3 w-3 ml-1" />
            </Button>
          </div>
          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={revenueByMonth}>
              <CartesianGrid strokeDasharray="3 3" stroke="hsl(220, 14%, 92%)" />
              <XAxis dataKey="name" tick={{ fontSize: 11 }} stroke="hsl(220, 10%, 50%)" />
              <YAxis tick={{ fontSize: 11 }} stroke="hsl(220, 10%, 50%)" tickFormatter={(v) => `${v}€`} />
              <Tooltip formatter={(v: number) => `${v.toLocaleString()}€`} />
              <Bar dataKey="total" fill="hsl(var(--primary))" radius={[6, 6, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="rounded-xl border border-border bg-card p-6">
          <h3 className="text-sm font-medium text-foreground mb-5">Balance mensual</h3>
          <div className="space-y-4">
            <div>
              <p className="text-xs text-muted-foreground">Ingresos</p>
              <p className="text-xl font-semibold text-foreground mt-0.5">{economy.monthlyIncome.toLocaleString()}€</p>
            </div>
            <div>
              <p className="text-xs text-muted-foreground">Gastos</p>
              <p className="text-xl font-semibold text-foreground mt-0.5">{economy.monthlyExpenses.toLocaleString()}€</p>
            </div>
            <div className="pt-3 border-t border-border">
              <p className="text-xs text-muted-foreground">Balance</p>
              <p className={cn("text-xl font-semibold mt-0.5", economy.monthlyBalance >= 0 ? "text-success" : "text-destructive")}>
                {economy.monthlyBalance >= 0 ? "+" : ""}{economy.monthlyBalance.toLocaleString()}€
              </p>
            </div>
            <Button className="w-full" variant="outline" size="sm" onClick={() => navigate("/admin/economia")}>Ver economía</Button>
          </div>
        </div>
      </div>

      {/* Schedule insights */}
      <ScheduleInsightsPanel
        insights={scheduleInsights}
        compact
        onViewSchedule={() => navigate("/admin/schedule")}
      />

      {/* Activity + Payments */}
      <div className="grid gap-5 lg:grid-cols-2">
        <div className="rounded-xl border border-border bg-card p-6">
          <div className="flex items-center justify-between mb-5">
            <h3 className="text-sm font-medium text-foreground">Actividad reciente</h3>
            <Button variant="ghost" size="sm" className="text-xs h-7" onClick={() => navigate("/admin/enrollments")}>
              Ver todas <ArrowRight className="h-3 w-3 ml-1" />
            </Button>
          </div>
          {recentEnrollments.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 text-center">
              <UserPlus className="h-5 w-5 text-muted-foreground mb-2" />
              <p className="text-sm text-muted-foreground">Sin actividad reciente</p>
            </div>
          ) : (
            <div className="space-y-1">
              {recentEnrollments.slice(0, 4).map((e) => (
                <div key={e.id} className="flex items-center justify-between py-2.5 border-b border-border/50 last:border-0">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-accent">
                      <UserPlus className="h-3 w-3 text-accent-foreground" />
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-medium text-foreground truncate">{e.studentName}</p>
                      <p className="text-[11px] text-muted-foreground">{formatSafeDate(e.createdAt)}</p>
                    </div>
                  </div>
                  <Badge variant="outline" className={cn("text-[10px] font-medium shrink-0", STATUS_STYLES[e.status])}>
                    {STATUS_LABELS[e.status]}
                  </Badge>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="rounded-xl border border-border bg-card p-6">
          <div className="flex items-center justify-between mb-5">
            <h3 className="text-sm font-medium text-foreground">Pagos pendientes</h3>
            <Button variant="ghost" size="sm" className="text-xs h-7" onClick={() => navigate("/admin/payments")}>
              Ver todos <ArrowRight className="h-3 w-3 ml-1" />
            </Button>
          </div>
          {overduePayments.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 text-center">
              <CheckCircle className="h-6 w-6 text-success mb-2" />
              <p className="text-sm font-medium text-foreground">Todo al día</p>
            </div>
          ) : (
            <div className="space-y-1">
              {overduePayments.slice(0, 5).map((p) => (
                <div key={p.id} className="flex items-center justify-between py-2.5 border-b border-border/50 last:border-0">
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-foreground truncate">{p.studentName}</p>
                    <p className="text-[11px] text-muted-foreground">{p.concept.slice(0, 35)}</p>
                  </div>
                  <p className="text-sm font-semibold text-destructive shrink-0">{p.amount.toLocaleString()}€</p>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </PageContainer>
  );
}

import { useState, useCallback, useEffect, useMemo } from "react";
import { PageContainer } from "@/components/layout/PageContainer";
import { PaymentsTable } from "@/components/tables/PaymentsTable";
import { PaymentDetailDrawer } from "@/components/tables/PaymentDetailDrawer";
import { RecordPaymentModal } from "@/components/tables/RecordPaymentModal";
import {
  getPayments,
  recordPayment,
  updatePaymentStatus,
  getInvoices,
  generateMonthlyInvoices,
  getInvoiceDetail,
  markInvoiceAsPaid,
  deleteInvoice,
  createCashReceiptBatch,
  downloadReceiptBatchPdf,
  downloadPaymentReceiptPdf,
  type PaymentRecord,
  type InvoiceRecord,
  type InvoiceDetail,
} from "@/lib/api/payments";
import { getEnrollments } from "@/lib/api/enrollments";
import { redirectToStripeCheckout } from "@/lib/api/stripe";
import { toast } from "sonner";
import { Loader2, Copy, DollarSign, FileText, AlertTriangle, Eye, Trash2 } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Checkbox } from "@/components/ui/checkbox";
import { useSearchParams } from "react-router-dom";

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString("es-ES", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
}

function getCurrentMonth() {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
}

function formatPaymentMethodLabel(value?: string) {
  const normalized = (value || "").trim().toLowerCase();
  if (!normalized) return "-";

  if (normalized === "cash" || normalized === "efectivo" || normalized === "manual") {
    return "Efectivo";
  }
  if (normalized === "transfer" || normalized === "transferencia" || normalized === "bank_transfer") {
    return "Transferencia bancaria";
  }
  if (normalized === "card" || normalized === "tarjeta") {
    return "Tarjeta";
  }
  if (normalized === "mercadopago") {
    return "Mercado Pago";
  }

  return value || "-";
}

export default function PaymentsPage() {
  const [searchParams, setSearchParams] = useSearchParams();

  // Payments state
  const [payments, setPayments] = useState<PaymentRecord[]>([]);
  const [selectedPayment, setSelectedPayment] = useState<PaymentRecord | null>(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);

  // Invoices state
  const [invoices, setInvoices] = useState<InvoiceRecord[]>([]);
  const [selectedInvoice, setSelectedInvoice] = useState<InvoiceDetail | null>(null);
  const [invoiceDetailOpen, setInvoiceDetailOpen] = useState(false);
  const [generateDialogOpen, setGenerateDialogOpen] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonth());
  const [receiptMonth, setReceiptMonth] = useState<string>(getCurrentMonth());

  // Invoice filters
  const [invoiceMonthFilter, setInvoiceMonthFilter] = useState<string>("all");
  const [invoiceStatusFilter, setInvoiceStatusFilter] = useState<string>("all");
  const [invoiceSearchFilter, setInvoiceSearchFilter] = useState<string>("");
  const [selectedInvoiceIds, setSelectedInvoiceIds] = useState<string[]>([]);

  // Loading state
  const [initialLoading, setInitialLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [generatingInvoices, setGeneratingInvoices] = useState(false);
  const [markingInvoiceId, setMarkingInvoiceId] = useState<string | null>(null);
  const [bulkAction, setBulkAction] = useState<"mark-paid" | "delete" | null>(null);
  const [generatingReceipts, setGeneratingReceipts] = useState(false);
  const [generatingReceiptPaymentId, setGeneratingReceiptPaymentId] = useState<string | null>(null);
  const [acceptedEnrollments, setAcceptedEnrollments] = useState<Array<{ studentId?: string; studentName: string }>>([]);

  const loadData = useCallback(async (options?: { background?: boolean }) => {
    const background = options?.background ?? false;

    try {
      if (background) {
        setRefreshing(true);
      } else {
        setInitialLoading(true);
      }

      const [paymentsData, invoicesData, enrollmentsData] = await Promise.all([
        getPayments(),
        getInvoices(),
        getEnrollments(),
      ]);
      setPayments(paymentsData || []);
      setInvoices(invoicesData || []);
      setAcceptedEnrollments(
        (enrollmentsData || [])
          .filter((enrollment) => enrollment.status === "confirmed")
          .map((enrollment) => ({ studentId: enrollment.studentId, studentName: enrollment.studentName }))
      );
    } catch (error) {
      console.error("Failed to load data:", error);
      toast.error("Error al cargar los datos");
    } finally {
      if (background) {
        setRefreshing(false);
      } else {
        setInitialLoading(false);
      }
    }
  }, []);

  useEffect(() => {
    void loadData();
  }, [loadData]);

  useEffect(() => {
    if (initialLoading) {
      return;
    }

    const targetId = searchParams.get("id");
    const action = searchParams.get("action");

    if (!targetId || action !== "preview") {
      return;
    }

    const targetPayment = payments.find((payment) => payment.id === targetId);
    if (!targetPayment) {
      return;
    }

    handleViewDetail(targetPayment);
    setSearchParams({}, { replace: true });
  }, [initialLoading, payments, searchParams, setSearchParams]);

  // Payments handlers
  const handleViewDetail = (payment: PaymentRecord) => {
    setSelectedPayment(payment);
    setDrawerOpen(true);
  };

  const handleMarkPaid = useCallback(async (id: string) => {
    try {
      await updatePaymentStatus(id, "paid");
      setPayments((prev) => prev.map((p) => (p.id === id ? { ...p, status: "paid" } : p)));
      setSelectedPayment((prev) => prev && prev.id === id ? { ...prev, status: "paid" } : prev);
      toast.success("Pago marcado como pagado");
    } catch (error) {
      toast.error("Error al actualizar el pago");
    }
  }, []);

  const handleMarkRefunded = useCallback(async (id: string) => {
    try {
      await updatePaymentStatus(id, "refunded");
      setPayments((prev) => prev.map((p) => (p.id === id ? { ...p, status: "refunded" } : p)));
      setSelectedPayment((prev) => prev && prev.id === id ? { ...prev, status: "refunded" } : prev);
      toast.success("Pago marcado como reembolsado");
    } catch (error) {
      toast.error("Error al actualizar el pago");
    }
  }, []);

  const handleGenerateReceipt = useCallback(async (payment: PaymentRecord) => {
    if (generatingReceiptPaymentId) {
      return;
    }

    try {
      setGeneratingReceiptPaymentId(payment.id);
      const blob = await downloadPaymentReceiptPdf(payment.id);
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = `recibo-${payment.studentName.replace(/\s+/g, "-").toLowerCase()}-${payment.month}.pdf`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      URL.revokeObjectURL(url);

      await loadData({ background: true });
      toast.success(`Recibo generado para ${payment.studentName}`);
    } catch (error) {
      console.error("Failed to generate payment receipt:", error);
      toast.error("No se pudo generar el recibo para este pago");
    } finally {
      setGeneratingReceiptPaymentId(null);
    }
  }, [generatingReceiptPaymentId]);

  const handleGenerateCashReceiptsBatch = useCallback(async () => {
    try {
      setGeneratingReceipts(true);
      const batch = await createCashReceiptBatch(receiptMonth);

      if (!batch) {
        toast.error("No se pudo crear el lote de recibos");
        return;
      }

      if (batch.generatedCount === 0) {
        toast.info("No hay pagos en efectivo pendientes de recibo para el período seleccionado");
        return;
      }

      const pdfBlob = await downloadReceiptBatchPdf(batch.batchId);
      const url = URL.createObjectURL(pdfBlob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = `recibos-efectivo-${batch.month}.pdf`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      URL.revokeObjectURL(url);

      toast.success(`Lote generado: ${batch.generatedCount} recibo(s) en PDF`);
    } catch (error) {
      console.error("Failed to generate receipts batch:", error);
      toast.error("Error al generar o descargar el lote de recibos");
    } finally {
      setGeneratingReceipts(false);
    }
  }, [receiptMonth]);

  const handleRecordPayment = useCallback(async (data: { studentId: string; amount: number; metadata: Record<string, unknown> }) => {
    try {
      const newPayment = await recordPayment({
        studentId: data.studentId,
        amount: data.amount,
        status: "paid",
        metadata: data.metadata,
      });
      if (newPayment) {
        setPayments((prev) => [newPayment, ...prev]);
        setPaymentModalOpen(false);
        toast.success("Pago registrado correctamente");
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : "Error al registrar el pago";
      toast.error(message);
    }
  }, []);

  const handleStripeCheckout = useCallback(async (data: { studentId: string; amount: number; metadata: Record<string, unknown> }) => {
    try {
      await redirectToStripeCheckout({
        amount: data.amount,
        currency: "eur",
        description: String(data.metadata.concept || "Pago Nexa"),
        metadata: {
          studentId: data.studentId,
          studentName: String(data.metadata.student_name || ""),
          studentEmail: String(data.metadata.student_email || ""),
          period: String(data.metadata.month || ""),
        },
        successUrl: `${window.location.origin}/admin/payments?stripe=success`,
        cancelUrl: `${window.location.origin}/admin/payments?stripe=cancel`,
      });
    } catch (error) {
      console.error("Failed to start Stripe checkout:", error);
      toast.error(error instanceof Error ? error.message : "No se pudo iniciar el cobro con Stripe");
    }
  }, []);

  // Invoices handlers
  const handleGenerateMonthlyInvoices = async () => {
    try {
      setGeneratingInvoices(true);
      const result = await generateMonthlyInvoices(selectedMonth);

      if (result) {
        await loadData({ background: true }); // Reload invoices
        setGenerateDialogOpen(false);
        toast.success(`${result.created} factura(s) generada(s) para ${selectedMonth}`);
      }
    } catch (error) {
      console.error("Failed to generate invoices:", error);
      toast.error("Error al generar las facturas");
    } finally {
      setGeneratingInvoices(false);
    }
  };

  const handleViewInvoiceDetail = async (invoice: InvoiceRecord) => {
    try {
      const detail = await getInvoiceDetail(invoice.id);
      if (detail) {
        setSelectedInvoice(detail);
        setInvoiceDetailOpen(true);
      }
    } catch (error) {
      toast.error("Error al cargar los detalles de la factura");
    }
  };

  const handleMarkInvoiceAsPaid = useCallback(async (invoice: InvoiceRecord) => {
    if (markingInvoiceId) {
      return;
    }

    try {
      setMarkingInvoiceId(invoice.id);
      const updated = await markInvoiceAsPaid(invoice.id, {
        paymentMethod: "cash",
      });

      if (!updated) {
        toast.error("No se pudo marcar la factura como pagada");
        return;
      }

      await loadData({ background: true });
      toast.success(`Factura ${invoice.invoiceNumber} marcada como pagada`);
    } catch (error) {
      console.error("Failed to mark invoice as paid:", error);
      toast.error("Error al marcar la factura como pagada");
    } finally {
      setMarkingInvoiceId(null);
    }
  }, [markingInvoiceId]);

  const handleDeleteInvoice = useCallback(async (invoice: InvoiceRecord) => {
    const confirmed = window.confirm(`Eliminar la factura ${invoice.invoiceNumber} de ${invoice.studentName}?`);
    if (!confirmed) {
      return;
    }

    try {
      const ok = await deleteInvoice(invoice.id);
      if (!ok) {
        toast.error("No se pudo eliminar la factura");
        return;
      }

      await loadData({ background: true });
      setSelectedInvoiceIds((prev) => prev.filter((id) => id !== invoice.id));
      toast.success(`Factura ${invoice.invoiceNumber} eliminada`);
    } catch (error) {
      console.error("Failed to delete invoice:", error);
      toast.error("Error al eliminar la factura");
    }
  }, []);

  // Filter invoices
  const filteredInvoices = useMemo(() => {
    return invoices.filter((invoice) => {
      const matchesMonth = invoiceMonthFilter === "all" || invoice.month === invoiceMonthFilter;
      const matchesStatus = invoiceStatusFilter === "all" || invoice.status === invoiceStatusFilter;
      const matchesSearch =
        invoiceSearchFilter === "" ||
        invoice.studentName.toLowerCase().includes(invoiceSearchFilter.toLowerCase()) ||
        invoice.invoiceNumber.toLowerCase().includes(invoiceSearchFilter.toLowerCase());
      return matchesMonth && matchesStatus && matchesSearch;
    });
  }, [invoices, invoiceMonthFilter, invoiceStatusFilter, invoiceSearchFilter]);

  const selectableInvoices = useMemo(
    () => filteredInvoices.filter((invoice) => invoice.status !== "paid"),
    [filteredInvoices]
  );

  const allSelectableChecked =
    selectableInvoices.length > 0 && selectableInvoices.every((invoice) => selectedInvoiceIds.includes(invoice.id));

  const someSelectableChecked =
    selectableInvoices.some((invoice) => selectedInvoiceIds.includes(invoice.id)) && !allSelectableChecked;

  const selectedInvoices = useMemo(
    () => filteredInvoices.filter((invoice) => selectedInvoiceIds.includes(invoice.id)),
    [filteredInvoices, selectedInvoiceIds]
  );

  const selectedUnpaidInvoices = useMemo(
    () => selectedInvoices.filter((invoice) => invoice.status !== "paid"),
    [selectedInvoices]
  );

  useEffect(() => {
    const visibleIds = new Set(filteredInvoices.map((invoice) => invoice.id));
    setSelectedInvoiceIds((prev) => prev.filter((id) => visibleIds.has(id)));
  }, [filteredInvoices]);

  const toggleInvoiceSelection = useCallback((invoiceId: string, checked: boolean) => {
    setSelectedInvoiceIds((prev) => {
      if (checked) {
        if (prev.includes(invoiceId)) return prev;
        return [...prev, invoiceId];
      }

      return prev.filter((id) => id !== invoiceId);
    });
  }, []);

  const toggleAllSelectableInvoices = useCallback((checked: boolean) => {
    if (!checked) {
      setSelectedInvoiceIds([]);
      return;
    }

    setSelectedInvoiceIds(selectableInvoices.map((invoice) => invoice.id));
  }, [selectableInvoices]);

  const handleBulkMarkInvoicesAsPaid = useCallback(async () => {
    if (selectedUnpaidInvoices.length === 0 || bulkAction) {
      return;
    }

    setBulkAction("mark-paid");
    try {
      const results = await Promise.allSettled(
        selectedUnpaidInvoices.map((invoice) =>
          markInvoiceAsPaid(invoice.id, { paymentMethod: "cash" })
        )
      );

      const successCount = results.filter((result) => result.status === "fulfilled" && result.value).length;
      const failedCount = results.length - successCount;

      await loadData({ background: true });
      setSelectedInvoiceIds([]);

      if (successCount > 0) {
        toast.success(`${successCount} factura(s) marcada(s) como pagada(s)`);
      }
      if (failedCount > 0) {
        toast.error(`${failedCount} factura(s) no se pudieron marcar como pagadas`);
      }
    } catch (error) {
      console.error("Failed to mark invoices as paid in bulk:", error);
      toast.error("Error al marcar facturas como pagadas");
    } finally {
      setBulkAction(null);
    }
  }, [selectedUnpaidInvoices, bulkAction]);

  const handleBulkDeleteInvoices = useCallback(async () => {
    if (selectedUnpaidInvoices.length === 0 || bulkAction) {
      return;
    }

    const confirmed = window.confirm(
      `Eliminar ${selectedUnpaidInvoices.length} factura(s) seleccionada(s)? Esta acción no se puede deshacer.`
    );
    if (!confirmed) {
      return;
    }

    setBulkAction("delete");
    try {
      const results = await Promise.allSettled(
        selectedUnpaidInvoices.map((invoice) => deleteInvoice(invoice.id))
      );

      const successCount = results.filter((result) => result.status === "fulfilled" && result.value === true).length;
      const failedCount = results.length - successCount;

      await loadData({ background: true });
      setSelectedInvoiceIds([]);

      if (successCount > 0) {
        toast.success(`${successCount} factura(s) eliminada(s)`);
      }
      if (failedCount > 0) {
        toast.error(`${failedCount} factura(s) no se pudieron eliminar`);
      }
    } catch (error) {
      console.error("Failed to delete invoices in bulk:", error);
      toast.error("Error al eliminar facturas");
    } finally {
      setBulkAction(null);
    }
  }, [selectedUnpaidInvoices, bulkAction]);

  // Available months from invoices
  const availableInvoiceMonths = useMemo(() => {
    const months = [...new Set(invoices.map((i) => i.month))].sort().reverse();
    return months;
  }, [invoices]);

  const currentMonth = getCurrentMonth();
  const hasCurrentMonthInvoices = useMemo(
    () => invoices.some((invoice) => invoice.month === currentMonth),
    [invoices, currentMonth]
  );

  const acceptedStudentsWithoutCurrentMonthRecords = useMemo(() => {
    const students = new Map<string, string>();

    for (const enrollment of acceptedEnrollments) {
      if (!enrollment.studentId) continue;
      students.set(enrollment.studentId, enrollment.studentName);
    }

    const hasInvoice = new Set(
      invoices
        .filter((invoice) => invoice.month === currentMonth)
        .map((invoice) => invoice.studentId)
    );

    const hasPayment = new Set(
      payments
        .filter((payment) => payment.month === currentMonth)
        .map((payment) => payment.studentId)
    );

    return Array.from(students.entries())
      .filter(([studentId]) => !hasInvoice.has(studentId) && !hasPayment.has(studentId))
      .map(([studentId, studentName]) => ({ studentId, studentName }));
  }, [acceptedEnrollments, invoices, payments, currentMonth]);

  const preferredPaymentByStudent = useMemo(() => {
    const result: Record<string, { method?: "Efectivo" | "Transferencia bancaria"; payerName?: string; accountNumber?: string }> = {};

    for (const payment of payments) {
      if (!payment.studentId || result[payment.studentId]) continue;
      const normalizedMethod = (payment.method || "").toLowerCase();
      const method = normalizedMethod.includes("transfer")
        ? "Transferencia bancaria"
        : "Efectivo";

      result[payment.studentId] = {
        method,
        payerName: payment.payerName || undefined,
        accountNumber: payment.accountNumber || undefined,
      };
    }

    return result;
  }, [payments]);

  const pendingPaymentsCount = useMemo(
    () => payments.filter((payment) => payment.status === "pending" || payment.status === "overdue").length,
    [payments]
  );
  const paidPaymentsCount = useMemo(
    () => payments.filter((payment) => payment.status === "paid").length,
    [payments]
  );
  const collectedAmount = useMemo(
    () => payments.filter((payment) => payment.status === "paid").reduce((sum, payment) => sum + payment.amount, 0),
    [payments]
  );

  if (initialLoading) {
    return (
      <PageContainer title="Pagos" description="Control de cobros claro y accionable">
        <div className="flex items-center justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer title="Pagos" description="Control de cobros claro y accionable">
      <div className="mb-4 grid gap-2 sm:grid-cols-3">
        <div className="rounded-md border border-border bg-card px-3 py-2">
          <p className="text-[11px] text-muted-foreground">Pagos pendientes</p>
          <p className="text-lg font-semibold text-foreground">{pendingPaymentsCount}</p>
        </div>
        <div className="rounded-md border border-border bg-card px-3 py-2">
          <p className="text-[11px] text-muted-foreground">Pagos confirmados</p>
          <p className="text-lg font-semibold text-foreground">{paidPaymentsCount}</p>
        </div>
        <div className="rounded-md border border-border bg-card px-3 py-2">
          <p className="text-[11px] text-muted-foreground">Cobrado</p>
          <p className="text-lg font-semibold text-foreground">€{collectedAmount.toFixed(2)}</p>
        </div>
      </div>

      <Tabs defaultValue="payments" className="w-full">
        <div className="space-y-3 mb-4">
          {!hasCurrentMonthInvoices && (
            <Alert>
              <AlertTriangle className="h-4 w-4" />
              <AlertTitle>No se han generado recibos del mes actual</AlertTitle>
              <AlertDescription>
                Aún no hay facturas/recibos para {currentMonth}. Genera las facturas del mes para mantener el control de cobros al día.
              </AlertDescription>
            </Alert>
          )}

          {acceptedStudentsWithoutCurrentMonthRecords.length > 0 && (
            <Alert>
              <AlertTriangle className="h-4 w-4" />
              <AlertTitle>
                {acceptedStudentsWithoutCurrentMonthRecords.length} alumno(s) aceptado(s) sin registro del mes
              </AlertTitle>
              <AlertDescription>
                {acceptedStudentsWithoutCurrentMonthRecords
                  .slice(0, 5)
                  .map((student) => student.studentName)
                  .join(", ")}
                {acceptedStudentsWithoutCurrentMonthRecords.length > 5 ? "..." : ""}. Revisa si se matricularon durante el mes y genera sus recibos.
              </AlertDescription>
            </Alert>
          )}
        </div>

        <TabsList>
          <TabsTrigger value="payments" className="flex items-center gap-2">
            <DollarSign className="h-4 w-4" />
            Pagos
          </TabsTrigger>
          <TabsTrigger value="invoices" className="flex items-center gap-2">
            <FileText className="h-4 w-4" />
            Facturas
          </TabsTrigger>
        </TabsList>

        <TabsContent value="payments" className="space-y-4">
          <Alert className="border-primary/25 bg-primary/5">
            <AlertTriangle className="h-4 w-4" />
            <AlertTitle>Flujo recomendado</AlertTitle>
            <AlertDescription>
              1) Genera facturas del mes. 2) Registra o confirma pagos. 3) Al marcar factura pagada se vincula con pagos existentes del mismo período para evitar duplicados.
            </AlertDescription>
          </Alert>

          <PaymentsTable
            payments={payments}
            isLoading={refreshing}
            onViewDetail={handleViewDetail}
            onAddPayment={() => setPaymentModalOpen(true)}
            onGenerateReceipt={handleGenerateReceipt}
            generatingReceiptPaymentId={generatingReceiptPaymentId}
          />

          <div className="flex justify-end">
            <Button onClick={() => setGenerateDialogOpen(true)}>
              Generar facturas del mes
            </Button>
          </div>

          <div className="flex flex-col gap-3 rounded-lg border p-4 sm:flex-row sm:items-end sm:justify-between">
            <div className="space-y-1">
              <h3 className="text-sm font-semibold">Recibos en efectivo (PDF único)</h3>
              <p className="text-xs text-muted-foreground">
                Genera un PDF multipágina con todos los recibos de pagos en efectivo del mes.
              </p>
            </div>

            <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
              <div className="space-y-1">
                <Label htmlFor="receipt-month" className="text-xs">Mes</Label>
                <Input
                  id="receipt-month"
                  type="month"
                  value={receiptMonth}
                  onChange={(event) => setReceiptMonth(event.target.value)}
                  className="h-9 w-[170px]"
                />
              </div>
              <Button
                onClick={() => void handleGenerateCashReceiptsBatch()}
                disabled={generatingReceipts}
                className="sm:mt-5"
              >
                {generatingReceipts ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : null}
                Generar PDF de Recibos
              </Button>
            </div>
          </div>
        </TabsContent>

        <TabsContent value="invoices" className="space-y-4">
          <div>
            <h3 className="text-lg font-semibold">Facturas</h3>
            <p className="text-sm text-muted-foreground">
              Genera y gestiona facturas mensuales de tus alumnos
            </p>
          </div>

          <Alert className="border-primary/25 bg-primary/5">
            <AlertTriangle className="h-4 w-4" />
            <AlertTitle>Flujo unificado de cobro</AlertTitle>
            <AlertDescription>
              Marca y registra pagos desde la pestaña <strong>Pagos</strong>. Esta vista de facturas es informativa para evitar duplicar acciones.
            </AlertDescription>
          </Alert>

          {/* Filters */}
          {invoices.length > 0 && (
            <div className="flex flex-wrap gap-3">
              <div className="relative flex-1 min-w-[200px] max-w-sm">
                <Input
                  placeholder="Buscar por alumno o número..."
                  value={invoiceSearchFilter}
                  onChange={(e) => setInvoiceSearchFilter(e.target.value)}
                  className="h-9 text-sm"
                />
              </div>
              <Select value={invoiceMonthFilter} onValueChange={setInvoiceMonthFilter}>
                <SelectTrigger className="h-9 w-[160px] text-sm">
                  <SelectValue placeholder="Período" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos los meses</SelectItem>
                  {availableInvoiceMonths.map((m) => (
                    <SelectItem key={m} value={m}>{m}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Select value={invoiceStatusFilter} onValueChange={setInvoiceStatusFilter}>
                <SelectTrigger className="h-9 w-[140px] text-sm">
                  <SelectValue placeholder="Estado" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos los estados</SelectItem>
                  <SelectItem value="pending">Pendiente</SelectItem>
                  <SelectItem value="paid">Pagada</SelectItem>
                  <SelectItem value="overdue">Vencida</SelectItem>
                </SelectContent>
              </Select>
            </div>
          )}

          {selectedInvoiceIds.length > 0 && (
            <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border bg-muted/30 p-3">
              <p className="text-sm text-muted-foreground">
                {selectedInvoiceIds.length} factura(s) seleccionada(s)
              </p>
              <div className="flex items-center gap-2">
                <Button
                  size="sm"
                  onClick={() => void handleBulkMarkInvoicesAsPaid()}
                  disabled={selectedUnpaidInvoices.length === 0 || bulkAction !== null}
                >
                  {bulkAction === "mark-paid" ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : null}
                  Marcar pagadas
                </Button>
                <Button
                  size="sm"
                  variant="destructive"
                  onClick={() => void handleBulkDeleteInvoices()}
                  disabled={selectedUnpaidInvoices.length === 0 || bulkAction !== null}
                >
                  {bulkAction === "delete" ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Trash2 className="h-4 w-4 mr-2" />}
                  Eliminar seleccionadas
                </Button>
              </div>
            </div>
          )}

          {filteredInvoices.length === 0 ? (
            <div className="rounded-lg border border-dashed p-8 text-center">
              <FileText className="h-8 w-8 mx-auto text-muted-foreground mb-2" />
              <p className="text-muted-foreground">
                {invoices.length === 0
                  ? "No hay facturas. Genera facturas para un mes específico para empezar."
                  : "No se encontraron facturas con los filtros aplicados."}
              </p>
            </div>
          ) : (
            <div className="border rounded-lg overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-[42px]">
                      <Checkbox
                        checked={allSelectableChecked || (someSelectableChecked ? "indeterminate" : false)}
                        onCheckedChange={(checked) => toggleAllSelectableInvoices(checked === true)}
                        aria-label="Seleccionar facturas"
                      />
                    </TableHead>
                    <TableHead>Número</TableHead>
                    <TableHead>Alumno</TableHead>
                    <TableHead>Mes</TableHead>
                    <TableHead>Cantidad</TableHead>
                    <TableHead>Método</TableHead>
                    <TableHead>Estado</TableHead>
                    <TableHead>Acciones</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredInvoices.map((invoice) => (
                    <TableRow key={invoice.id}>
                      <TableCell>
                        <Checkbox
                          checked={selectedInvoiceIds.includes(invoice.id)}
                          onCheckedChange={(checked) => toggleInvoiceSelection(invoice.id, checked === true)}
                          aria-label={`Seleccionar factura ${invoice.invoiceNumber}`}
                          disabled={invoice.status === "paid"}
                        />
                      </TableCell>
                      <TableCell className="font-mono text-sm">{invoice.invoiceNumber}</TableCell>
                      <TableCell>
                        <div>
                          <p className="font-medium">{invoice.studentName}</p>
                          <p className="text-sm text-muted-foreground">{invoice.studentEmail}</p>
                        </div>
                      </TableCell>
                      <TableCell>{invoice.month}</TableCell>
                      <TableCell className="font-semibold">€{invoice.totalAmount.toFixed(2)}</TableCell>
                      <TableCell className="text-sm text-muted-foreground">
                        {formatPaymentMethodLabel(invoice.paymentMethod)}
                      </TableCell>
                      <TableCell>
                        <Badge
                          variant={
                            invoice.status === "paid"
                              ? "default"
                              : invoice.status === "overdue"
                                ? "destructive"
                                : "outline"
                          }
                        >
                          {invoice.status === "paid"
                            ? "Pagada"
                            : invoice.status === "overdue"
                              ? "Vencida"
                              : "Pendiente"}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-1">
                        {invoice.status !== "paid" && (
                          <Button
                            variant="outline"
                            size="sm"
                            className="h-8"
                            onClick={() => void handleMarkInvoiceAsPaid(invoice)}
                            disabled={markingInvoiceId === invoice.id}
                            title="Marcar como pagada"
                          >
                            {markingInvoiceId === invoice.id ? <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" /> : null}
                            Marcar pagada
                          </Button>
                        )}
                        {invoice.status !== "paid" && (
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-destructive"
                            onClick={() => void handleDeleteInvoice(invoice)}
                            title="Eliminar factura"
                            disabled={bulkAction !== null}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        )}
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8"
                          onClick={() => handleViewInvoiceDetail(invoice)}
                          title="Ver detalle"
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Dialogs */}
      <PaymentDetailDrawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        payment={selectedPayment}
        onMarkPaid={handleMarkPaid}
        onMarkRefunded={handleMarkRefunded}
        onGenerateReceipt={handleGenerateReceipt}
      />

      <RecordPaymentModal
        open={paymentModalOpen}
        onOpenChange={setPaymentModalOpen}
        onSave={handleRecordPayment}
        onStartStripeCheckout={handleStripeCheckout}
        preferredByStudent={preferredPaymentByStudent}
      />

      {/* Generate Invoices Dialog */}
      <Dialog open={generateDialogOpen} onOpenChange={setGenerateDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Generar Facturas Mensuales</DialogTitle>
            <DialogDescription>
              Genera automáticamente facturas para todos los alumnos activos de un mes específico.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="month">Mes</Label>
              <Input
                id="month"
                type="month"
                value={selectedMonth}
                onChange={(e) => setSelectedMonth(e.target.value)}
              />
              <p className="text-sm text-muted-foreground">
                Las facturas se generarán para alumnos activos con matrícula confirmada.
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setGenerateDialogOpen(false)}>
              Cancelar
            </Button>
            <Button
              onClick={handleGenerateMonthlyInvoices}
              disabled={generatingInvoices}
            >
              {generatingInvoices && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Generar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Invoice Detail Dialog */}
      <Dialog open={invoiceDetailOpen} onOpenChange={setInvoiceDetailOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Detalles de Factura</DialogTitle>
          </DialogHeader>

          {selectedInvoice && (
            <div className="space-y-6 py-4">
              {/* Header */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-muted-foreground">Número de Factura</p>
                  <p className="font-mono font-semibold">{selectedInvoice.invoiceNumber}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Estado</p>
                  <Badge
                    variant={
                      selectedInvoice.status === "paid"
                        ? "default"
                        : selectedInvoice.status === "overdue"
                          ? "destructive"
                          : "outline"
                    }
                  >
                    {selectedInvoice.status === "paid"
                      ? "Pagada"
                      : selectedInvoice.status === "overdue"
                        ? "Vencida"
                        : "Pendiente"}
                  </Badge>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Alumno</p>
                  <p className="font-medium">{selectedInvoice.studentName}</p>
                  <p className="text-sm text-muted-foreground">{selectedInvoice.studentEmail}</p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground">Mes</p>
                  <p className="font-medium">{selectedInvoice.month}</p>
                </div>
              </div>

              {/* Line Items */}
              <div>
                <h4 className="font-semibold mb-3">Clases</h4>
                <div className="border rounded-lg overflow-hidden">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Clase</TableHead>
                        <TableHead className="text-right">Cantidad</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {selectedInvoice.items.map((item) => (
                        <TableRow key={item.id}>
                          <TableCell>{item.className}</TableCell>
                          <TableCell className="text-right font-medium">
                            €{item.amount.toFixed(2)}
                          </TableCell>
                        </TableRow>
                      ))}
                      <TableRow className="bg-muted font-semibold">
                        <TableCell>Total</TableCell>
                        <TableCell className="text-right">
                          €{selectedInvoice.totalAmount.toFixed(2)}
                        </TableCell>
                      </TableRow>
                    </TableBody>
                  </Table>
                </div>
              </div>

              {/* Footer */}
              <div className="pt-4 border-t">
                <p className="text-xs text-muted-foreground">
                  Creada el {formatDate(selectedInvoice.createdAt)}
                </p>
              </div>
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setInvoiceDetailOpen(false)}>
              Cerrar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </PageContainer>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { PageContainer } from "@/components/layout/PageContainer";
import { ModuleHelpShortcut } from "@/components/layout/ModuleHelpShortcut";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import {
  approveTeacherPortalPost,
  createPortalMediaFromUrl,
  createSchoolPortalPost,
  deleteSchoolPortalPost,
  listSchoolPortalPosts,
  rejectTeacherPortalPost,
  type PortalFeedPost,
  type PortalFeedType,
  uploadPortalMediaFile,
  updateSchoolPortalPost,
} from "@/lib/api/portalFoundation";
import { getSchoolSettings } from "@/lib/api/settings";
import { toast } from "sonner";
import { runWithSaveFeedback } from "@/lib/saveFeedback";
import { toastErrorOnce } from "@/lib/toastPremium";
import { useUnsavedChangesGuard } from "@/hooks/useUnsavedChangesGuard";
import { Loader2, RefreshCw } from "lucide-react";

interface FormState {
  authorName: string;
  type: PortalFeedType;
  content: string;
  mediaUrl: string;
  mediaKind: "image" | "video";
  existingMediaIds: string[];
}

const initialForm: FormState = {
  authorName: "",
  type: "announcement",
  content: "",
  mediaUrl: "",
  mediaKind: "image",
  existingMediaIds: [],
};

const statusColor: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  published: "default",
  pending_approval: "secondary",
  rejected: "destructive",
  draft: "outline",
};

const POST_DELETE_UNDO_MS = 5000;

export default function PostsManagementScreen() {
  const [posts, setPosts] = useState<PortalFeedPost[]>([]);
  const [form, setForm] = useState<FormState>(initialForm);
  const [mediaFile, setMediaFile] = useState<File | null>(null);
  const [mediaPreviewUrl, setMediaPreviewUrl] = useState<string>("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [editingPostId, setEditingPostId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const pendingDeleteMapRef = useRef<Map<string, { post: PortalFeedPost; index: number }>>(new Map());
  const pendingDeleteTimersRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    return () => {
      if (mediaPreviewUrl.startsWith("blob:")) {
        URL.revokeObjectURL(mediaPreviewUrl);
      }

      pendingDeleteTimersRef.current.forEach((timerId) => window.clearTimeout(timerId));
      pendingDeleteTimersRef.current.clear();
      pendingDeleteMapRef.current.clear();
    };
  }, [mediaPreviewUrl]);

  const editingPost = useMemo(
    () => (editingPostId ? posts.find((item) => item.id === editingPostId) ?? null : null),
    [editingPostId, posts]
  );

  const formHasUnsavedChanges = useMemo(() => {
    if (saving) {
      return false;
    }

    if (editingPost) {
      const originalMediaUrl = editingPost.mediaItems[0]?.url ?? editingPost.imageUrls[0] ?? editingPost.videoUrl ?? "";
      const originalMediaKind: "image" | "video" = editingPost.videoUrl ? "video" : "image";

      return Boolean(
        mediaFile
        || form.authorName.trim() !== editingPost.authorName.trim()
        || form.type !== editingPost.type
        || form.content.trim() !== editingPost.content.trim()
        || form.mediaUrl.trim() !== originalMediaUrl.trim()
        || form.mediaKind !== originalMediaKind
      );
    }

    return Boolean(
      form.content.trim()
      || form.mediaUrl.trim()
      || mediaFile
      || form.type !== "announcement"
    );
  }, [editingPost, form.authorName, form.content, form.mediaKind, form.mediaUrl, form.type, mediaFile, saving]);

  useUnsavedChangesGuard({
    enabled: formHasUnsavedChanges,
    message: "Tienes cambios sin guardar en Publicaciones. Si sales ahora, se perderán. ¿Quieres continuar?",
  });

  const filteredPosts = useMemo(
    () => posts.filter((item) => statusFilter === "all" || item.approvalStatus === statusFilter),
    [posts, statusFilter]
  );

  const loadPosts = async () => {
    setLoading(true);
    setLoadError(null);
    try {
      const data = await listSchoolPortalPosts({ limit: 100 });
      setPosts(data.items);
    } catch (error) {
      console.error(error);
      const message = "No se pudieron cargar las publicaciones";
      setLoadError(message);
      toastErrorOnce("posts-load", message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadPosts();

    const loadDefaults = async () => {
      const settings = await getSchoolSettings();
      if (settings?.school?.name) {
        setForm((prev) => ({ ...prev, authorName: settings.school.name }));
      }
    };

    void loadDefaults();
  }, []);

  const resetForm = () => {
    setEditingPostId(null);
    setForm((prev) => ({ ...initialForm, authorName: prev.authorName }));
    setMediaFile(null);
    if (mediaPreviewUrl.startsWith("blob:")) {
      URL.revokeObjectURL(mediaPreviewUrl);
    }
    setMediaPreviewUrl("");
  };

  const handleMediaFileChange = (file: File | null) => {
    if (mediaPreviewUrl.startsWith("blob:")) {
      URL.revokeObjectURL(mediaPreviewUrl);
    }

    setMediaFile(file);

    if (!file) {
      setMediaPreviewUrl("");
      return;
    }

    setMediaPreviewUrl(URL.createObjectURL(file));
    setForm((prev) => ({
      ...prev,
      mediaKind: file.type.startsWith("video/") ? "video" : "image",
    }));
  };

  const handleCreateOrUpdate = async () => {
    if (!form.authorName.trim() || !form.content.trim()) {
      toast.error("Autor y contenido son obligatorios");
      return;
    }

    setSaving(true);
    try {
      await runWithSaveFeedback(
        {
          loading: editingPostId ? "Guardando publicación..." : "Publicando contenido...",
          success: editingPostId ? "Publicación guardada" : "Publicación creada",
          error: "No se pudo guardar la publicación",
          successDescription: editingPostId
            ? "Se actualizó en el historial de publicaciones."
            : "Ya puedes verla y moderarla desde el historial.",
          errorHint: "Revisa autor, contenido y multimedia antes de reintentar.",
        },
        async () => {
          let mediaIds = form.existingMediaIds;
          if (mediaFile) {
            const uploaded = await uploadPortalMediaFile({
              file: mediaFile,
              kind: form.mediaKind,
              isPublic: true,
            });
            mediaIds = [uploaded.id];
          } else if (form.mediaUrl.trim()) {
            const uploaded = await createPortalMediaFromUrl({
              url: form.mediaUrl.trim(),
              kind: form.mediaKind,
              isPublic: true,
            });
            mediaIds = [uploaded.id];
          }

          if (editingPostId) {
            await updateSchoolPortalPost(editingPostId, {
              authorName: form.authorName.trim(),
              type: form.type,
              content: form.content.trim(),
              mediaIds,
            });
            return;
          }

          await createSchoolPortalPost({
            authorType: "school",
            authorName: form.authorName.trim(),
            type: form.type,
            content: form.content.trim(),
            mediaIds,
            isPublic: true,
          });
        }
      );

      resetForm();
      await loadPosts();
    } catch (error) {
      console.error(error);
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteWithUndo = (post: PortalFeedPost) => {
    if (pendingDeleteTimersRef.current.has(post.id)) {
      return;
    }

    const index = filteredPosts.findIndex((item) => item.id === post.id);
    pendingDeleteMapRef.current.set(post.id, { post, index: index >= 0 ? index : 0 });
    setPosts((prev) => prev.filter((item) => item.id !== post.id));

    toast.warning("Publicación preparada para eliminar", {
      description: "Puedes deshacer durante unos segundos.",
      action: {
        label: "Deshacer",
        onClick: () => {
          const pending = pendingDeleteMapRef.current.get(post.id);
          const timerId = pendingDeleteTimersRef.current.get(post.id);
          if (!pending) {
            return;
          }

          if (timerId) {
            window.clearTimeout(timerId);
          }

          pendingDeleteMapRef.current.delete(post.id);
          pendingDeleteTimersRef.current.delete(post.id);
          setPosts((prev) => {
            const next = [...prev];
            next.splice(Math.min(pending.index, next.length), 0, pending.post);
            return next;
          });
          toast.success("Eliminación cancelada");
        },
      },
    });

    const timerId = window.setTimeout(() => {
      pendingDeleteTimersRef.current.delete(post.id);
      const pending = pendingDeleteMapRef.current.get(post.id);
      pendingDeleteMapRef.current.delete(post.id);

      if (!pending) {
        return;
      }

      void runWithSaveFeedback(
        {
          loading: "Eliminando publicación...",
          success: "Publicación eliminada",
          error: "No se pudo eliminar la publicación",
          successDescription: "El contenido dejó de mostrarse en el listado.",
          errorHint: "Inténtalo de nuevo en unos segundos.",
        },
        async () => {
          await deleteSchoolPortalPost(post.id);
        }
      ).catch((error) => {
        console.error(error);
        setPosts((prev) => {
          const next = [...prev];
          next.splice(Math.min(pending.index, next.length), 0, pending.post);
          return next;
        });
      });
    }, POST_DELETE_UNDO_MS);

    pendingDeleteTimersRef.current.set(post.id, timerId);
  };

  const handleApprovePost = async (postId: string) => {
    try {
      await runWithSaveFeedback(
        {
          loading: "Aprobando publicación...",
          success: "Publicación aprobada",
          error: "No se pudo aprobar la publicación",
          successDescription: "El contenido ya puede mostrarse a los alumnos.",
          errorHint: "Inténtalo de nuevo en unos segundos.",
        },
        async () => {
          await approveTeacherPortalPost(postId);
        }
      );
      await loadPosts();
    } catch (error) {
      console.error(error);
    }
  };

  const handleRejectPost = async (postId: string) => {
    try {
      await runWithSaveFeedback(
        {
          loading: "Rechazando publicación...",
          success: "Publicación rechazada",
          error: "No se pudo rechazar la publicación",
          successDescription: "La publicación quedó marcada para revisión del autor.",
          errorHint: "Comprueba la conexión e inténtalo nuevamente.",
        },
        async () => {
          await rejectTeacherPortalPost(postId, "Revisar formato");
        }
      );
      await loadPosts();
    } catch (error) {
      console.error(error);
    }
  };

  const startEdit = (post: PortalFeedPost) => {
    setEditingPostId(post.id);
    setForm({
      authorName: post.authorName,
      type: post.type,
      content: post.content,
      mediaUrl: post.mediaItems[0]?.url ?? post.imageUrls[0] ?? post.videoUrl ?? "",
      mediaKind: post.videoUrl ? "video" : "image",
      existingMediaIds: post.mediaIds,
    });
    setMediaFile(null);
    if (mediaPreviewUrl.startsWith("blob:")) {
      URL.revokeObjectURL(mediaPreviewUrl);
    }
    setMediaPreviewUrl("");
  };

  return (
    <PageContainer
      title="Gestión de Publicaciones"
      description="Crea, edita y modera publicaciones de escuela y profesores"
      actions={
        <>
          <ModuleHelpShortcut module="school-posts" />
          <Button variant="outline" onClick={() => void loadPosts()} disabled={loading || saving}>
            {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
            <span className="ml-2">Recargar</span>
          </Button>
          {editingPostId ? (
            <Button variant="outline" onClick={resetForm}>Cancelar edición</Button>
          ) : null}
        </>
      }
    >
      <Card>
        <CardHeader>
          <CardTitle>{editingPostId ? "Editar publicación" : "Nueva publicación"}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="author-name">Autor</Label>
              <Input
                id="author-name"
                value={form.authorName}
                onChange={(event) => setForm((prev) => ({ ...prev, authorName: event.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="post-type">Tipo</Label>
              <Select value={form.type} onValueChange={(value) => setForm((prev) => ({ ...prev, type: value as PortalFeedType }))}>
                <SelectTrigger id="post-type">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="announcement">Anuncio</SelectItem>
                  <SelectItem value="class">Clase</SelectItem>
                  <SelectItem value="event">Evento</SelectItem>
                  <SelectItem value="achievement">Logro</SelectItem>
                  <SelectItem value="choreography">Coreografía</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="space-y-2">
            <Label htmlFor="post-content">Contenido</Label>
            <Textarea
              id="post-content"
              rows={5}
              value={form.content}
              onChange={(event) => setForm((prev) => ({ ...prev, content: event.target.value }))}
            />
          </div>
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="media-url">URL multimedia (opcional)</Label>
              <Input
                id="media-url"
                placeholder="https://..."
                value={form.mediaUrl}
                onChange={(event) => setForm((prev) => ({ ...prev, mediaUrl: event.target.value }))}
              />
              <p className="text-xs text-muted-foreground">
                Si adjuntas archivo, tiene prioridad sobre esta URL.
              </p>
            </div>
            <div className="space-y-2">
              <Label htmlFor="media-file">Archivo multimedia (opcional)</Label>
              <Input
                id="media-file"
                type="file"
                accept="image/*,video/*"
                onChange={(event) => handleMediaFileChange(event.target.files?.[0] ?? null)}
              />
            </div>
          </div>
          {(mediaPreviewUrl || form.mediaUrl.trim()) ? (
            <div className="space-y-2">
              <Label>Vista previa</Label>
              <div className="overflow-hidden rounded-md border">
                {form.mediaKind === "video" ? (
                  <video
                    src={mediaPreviewUrl || form.mediaUrl.trim()}
                    controls
                    className="max-h-64 w-full bg-black object-contain"
                  />
                ) : (
                  <img
                    src={mediaPreviewUrl || form.mediaUrl.trim()}
                    alt="Vista previa multimedia"
                    className="max-h-64 w-full object-contain"
                  />
                )}
              </div>
            </div>
          ) : null}
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="media-kind">Tipo multimedia</Label>
              <Select
                value={form.mediaKind}
                onValueChange={(value) => setForm((prev) => ({ ...prev, mediaKind: value as "image" | "video" }))}
              >
                <SelectTrigger id="media-kind">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="image">Imagen</SelectItem>
                  <SelectItem value="video">Video</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="sticky bottom-0 -mx-6 mt-4 flex items-center justify-between border-t bg-card/90 px-6 py-3 backdrop-blur supports-[backdrop-filter]:bg-card/75">
            <p className="text-xs text-muted-foreground">
              {formHasUnsavedChanges ? "Cambios sin guardar" : "Sin cambios pendientes"}
            </p>
            <Button disabled={saving} onClick={() => void handleCreateOrUpdate()}>
              {saving ? "Guardando..." : editingPostId ? "Actualizar" : "Publicar"}
            </Button>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
          <CardTitle>Historial</CardTitle>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-[220px]">
              <SelectValue placeholder="Filtrar por estado" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todos</SelectItem>
              <SelectItem value="published">Publicados</SelectItem>
              <SelectItem value="pending_approval">Pendientes</SelectItem>
              <SelectItem value="rejected">Rechazados</SelectItem>
              <SelectItem value="draft">Borrador</SelectItem>
            </SelectContent>
          </Select>
        </CardHeader>
        <CardContent className="space-y-3">
          {loading ? (
            <EmptyState
              title="Cargando publicaciones"
              description="Estamos preparando el historial para que puedas seguir moderando sin perder contexto."
            />
          ) : null}
          {!loading && loadError ? (
            <EmptyState
              type="error"
              title="No se pudo cargar el historial"
              description={loadError}
              actionLabel="Reintentar"
              onAction={() => void loadPosts()}
            />
          ) : null}
          {!loading && !loadError && filteredPosts.length === 0 ? (
            <EmptyState
              title={posts.length === 0 ? "Aún no hay publicaciones" : "Sin resultados para este filtro"}
              description={
                posts.length === 0
                  ? "Publica el primer contenido para activar el canal social de la escuela."
                  : "Ajusta el estado para recuperar publicaciones rápidamente."
              }
              actionLabel={posts.length === 0 ? "Crear publicación" : "Ver todas"}
              onAction={posts.length === 0 ? () => {
                setEditingPostId(null);
                window.scrollTo({ top: 0, behavior: "smooth" });
              } : () => setStatusFilter("all")}
            />
          ) : null}
          {filteredPosts.map((post) => (
            <div key={post.id} className="rounded-md border p-3 space-y-2">
              <div className="flex flex-wrap items-center gap-2">
                <p className="font-medium">{post.authorName}</p>
                <Badge variant={statusColor[post.approvalStatus || "published"] || "outline"}>
                  {post.approvalStatus || "published"}
                </Badge>
                <Badge variant="outline">{post.type}</Badge>
              </div>
              <p className="text-sm text-muted-foreground">{post.content}</p>
              {(post.mediaItems[0]?.url || post.videoUrl || post.imageUrls[0]) ? (
                <div className="overflow-hidden rounded-md border">
                  {(post.mediaItems[0]?.kind === "video" || (!post.mediaItems[0] && post.videoUrl)) ? (
                    <video
                      src={post.mediaItems[0]?.url ?? post.videoUrl ?? ""}
                      controls
                      className="max-h-64 w-full bg-black object-contain"
                    />
                  ) : (
                    <img
                      src={post.mediaItems[0]?.url ?? post.imageUrls[0] ?? ""}
                      alt="Media de la publicación"
                      className="max-h-64 w-full object-contain"
                      loading="lazy"
                    />
                  )}
                </div>
              ) : null}
              <div className="flex flex-wrap gap-2">
                <Button size="sm" variant="outline" onClick={() => startEdit(post)}>Editar</Button>
                <Button size="sm" variant="destructive" onClick={() => handleDeleteWithUndo(post)}>
                  Eliminar
                </Button>
                {post.approvalStatus === "pending_approval" ? (
                  <>
                    <Button size="sm" onClick={() => void handleApprovePost(post.id)}>
                      Aprobar
                    </Button>
                    <Button size="sm" variant="secondary" onClick={() => void handleRejectPost(post.id)}>
                      Rechazar
                    </Button>
                  </>
                ) : null}
              </div>
            </div>
          ))}
        </CardContent>
      </Card>
    </PageContainer>
  );
}

import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { Loader2, RefreshCw } from "lucide-react";
import { PageContainer } from "@/components/layout/PageContainer";
import { ModuleHelpShortcut } from "@/components/layout/ModuleHelpShortcut";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { EmptyState } from "@/components/ui/empty-state";
import {
  createRenewalCampaign,
  getRenewalCampaigns,
  getRenewalOffers,
  updateRenewalOffer,
  type RenewalCampaign,
  type RenewalOffer,
  type RenewalOfferStatus,
} from "@/lib/api/renewals";
import { runWithRetry } from "@/lib/reliability";
import { useBillingEntitlements } from "@/hooks/useBillingEntitlements";
import { UpgradeFeatureAlert } from "@/components/billing/UpgradeFeatureAlert";
import { FeatureLockDialog } from "@/components/billing/FeatureLockDialog";

const OFFER_STATUS_FILTERS: Array<{ value: "all" | RenewalOfferStatus; label: string }> = [
  { value: "all", label: "Todas" },
  { value: "pending", label: "Pendientes" },
  { value: "confirmed", label: "Confirmadas" },
  { value: "changed", label: "Con cambios" },
  { value: "released", label: "Liberadas" },
];

const OFFER_STATUS_LABELS: Record<RenewalOfferStatus, string> = {
  pending: "Pendiente",
  confirmed: "Confirmada",
  changed: "Con cambios",
  released: "Plaza liberada",
};

const RENEWALS_SELECTED_CAMPAIGN_KEY = "nexa:renewals:selected-campaign";
const RENEWALS_STATUS_FILTER_KEY = "nexa:renewals:status-filter";
const RENEWALS_CAMPAIGNS_CACHE_KEY = "nexa:renewals:campaigns-cache";

function readStoredString(key: string): string {
  if (typeof window === "undefined") return "";
  return window.localStorage.getItem(key) || "";
}

function readStoredStatusFilter(): "all" | RenewalOfferStatus {
  const stored = readStoredString(RENEWALS_STATUS_FILTER_KEY);
  return stored === "pending" || stored === "confirmed" || stored === "changed" || stored === "released" ? stored : "all";
}

function readStoredCampaignsCache(): RenewalCampaign[] {
  if (typeof window === "undefined") return [];

  try {
    const raw = window.localStorage.getItem(RENEWALS_CAMPAIGNS_CACHE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as RenewalCampaign[]) : [];
  } catch {
    return [];
  }
}

function persistString(key: string, value: string): void {
  if (typeof window === "undefined") return;

  if (!value) {
    window.localStorage.removeItem(key);
    return;
  }

  window.localStorage.setItem(key, value);
}

function persistCampaignsCache(campaigns: RenewalCampaign[]): void {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(RENEWALS_CAMPAIGNS_CACHE_KEY, JSON.stringify(campaigns));
}

function isValidPeriodCode(value: string): boolean {
  return /^\d{4}-(0[1-9]|1[0-2])$/.test(value);
}

export default function RenewalsPage() {
  const { billing, planLabel, startUpgrade, loading: billingLoading } = useBillingEntitlements();
  const [loadingCampaigns, setLoadingCampaigns] = useState(true);
  const [loadingOffers, setLoadingOffers] = useState(false);
  const [mutating, setMutating] = useState(false);
  const [lockOpen, setLockOpen] = useState(false);
  const [campaignsError, setCampaignsError] = useState<string | null>(null);
  const [offersError, setOffersError] = useState<string | null>(null);
  const [campaigns, setCampaigns] = useState<RenewalCampaign[]>(() => readStoredCampaignsCache());
  const [offers, setOffers] = useState<RenewalOffer[]>([]);
  const [selectedCampaignId, setSelectedCampaignId] = useState(() => readStoredString(RENEWALS_SELECTED_CAMPAIGN_KEY));
  const [statusFilter, setStatusFilter] = useState<"all" | RenewalOfferStatus>(() => readStoredStatusFilter());

  const [campaignName, setCampaignName] = useState("");
  const [fromPeriod, setFromPeriod] = useState("");
  const [toPeriod, setToPeriod] = useState("");
  const [expiresAt, setExpiresAt] = useState("");
  const [createError, setCreateError] = useState<string | null>(null);
  const renewalsLocked = !billingLoading && !billing.features.renewalAutomation;

  const campaignNameTrimmed = campaignName.trim();
  const fromPeriodTrimmed = fromPeriod.trim();
  const toPeriodTrimmed = toPeriod.trim();

  const createValidationError = useMemo(() => {
    if (!campaignNameTrimmed) {
      return "El nombre de la campaña es obligatorio.";
    }

    if (!fromPeriodTrimmed || !toPeriodTrimmed) {
      return "Periodo origen y periodo destino son obligatorios.";
    }

    if (!isValidPeriodCode(fromPeriodTrimmed) || !isValidPeriodCode(toPeriodTrimmed)) {
      return "Usa formato AAAA-MM en ambos periodos.";
    }

    if (fromPeriodTrimmed === toPeriodTrimmed) {
      return "El periodo destino debe ser distinto del periodo origen.";
    }

    if (fromPeriodTrimmed > toPeriodTrimmed) {
      return "El periodo destino debe ser posterior al periodo origen.";
    }

    return null;
  }, [campaignNameTrimmed, fromPeriodTrimmed, toPeriodTrimmed]);

  const canCreateCampaign = !mutating && !loadingCampaigns && !renewalsLocked && !createValidationError;

  const setCampaignsPersisted = (nextCampaigns: RenewalCampaign[]) => {
    setCampaigns(nextCampaigns);
    persistCampaignsCache(nextCampaigns);
  };

  const setSelectedCampaignIdPersisted = (campaignId: string) => {
    setSelectedCampaignId(campaignId);
    persistString(RENEWALS_SELECTED_CAMPAIGN_KEY, campaignId);
  };

  const selectedCampaign = useMemo(
    () => campaigns.find((campaign) => campaign.id === selectedCampaignId) || null,
    [campaigns, selectedCampaignId]
  );

  const loadCampaigns = async () => {
    setLoadingCampaigns(true);
    setCampaignsError(null);
    try {
      const data = await getRenewalCampaigns();
      setCampaignsPersisted(data);

      setSelectedCampaignId((previous) => {
        if (previous && data.some((campaign) => campaign.id === previous)) {
          return previous;
        }

        const storedCampaignId = readStoredString(RENEWALS_SELECTED_CAMPAIGN_KEY);
        if (storedCampaignId && data.some((campaign) => campaign.id === storedCampaignId)) {
          return storedCampaignId;
        }

        return data[0]?.id || "";
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : "No se pudieron cargar las campañas";
      setCampaignsError(message);
      toast.error(message);

      const cached = readStoredCampaignsCache();
      if (cached.length > 0) {
        setCampaigns((previous) => previous.length > 0 ? previous : cached);
        setSelectedCampaignId((previous) => {
          if (previous && cached.some((campaign) => campaign.id === previous)) {
            return previous;
          }

          const storedCampaignId = readStoredString(RENEWALS_SELECTED_CAMPAIGN_KEY);
          if (storedCampaignId && cached.some((campaign) => campaign.id === storedCampaignId)) {
            return storedCampaignId;
          }

          return cached[0]?.id || previous;
        });
      }
    } finally {
      setLoadingCampaigns(false);
    }
  };

  const loadOffers = async (campaignId: string, filter: "all" | RenewalOfferStatus) => {
    if (!campaignId) {
      setOffers([]);
      return;
    }

    setLoadingOffers(true);
    setOffersError(null);
    try {
      const data = await getRenewalOffers(campaignId, filter === "all" ? undefined : filter);
      setOffers(data);
    } catch (error) {
      const message = error instanceof Error ? error.message : "No se pudieron cargar las ofertas";
      setOffersError(message);
      toast.error(message);
    } finally {
      setLoadingOffers(false);
    }
  };

  useEffect(() => {
    if (typeof window === "undefined") return;
    if (!selectedCampaignId) {
      window.localStorage.removeItem(RENEWALS_SELECTED_CAMPAIGN_KEY);
      return;
    }
    window.localStorage.setItem(RENEWALS_SELECTED_CAMPAIGN_KEY, selectedCampaignId);
  }, [selectedCampaignId]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(RENEWALS_STATUS_FILTER_KEY, statusFilter);
  }, [statusFilter]);

  useEffect(() => {
    void loadCampaigns();
  }, []);

  useEffect(() => {
    void loadOffers(selectedCampaignId, statusFilter);
  }, [selectedCampaignId, statusFilter]);

  useEffect(() => {
    if (campaigns.length === 0) {
      if (selectedCampaignId) {
        setSelectedCampaignId("");
      }
      return;
    }

    if (selectedCampaignId && campaigns.some((campaign) => campaign.id === selectedCampaignId)) {
      return;
    }

    const storedCampaignId = readStoredString(RENEWALS_SELECTED_CAMPAIGN_KEY);
    if (storedCampaignId && campaigns.some((campaign) => campaign.id === storedCampaignId)) {
      setSelectedCampaignId(storedCampaignId);
      return;
    }

    setSelectedCampaignId(campaigns[0]?.id || "");
  }, [campaigns, selectedCampaignId]);

  const handleCreateCampaign = async () => {
    if (renewalsLocked) {
      setLockOpen(true);
      return;
    }

    if (createValidationError) {
      setCreateError(createValidationError);
      toast.error(createValidationError);
      return;
    }

    setMutating(true);
    setCreateError(null);
    try {
      const result = await createRenewalCampaign({
        name: campaignNameTrimmed,
        fromPeriod: fromPeriodTrimmed,
        toPeriod: toPeriodTrimmed,
        expiresAt: expiresAt || undefined,
      });

      toast.success(`Campaña creada con ${result.offersCount} propuesta(s)`);
      setCampaignName("");
      setFromPeriod("");
      setToPeriod("");
      setExpiresAt("");

      const refreshedCampaigns = await runWithRetry(async () => {
        const data = await getRenewalCampaigns();
        if (!data.some((campaign) => campaign.id === result.campaignId)) {
          throw new Error("La campaña aún se está sincronizando");
        }
        return data;
      }, { retries: 2, delayMs: 350 });

      setCampaignsPersisted(refreshedCampaigns);
      setSelectedCampaignIdPersisted(result.campaignId);
      await loadOffers(result.campaignId, statusFilter);
    } catch (error) {
      const message = error instanceof Error ? error.message : "No se pudo crear la campaña";
      setCreateError(message);
      toast.error(message);
    } finally {
      setMutating(false);
    }
  };

  const handleOfferAction = async (offerId: string, action: "confirm" | "release") => {
    if (renewalsLocked) {
      setLockOpen(true);
      return;
    }

    if (!selectedCampaignId) {
      return;
    }

    setMutating(true);
    try {
      await updateRenewalOffer({
        campaignId: selectedCampaignId,
        offerId,
        action,
      });
      toast.success(action === "confirm" ? "Renovación confirmada" : "Plaza liberada");
      await loadOffers(selectedCampaignId, statusFilter);
      await loadCampaigns();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "No se pudo actualizar la oferta");
    } finally {
      setMutating(false);
    }
  };

  return (
    <PageContainer
      title="Renovación de alumnos"
      description="Continuidad de alumnado con flujo claro y accionable"
      actions={
        <>
          <ModuleHelpShortcut module="renewals" />
          <Button variant="outline" onClick={() => void loadCampaigns()} disabled={loadingCampaigns || loadingOffers || mutating}>
            {loadingCampaigns ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
            <span className="ml-2">Recargar</span>
          </Button>
        </>
      }
    >
      {renewalsLocked ? (
        <UpgradeFeatureAlert
          title="Renovaciones automáticas bloqueadas"
          description={`Tu plan actual (${planLabel}) no incluye campañas automáticas de renovación. Mejora a Pro para activarlas.`}
          onUpgrade={() => void startUpgrade("renewalAutomation")}
        />
      ) : null}

      <div className="grid gap-2 sm:grid-cols-3">
        <div className="rounded-md border border-border bg-card px-3 py-2">
          <p className="text-[11px] text-muted-foreground">Campañas activas</p>
          <p className="text-lg font-semibold text-foreground">{campaigns.length}</p>
        </div>
        <div className="rounded-md border border-border bg-card px-3 py-2">
          <p className="text-[11px] text-muted-foreground">Propuestas visibles</p>
          <p className="text-lg font-semibold text-foreground">{offers.length}</p>
        </div>
        <div className="rounded-md border border-border bg-card px-3 py-2">
          <p className="text-[11px] text-muted-foreground">Filtro activo</p>
          <p className="text-lg font-semibold text-foreground">{OFFER_STATUS_FILTERS.find((item) => item.value === statusFilter)?.label || "Todas"}</p>
        </div>
      </div>

      <div className={renewalsLocked ? "pointer-events-none opacity-70 blur-[1px]" : ""}>

      {campaignsError && campaigns.length === 0 ? (
        <Card>
          <CardContent>
            <EmptyState
              type="error"
              title="No se pudieron cargar campañas"
              description={campaignsError}
              actionLabel="Reintentar"
              onAction={() => void loadCampaigns()}
            />
          </CardContent>
        </Card>
      ) : null}

      <Card>
        <CardHeader>
          <CardTitle>Crear campaña</CardTitle>
          <CardDescription>Genera propuestas para los alumnos activos del periodo origen.</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-4 md:grid-cols-4">
          <div className="space-y-2 md:col-span-2">
            <Label>Nombre</Label>
            <Input
              value={campaignName}
              onChange={(event) => {
                setCampaignName(event.target.value);
                if (createError) setCreateError(null);
              }}
              placeholder="Renovación abril"
              aria-invalid={Boolean(createError || createValidationError) && !campaignNameTrimmed}
            />
          </div>
          <div className="space-y-2">
            <Label>Periodo origen</Label>
            <Input
              value={fromPeriod}
              onChange={(event) => {
                setFromPeriod(event.target.value);
                if (createError) setCreateError(null);
              }}
              placeholder="2026-03"
              aria-invalid={Boolean(createError || createValidationError) && (!fromPeriodTrimmed || !isValidPeriodCode(fromPeriodTrimmed))}
            />
          </div>
          <div className="space-y-2">
            <Label>Periodo destino</Label>
            <Input
              value={toPeriod}
              onChange={(event) => {
                setToPeriod(event.target.value);
                if (createError) setCreateError(null);
              }}
              placeholder="2026-04"
              aria-invalid={Boolean(createError || createValidationError) && (!toPeriodTrimmed || !isValidPeriodCode(toPeriodTrimmed) || fromPeriodTrimmed >= toPeriodTrimmed)}
            />
          </div>
          <div className="space-y-2 md:col-span-2">
            <Label>Fecha límite (opcional)</Label>
            <Input
              type="datetime-local"
              value={expiresAt}
              onChange={(event) => setExpiresAt(event.target.value)}
            />
          </div>
          <div className="md:col-span-2 flex items-end">
            <Button onClick={handleCreateCampaign} disabled={!canCreateCampaign}>
              {mutating ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
              Crear campaña
            </Button>
          </div>
          <div className="md:col-span-4">
            {createError ? (
              <p className="text-sm text-destructive">{createError}</p>
            ) : createValidationError ? (
              <p className="text-xs text-muted-foreground">{createValidationError}</p>
            ) : (
              <p className="text-xs text-muted-foreground">Listo para crear la campaña con validación completa.</p>
            )}
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Campañas</CardTitle>
          <CardDescription>Selecciona una campaña para gestionar sus propuestas.</CardDescription>
        </CardHeader>
        <CardContent className="grid gap-4 md:grid-cols-3">
