        </div>
      </Section>

      {/* Events participated */}
      <Section title="Eventos">
        <div className="space-y-2">
          {MOCK_PORTAL_EVENTS.slice(0, 2).map((e) => (
            <div key={e.id} className="flex items-center gap-3 rounded-lg bg-muted/50 px-3 py-2">
