        </Link>
        <Link
          to="/portal/app/teacher/classes"
          className="flex w-full items-center gap-3 rounded-xl border border-border bg-card px-4 py-3 text-sm font-medium text-foreground transition hover:bg-muted"
        >
          <BookOpen className="h-4 w-4 text-muted-foreground" /> Profesor · Clases
          <ChevronRight className="ml-auto h-4 w-4 text-muted-foreground" />
        </Link>
        <Link
          to="/portal/app/teacher/posts/new"
          className="flex w-full items-center gap-3 rounded-xl border border-border bg-card px-4 py-3 text-sm font-medium text-foreground transition hover:bg-muted"
        >
          <PencilLine className="h-4 w-4 text-muted-foreground" /> Profesor · Publicar
          <ChevronRight className="ml-auto h-4 w-4 text-muted-foreground" />
        </Link>
        <Link to="/portal/app/preferences" className="flex w-full items-center gap-3 rounded-xl border border-border bg-card px-4 py-3 text-sm font-medium text-foreground transition hover:bg-muted">
          <Settings className="h-4 w-4 text-muted-foreground" /> Ajustes
          <ChevronRight className="ml-auto h-4 w-4 text-muted-foreground" />
        </Link>
        <Link
          to="/portal/onboarding"
          className="flex w-full items-center gap-3 rounded-xl border border-border bg-card px-4 py-3 text-sm font-medium text-destructive transition hover:bg-muted"
        >
          <LogOut className="h-4 w-4" /> Cerrar sesión
        </Link>
      </div>
    </div>
  );
}

function StatBox({ value, label }: { value: string; label: string }) {
  return (
    <div className="rounded-xl border border-border bg-card py-3">
      <p className="text-lg font-bold text-foreground">{value}</p>
      <p className="text-[10px] text-muted-foreground">{label}</p>
    </div>
  );
}

function Section({ title, linkTo, children }: { title: string; linkTo?: string; children: React.ReactNode }) {
  return (
    <div>
      <div className="mb-2 flex items-center justify-between">
        <h2 className="text-base font-semibold text-foreground">{title}</h2>
        {linkTo && (
          <Link to={linkTo} className="flex items-center gap-0.5 text-xs font-medium text-primary">
            Ver todo <ChevronRight className="h-3 w-3" />
          </Link>
        )}
      </div>
      {children}
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import { Zap, Target, CheckCircle2 } from "lucide-react";
import type { PortalAchievement, PortalStudent } from "../data/mockData";
import { ProgressCard } from "../components/ProgressCard";
import { AchievementBadge } from "../components/AchievementBadge";
import { Progress } from "@/components/ui/progress";
import { cn } from "@/lib/utils";
import { usePortalPersona } from "../services/portalPersona";
import { getStudentPortalProgress, getStudentPortalXpHistory } from "@/lib/api/studentPortal";

const categories = ["Todos", "Asistencia", "Eventos", "Hitos", "Certificaciones"] as const;
const categoryMap: Record<string, string> = {
  Todos: "all",
  Asistencia: "attendance",
  Eventos: "events",
  Hitos: "milestones",
  Certificaciones: "certifications",
};

export default function ProgressScreen() {
  const { persona } = usePortalPersona();
  const [cat, setCat] = useState("Todos");
  const [student, setStudent] = useState<PortalStudent>({
    id: "",
    name: "Alumno",
    avatar: "",
    school: "",
    styles: [],
    yearsExperience: 0,
    level: "Nivel 1",
    classesCompleted: 0,
    currentStreak: 0,
    joinDate: new Date().toISOString().slice(0, 10),
    xp: 0,
    xpToNextLevel: 1000,
  });
  const [achievements, setAchievements] = useState<PortalAchievement[]>([]);
  const [missions, setMissions] = useState<MissionUi[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (persona === "prospect") {
      return;
    }

    let cancelled = false;

    const iconForCategory = (category: PortalAchievement["category"]): string => {
      if (category === "attendance") return "🔥";
      if (category === "events") return "🎪";
      if (category === "certifications") return "📜";
      return "⭐";
    };

    const load = async () => {
      setIsLoading(true);
      setError(null);

      try {
        const [progress, xpHistory] = await Promise.all([
          getStudentPortalProgress(),
          getStudentPortalXpHistory(20, 0),
        ]);

        if (cancelled) return;

        setStudent((prev) => ({
          ...prev,
          classesCompleted: progress.classesCompleted,
          currentStreak: progress.currentStreakDays,
          level: `Nivel ${progress.levelNumber}`,
          xp: progress.xp,
          xpToNextLevel: progress.xpToNextLevel,
        }));

        setAchievements(
          progress.achievements.map((achievement) => ({
            id: achievement.id,
            name: achievement.title,
            description: achievement.earned ? "Completado" : "En progreso",
            icon: iconForCategory(achievement.category),
            earned: achievement.earned,
            category: achievement.category,
          }))
        );

        const classCount = xpHistory.items.filter((item) => item.type === "class_completed").length;
        const eventCount = xpHistory.items.filter((item) => item.type === "event_attended").length;

        setMissions([
          {
            id: "weekly-classes",
            title: "Completar 3 clases",
            description: "Sigue sumando asistencia esta semana",
            icon: "📚",
            progress: Math.min(classCount, 3),
            target: 3,
            xpReward: 50,
            completed: classCount >= 3,
          },
          {
            id: "event-mission",
            title: "Asistir a 1 evento",
            description: "Participa en eventos de tu escuela",
            icon: "🎭",
            progress: Math.min(eventCount, 1),
            target: 1,
            xpReward: 80,
            completed: eventCount >= 1,
          },
          {
            id: "attendance-rate",
            title: "Mantener 90% de asistencia",
            description: "Cuidar la regularidad mejora tu nivel",
            icon: "🎯",
            progress: Math.min(progress.attendanceRate, 90),
            target: 90,
            xpReward: 120,
            completed: progress.attendanceRate >= 90,
          },
        ]);
      } catch (loadError) {
        if (cancelled) return;
        setError(loadError instanceof Error ? loadError.message : "No se pudo cargar tu progreso");
      } finally {
        if (!cancelled) {
          setIsLoading(false);
        }
      }
    };

    void load();

    return () => {
      cancelled = true;
    };
  }, [persona]);

  if (persona === "prospect") {
    return (
      <div className="px-4 pb-24 pt-6 space-y-4">
        <h1 className="text-xl font-bold text-foreground">Progreso</h1>
        <div className="rounded-xl border border-border bg-card p-4">
          <p className="text-sm font-medium text-foreground">Tu progreso se activará al matricularte</p>
          <p className="mt-1 text-xs text-muted-foreground">
            Aquí verás asistencia, nivel, hitos y certificaciones en cuanto tengas una escuela conectada.
          </p>
        </div>
      </div>
    );
  }

  const filtered = cat === "Todos"
    ? achievements
    : achievements.filter((a) => a.category === categoryMap[cat]);

  const earned = achievements.filter((a) => a.earned).length;
  const xp = student.xp ?? 0;
  const xpNext = student.xpToNextLevel ?? 1000;
  const activeMissions = useMemo(() => missions.filter((m) => !m.completed), [missions]);
  const completedMissions = useMemo(() => missions.filter((m) => m.completed), [missions]);

  return (
    <div className="px-4 pb-24 pt-6 space-y-6">
      <h1 className="text-xl font-bold text-foreground">Progreso</h1>

      {error ? (
        <div className="rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2 text-xs text-destructive">
          {error}
        </div>
      ) : null}

      {isLoading ? (
        <div className="rounded-xl border border-border bg-card p-4 text-sm text-muted-foreground">Cargando progreso...</div>
      ) : null}

      {!isLoading ? (
        <>

      <ProgressCard student={student} />

      {/* XP bar */}
      <div className="rounded-xl border border-border bg-card p-4 space-y-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Zap className="h-4 w-4 text-primary" />
            <span className="text-sm font-semibold text-foreground">{xp} XP</span>
          </div>
          <span className="text-xs text-muted-foreground">Siguiente nivel: {xpNext} XP</span>
        </div>
        <Progress value={Math.round((xp / xpNext) * 100)} className="h-2.5" />
        <p className="text-[11px] text-muted-foreground">Tu progreso habla por ti</p>
      </div>

      {/* Missions */}
      <div>
        <div className="mb-3 flex items-center gap-2">
          <Target className="h-4 w-4 text-primary" />
          <h2 className="text-base font-semibold text-foreground">Misiones activas</h2>
        </div>
        <div className="space-y-2">
          {activeMissions.map((m) => (
            <MissionCard key={m.id} mission={m} />
          ))}
          {completedMissions.map((m) => (
            <MissionCard key={m.id} mission={m} />
          ))}
        </div>
      </div>

      {/* Achievements */}
      <div>
        <div className="mb-3 flex items-center justify-between">
          <h2 className="text-base font-semibold text-foreground">Logros</h2>
          <span className="text-xs text-muted-foreground">{earned}/{achievements.length} desbloqueados</span>
        </div>

        {/* Filters */}
        <div className="mb-4 flex gap-2 overflow-x-auto">
          {categories.map((c) => (
            <button
              key={c}
              onClick={() => setCat(c)}
              className={cn(
                "shrink-0 rounded-full px-3 py-1 text-xs font-medium transition",
                cat === c ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"
              )}
            >
              {c}
            </button>
          ))}
        </div>

        <motion.div
          key={cat}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="grid grid-cols-4 gap-4"
        >
          {filtered.map((a) => (
            <AchievementBadge key={a.id} achievement={a} size="sm" />
          ))}
        </motion.div>
      </div>
        </>
      ) : null}
    </div>
  );
}

interface MissionUi {
  id: string;
  title: string;
  description: string;
  icon: string;
  progress: number;
  target: number;
  xpReward: number;
  completed: boolean;
}

function MissionCard({ mission }: { mission: MissionUi }) {
  const pct = Math.round((mission.progress / mission.target) * 100);
  return (
    <div className={cn(
      "rounded-xl border bg-card p-3 space-y-2 transition",
      mission.completed ? "border-primary/30 bg-primary/5" : "border-border"
    )}>
      <div className="flex items-start gap-3">
        <span className="text-xl">{mission.icon}</span>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <p className={cn("text-sm font-medium", mission.completed ? "text-primary" : "text-foreground")}>
              {mission.title}
            </p>
            {mission.completed && <CheckCircle2 className="h-4 w-4 text-primary shrink-0" />}
          </div>
          <p className="text-[11px] text-muted-foreground">{mission.description}</p>
        </div>
        <span className="shrink-0 rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-bold text-primary">
          +{mission.xpReward} XP
        </span>
      </div>
      {!mission.completed && (
        <div className="space-y-1">
          <Progress value={pct} className="h-1.5" />
          <p className="text-[10px] text-muted-foreground text-right">{mission.progress}/{mission.target}</p>
        </div>
      )}
    </div>
  );
}

import { createContext, useContext, useMemo, useState, type ReactNode } from "react";
import { useSearchParams } from "react-router-dom";

export type PortalPersona = "prospect" | "enrolled" | "community";

export interface PortalPersonaOption {
  id: PortalPersona;
  label: string;
  description: string;
}

export const PORTAL_PERSONA_OPTIONS: PortalPersonaOption[] = [
  {
    id: "prospect",
    label: "Sin matricula",
    description: "Usuario con perfil creado sin escuela conectada.",
  },
  {
    id: "enrolled",
    label: "Matriculado",
    description: "Alumno activo con clases, progreso y certificaciones.",
  },
  {
    id: "community",
    label: "Comunidad",
    description: "Alumno con modulo social y eventos colaborativos activos.",
  },
];

const STORAGE_KEY = "nexa:portal:persona";

interface PortalPersonaContextValue {
  persona: PortalPersona;
  setPersona: (value: PortalPersona) => void;
  options: PortalPersonaOption[];
}

const PortalPersonaContext = createContext<PortalPersonaContextValue | null>(null);

function normalizePersona(value: string | null): PortalPersona | null {
  if (value === "prospect" || value === "enrolled" || value === "community") {
    return value;
  }
  return null;
}

function readStoredPersona(): PortalPersona {
  if (typeof window === "undefined") {
    return "enrolled";
  }

  return normalizePersona(window.localStorage.getItem(STORAGE_KEY)) ?? "enrolled";
}

export function PortalPersonaProvider({ children }: { children: ReactNode }) {
  const [searchParams, setSearchParams] = useSearchParams();
  const [persona, setPersonaState] = useState<PortalPersona>(() => {
    const fromQuery = normalizePersona(searchParams.get("persona"));
    return fromQuery ?? readStoredPersona();
  });

  const setPersona = (value: PortalPersona) => {
    setPersonaState(value);
    if (typeof window !== "undefined") {
      window.localStorage.setItem(STORAGE_KEY, value);
    }

    const next = new URLSearchParams(searchParams);
    next.set("persona", value);
    setSearchParams(next, { replace: true });
  };

  const value = useMemo<PortalPersonaContextValue>(
    () => ({
      persona,
      setPersona,
      options: PORTAL_PERSONA_OPTIONS,
    }),
    [persona]
  );

  return <PortalPersonaContext.Provider value={value}>{children}</PortalPersonaContext.Provider>;
}

export function usePortalPersona() {
  const context = useContext(PortalPersonaContext);
  if (!context) {
    throw new Error("usePortalPersona must be used within PortalPersonaProvider");
  }

  return context;
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
import { matchPath, useLocation } from "react-router-dom";
import {
  getPublicTenantBranding,
  getTenantBranding,
  type BrandingFontFamily,
  type BrandingStyleVariant,
  type TenantBranding,
} from "@/lib/api/branding";

interface BrandingTheme {
  logoUrl: string | null;
  primaryColor: string;
  secondaryColor: string;
  accentColor: string;
  fontFamily: BrandingFontFamily;
  styleVariant: BrandingStyleVariant;
}

interface BrandingContextValue {
  branding: BrandingTheme;
  isLoading: boolean;
  setPreviewBranding: (value: Partial<BrandingTheme> | null) => void;
  refreshBranding: () => Promise<void>;
}

const DEFAULT_BRANDING: BrandingTheme = {
  logoUrl: null,
  primaryColor: "#7C3AED",
  secondaryColor: "#F1F5F9",
  accentColor: "#A78BFA",
  fontFamily: "inter",
  styleVariant: "clean",
};

const fontFamilyMap: Record<BrandingFontFamily, string> = {
  inter: '"Inter", system-ui, sans-serif',
  poppins: '"Poppins", system-ui, sans-serif',
  montserrat: '"Montserrat", system-ui, sans-serif',
  lato: '"Lato", system-ui, sans-serif',
};

const styleRadiusMap: Record<BrandingStyleVariant, string> = {
  clean: "0.75rem",
  rounded: "1rem",
  bold: "0.55rem",
};

const BrandingContext = createContext<BrandingContextValue | null>(null);

function hexToHslString(hex: string): string {
  const normalized = hex.replace("#", "");
  const r = Number.parseInt(normalized.slice(0, 2), 16) / 255;
  const g = Number.parseInt(normalized.slice(2, 4), 16) / 255;
  const b = Number.parseInt(normalized.slice(4, 6), 16) / 255;

  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;

  let h = 0;
  let s = 0;
  const l = (max + min) / 2;

  if (delta !== 0) {
    s = delta / (1 - Math.abs(2 * l - 1));
    switch (max) {
      case r:
        h = ((g - b) / delta) % 6;
        break;
      case g:
        h = (b - r) / delta + 2;
        break;
      default:
        h = (r - g) / delta + 4;
        break;
    }
    h *= 60;
    if (h < 0) h += 360;
  }

  return `${Math.round(h)} ${Math.round(s * 100)}% ${Math.round(l * 100)}%`;
}

function mapApiBrandingToTheme(data: TenantBranding): BrandingTheme {
  return {
    logoUrl: data.logo_url,
    primaryColor: data.primary_color,
    secondaryColor: data.secondary_color,
    accentColor: data.accent_color || DEFAULT_BRANDING.accentColor,
    fontFamily: data.font_family,
    styleVariant: data.style_variant,
  };
}

export function BrandingProvider({ children }: { children: ReactNode }) {
  const location = useLocation();
  const [branding, setBranding] = useState<BrandingTheme>(DEFAULT_BRANDING);
  const [previewBranding, setPreviewBrandingState] = useState<Partial<BrandingTheme> | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const effectiveBranding = useMemo(
    () => ({ ...branding, ...(previewBranding || {}) }),
    [branding, previewBranding]
  );

  const publicMatch =
    matchPath("/s/:schoolSlug", location.pathname)
    || matchPath("/s/:schoolSlug/*", location.pathname);

  const isAdminRoute = location.pathname.startsWith("/admin");

  const loadBranding = useCallback(async () => {
    if (!isAdminRoute && !publicMatch) {
      setBranding(DEFAULT_BRANDING);
      return;
    }

    setIsLoading(true);
    try {
      if (publicMatch?.params.schoolSlug) {
        const publicBranding = await getPublicTenantBranding(publicMatch.params.schoolSlug);
        if (publicBranding?.branding) {
          setBranding(mapApiBrandingToTheme(publicBranding.branding));
          return;
        }
      }

      if (isAdminRoute) {
        const tenantBranding = await getTenantBranding();
        if (tenantBranding) {
          setBranding(mapApiBrandingToTheme(tenantBranding));
          return;
        }
      }

      setBranding(DEFAULT_BRANDING);
    } finally {
      setIsLoading(false);
    }
  }, [isAdminRoute, publicMatch]);

  useEffect(() => {
    void loadBranding();
  }, [loadBranding]);

  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty("--brand-primary", effectiveBranding.primaryColor);
    root.style.setProperty("--brand-secondary", effectiveBranding.secondaryColor);
    root.style.setProperty("--brand-accent", effectiveBranding.accentColor);
    root.style.setProperty("--brand-font-family", fontFamilyMap[effectiveBranding.fontFamily]);
    root.style.setProperty("--primary", hexToHslString(effectiveBranding.primaryColor));
    root.style.setProperty("--ring", hexToHslString(effectiveBranding.primaryColor));
    root.style.setProperty("--sidebar-primary", hexToHslString(effectiveBranding.primaryColor));
    root.style.setProperty("--secondary", hexToHslString(effectiveBranding.secondaryColor));
    root.style.setProperty("--accent", hexToHslString(effectiveBranding.accentColor));
    root.style.setProperty("--radius", styleRadiusMap[effectiveBranding.styleVariant]);
  }, [effectiveBranding]);

  const setPreviewBranding = useCallback((value: Partial<BrandingTheme> | null) => {
    setPreviewBrandingState(value);
  }, []);

  const value = useMemo<BrandingContextValue>(
    () => ({
      branding: effectiveBranding,
      isLoading,
      setPreviewBranding,
      refreshBranding: loadBranding,
    }),
    [effectiveBranding, isLoading, loadBranding, setPreviewBranding]
  );

  return <BrandingContext.Provider value={value}>{children}</BrandingContext.Provider>;
}

export function useBranding() {
  const context = useContext(BrandingContext);
  if (!context) {
    throw new Error("useBranding must be used inside BrandingProvider");
  }
  return context;
}

export function defaultBrandingTheme(): BrandingTheme {
  return { ...DEFAULT_BRANDING };
}
